#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StepOutcome {
    Running,
    Halted,
    Attention,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BatchStepStop {
    Halted,
    Attention,
    Error(StepError),
}

impl From<StepError> for BatchStepStop {
    #[inline(always)]
    fn from(error: StepError) -> Self {
        Self::Error(error)
    }
}

#[inline(always)]
fn batch_step_result(result: Result<StepOutcome, StepError>) -> Result<(), BatchStepStop> {
    match result {
        Ok(StepOutcome::Running) => Ok(()),
        Ok(StepOutcome::Halted) => Err(BatchStepStop::Halted),
        Ok(StepOutcome::Attention) => Err(BatchStepStop::Attention),
        Err(error) => Err(error.into()),
    }
}

impl From<Fault> for BatchStepStop {
    #[inline(always)]
    fn from(fault: Fault) -> Self {
        Self::Error(fault.into())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BatchStop {
    Budget,
    Attention {
        instruction_step: u64,
        was_interruptible: bool,
    },
    Step {
        instruction_step: u64,
        instruction_eip: u32,
        was_interruptible: bool,
        reason: BatchStepStop,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BatchResult {
    pub ran: u64,
    pub stop: BatchStop,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StepError {
    FaultOutOfRange {
        addr: PhysAddr,
    },
    FaultMmio {
        addr: PhysAddr,
    },
    FaultIoUnhandled {
        port: u16,
    },
    PageFault(mmu::PageFault),
    UnsupportedOpcode {
        eip: u32,
        opcode: u8,
    },
    UnsupportedOpcode2 {
        eip: u32,
        opcode: u8,
    },
    UnsupportedModRm {
        eip: u32,
        opcode: u8,
        modrm: u8,
    },
    InvalidOpcode {
        eip: u32,
    },
    SoftwareInterrupt {
        vector: u8,
        return_eip: u32,
        fault_eip: u32,
    },
    DivideError {
        eip: u32,
    },
    DeviceNotAvailable {
        eip: u32,
    },
    BoundRangeExceeded {
        eip: u32,
    },
    GeneralProtection {
        eip: u32,
        code: u32,
    },
    InvalidTss {
        eip: u32,
        code: u32,
    },
    StackFault {
        eip: u32,
        code: u32,
    },
    SegmentNotPresent {
        eip: u32,
        code: u32,
    },
    /// A guest fault prevented entry to #DF. A PC resets on CPU shutdown;
    /// this is not an unimplemented opcode or a host memory error.
    TripleFault {
        eip: u32,
        vector: u8,
        code: u32,
    },
    /// Paging fault after a hardware task switch committed its new EIP.
    /// Restart belongs to that task, not to the CALL/INT/IRET instruction.
    TaskSwitchPageFault {
        eip: u32,
        page: mmu::PageFault,
    },
    /// #TS/#NP/#SS/#GP after the new task was committed. Its EIP must not
    /// be replaced by the address of the outgoing CALL/JMP/INT/IRET.
    TaskSwitchFault {
        eip: u32,
        vector: u8,
        code: u32,
    },
    /// The task switch completed. Deliver #DB before its first instruction;
    /// this is a new event, not a fault while entering the previous event.
    TaskSwitchTrap {
        eip: u32,
    },
    MemOutOfRange {
        addr: PhysAddr,
    },
    MemMmio {
        addr: PhysAddr,
    },
    MemIoUnhandled {
        port: u16,
    },
}

pub fn deliver_external_interrupt<B: Bus>(
    cpu: &mut Cpu,
    bus: &mut B,
    vector: u8,
    return_eip: u32,
) -> Result<(), StepError> {
    deliver_interrupt_event(
        cpu,
        bus,
        vector,
        return_eip,
        None,
        EventKind::External,
        return_eip,
    )
}

pub fn deliver_exception<B: Bus>(
    cpu: &mut Cpu,
    bus: &mut B,
    vector: u8,
    error_code: Option<u32>,
    fault_eip: u32,
) -> Result<(), StepError> {
    deliver_interrupt_event(
        cpu,
        bus,
        vector,
        fault_eip,
        error_code,
        EventKind::Exception,
        fault_eip,
    )
}

pub fn deliver_software_interrupt_event<B: Bus>(
    cpu: &mut Cpu,
    bus: &mut B,
    vector: u8,
    return_eip: u32,
    fault_eip: u32,
) -> Result<(), StepError> {
    deliver_interrupt_event(
        cpu,
        bus,
        vector,
        return_eip,
        None,
        EventKind::Software,
        fault_eip,
    )
}

#[derive(Clone, Copy, Eq, PartialEq)]
enum EventKind {
    External,
    Software,
    Exception,
}

impl From<Fault> for StepError {
    fn from(value: Fault) -> Self {
        match value {
            Fault::Mem(MemError::OutOfRange { addr }) => Self::FaultOutOfRange { addr },
            Fault::Mem(MemError::Mmio { addr }) => Self::FaultMmio { addr },
            Fault::Mem(MemError::IoUnhandled { port }) => Self::FaultIoUnhandled { port },
            Fault::Page(page) => Self::PageFault(page),
        }
    }
}

impl From<MemError> for StepError {
    fn from(value: MemError) -> Self {
        match value {
            MemError::OutOfRange { addr } => Self::MemOutOfRange { addr },
            MemError::Mmio { addr } => Self::MemMmio { addr },
            MemError::IoUnhandled { port } => Self::MemIoUnhandled { port },
        }
    }
}

impl StepError {
    /// Decode/operand helpers may still hold the advanced fetch cursor.
    /// The execution boundary owns the original instruction address, as do
    /// tiny386's ip/next_ip and v86's previous_ip. Attach it only on a fault
    /// exit; no extra state or work is needed in the successful instruction.
    /// Explicit committed-task results retain their separate restart point.
    #[cold]
    fn at_instruction(mut self, instruction_eip: u32) -> Self {
        match &mut self {
            Self::DivideError { eip }
            | Self::BoundRangeExceeded { eip }
            | Self::InvalidOpcode { eip }
            | Self::DeviceNotAvailable { eip }
            | Self::GeneralProtection { eip, .. }
            | Self::InvalidTss { eip, .. }
            | Self::StackFault { eip, .. }
            | Self::SegmentNotPresent { eip, .. } => *eip = instruction_eip,
            _ => {}
        }
        self
    }

    /// Only architecturally defined guest faults belong in the exception
    /// chain. Bus implementation errors and unsupported instructions retain
    /// their diagnostic identity instead of becoming a fabricated #GP/#UD.
    pub(crate) fn exception(self, instruction_eip: u32) -> Option<(u8, Option<u32>, u32)> {
        Some(match self {
            Self::PageFault(page) => (14, Some(page.code), instruction_eip),
            Self::TaskSwitchPageFault { eip, page } => (14, Some(page.code), eip),
            Self::TaskSwitchFault { eip, vector, code } => (vector, Some(code), eip),
            Self::TaskSwitchTrap { eip } => (1, None, eip),
            Self::DivideError { eip } => (0, None, eip),
            Self::BoundRangeExceeded { eip } => (5, None, eip),
            Self::InvalidOpcode { eip } => (6, None, eip),
            Self::DeviceNotAvailable { eip } => (7, None, eip),
            Self::InvalidTss { eip, code } => (10, Some(code), eip),
            Self::SegmentNotPresent { eip, code } => (11, Some(code), eip),
            Self::StackFault { eip, code } => (12, Some(code), eip),
            Self::GeneralProtection { eip, code } => (13, Some(code), eip),
            _ => return None,
        })
    }

    pub const fn page_fault(self) -> Option<mmu::PageFault> {
        match self {
            Self::PageFault(page) | Self::TaskSwitchPageFault { page, .. } => Some(page),
            _ => None,
        }
    }

    pub const fn fault_mem_error(self) -> Option<MemError> {
        match self {
            Self::FaultOutOfRange { addr } => Some(MemError::OutOfRange { addr }),
            Self::FaultMmio { addr } => Some(MemError::Mmio { addr }),
            Self::FaultIoUnhandled { port } => Some(MemError::IoUnhandled { port }),
            _ => None,
        }
    }

    pub const fn direct_mem_error(self) -> Option<MemError> {
        match self {
            Self::MemOutOfRange { addr } => Some(MemError::OutOfRange { addr }),
            Self::MemMmio { addr } => Some(MemError::Mmio { addr }),
            Self::MemIoUnhandled { port } => Some(MemError::IoUnhandled { port }),
            _ => None,
        }
    }

    pub const fn mem_error(self) -> Option<MemError> {
        if let Some(err) = self.fault_mem_error() {
            Some(err)
        } else {
            self.direct_mem_error()
        }
    }
}

pub struct Interpreter;

#[derive(Clone, Copy)]
enum Prefix {
    None,
    Rep,
    Repne,
}

const PREFIX_NONE: u8 = 0;
const PREFIX_SEG_ES: u8 = 1;
const PREFIX_SEG_CS: u8 = 2;
const PREFIX_SEG_SS: u8 = 3;
const PREFIX_SEG_DS: u8 = 4;
const PREFIX_SEG_FS: u8 = 5;
const PREFIX_SEG_GS: u8 = 6;
const PREFIX_LOCK: u8 = 7;
const PREFIX_REPNE: u8 = 8;
const PREFIX_REP: u8 = 9;
const PREFIX_OPERAND_SIZE: u8 = 10;
const PREFIX_ADDRESS_SIZE: u8 = 11;

const OPCODE_PREFIX_CLASS: [u8; 256] = build_opcode_prefix_class();

const fn build_opcode_prefix_class() -> [u8; 256] {
    let mut table = [PREFIX_NONE; 256];
    table[0x26] = PREFIX_SEG_ES;
    table[0x2e] = PREFIX_SEG_CS;
    table[0x36] = PREFIX_SEG_SS;
    table[0x3e] = PREFIX_SEG_DS;
    table[0x64] = PREFIX_SEG_FS;
    table[0x65] = PREFIX_SEG_GS;
    table[0xf0] = PREFIX_LOCK;
    table[0xf2] = PREFIX_REPNE;
    table[0xf3] = PREFIX_REP;
    table[0x66] = PREFIX_OPERAND_SIZE;
    table[0x67] = PREFIX_ADDRESS_SIZE;
    table
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MemAddr {
    seg: SegmentReg,
    offset: u32,
}

impl MemAddr {
    #[inline]
    const fn new(seg: SegmentReg, offset: u32) -> Self {
        Self { seg, offset }
    }

    #[inline]
    fn add(self, bytes: u32) -> Self {
        Self {
            seg: self.seg,
            offset: self.offset.wrapping_add(bytes),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Rm32 {
    Reg(Reg32),
    Mem(MemAddr),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Rm8 {
    Reg(u8),
    Mem(MemAddr),
}

