                            let imm = step_try!(fetch_u8(cpu, bus)) as i8 as i32 as u32;
                            step_try!(lockable_group1_rm32(lock_prefix, dst, op, start_eip));
                            step_try!(group_81(cpu, bus, dst, op, imm));
