                            let old_dst = step_try!(read_rm16(cpu, bus, dst));
                            let old_reg = read_reg16(cpu, reg as u8);
                            step_try!(write_rm16(cpu, bus, dst, old_reg));
                            write_reg16(cpu, reg as u8, old_dst);
