    #[test]
    fn batch_tsc_write_read_wrap_and_halt_keep_exact_observation_order() {
        let mut cpu = flat_cpu();
        let mut ram = Ram::new();
        let code = [
            0xb9, 0x10, 0, 0, 0, // mov ecx, MSR_TSC
            0xb8, 0xfe, 0xff, 0xff, 0xff, // mov eax, -2
            0xba, 0xff, 0xff, 0xff, 0xff, // mov edx, -1
            0x0f, 0x30, // wrmsr: TSC := u64::MAX - 1
            0x0f, 0x31, // rdtsc: u64::MAX
            0x89, 0xc3, // mov ebx, eax: TSC wraps to 0
            0x89, 0xd6, // mov esi, edx: TSC = 1
            0x0f, 0x32, // rdmsr: TSC = 2
            0xf4, // hlt: TSC = 3
            0xf0, 0x90, // invalid LOCK NOP, on resumed execution
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        let result = Interpreter::run_batch(&mut cpu, &mut ram, 100, 20);
        assert_eq!(result.ran, 9);
        assert_eq!((cpu.reg(Reg32::Eax), cpu.reg(Reg32::Edx)), (2, 0));
        assert_eq!(
            (cpu.reg(Reg32::Ebx), cpu.reg(Reg32::Esi)),
            (u32::MAX, u32::MAX)
        );
        // The bus sees pre-instruction time; architectural reads see the tick.
        assert_eq!((ram.instruction_tsc, cpu.tsc()), (2, 3));
        assert_eq!(ram.instruction_step, 108);

        let result = Interpreter::run_batch(&mut cpu, &mut ram, 109, 0);
        assert_eq!(result.ran, 0);
        assert_eq!((ram.instruction_tsc, cpu.tsc()), (2, 3));
        let result = Interpreter::run_batch(&mut cpu, &mut ram, 109, 20);
        assert_eq!(result.ran, 1); // A halted poll does not advance TSC.
        assert_eq!((ram.instruction_tsc, cpu.tsc()), (3, 3));
        cpu.halted = false;
        let result = Interpreter::run_batch(&mut cpu, &mut ram, 110, 20);
        assert_eq!(result.ran, 1); // A faulting attempt does advance it.
        assert!(matches!(
            result.stop,
            BatchStop::Step {
                reason: BatchStepStop::Error(_),
                ..
            }
        ));
        assert_eq!((ram.instruction_tsc, cpu.tsc()), (3, 4));
    }

    #[test]
    fn batch_preserves_absolute_steps_across_counter_wrap_and_large_budgets() {
        // Loop bookkeeping must not narrow the caller's absolute step or return
        // Budget just because a requested budget exceeds one native RV32 word.
        for start in [u64::from(u32::MAX) - 1, u64::MAX - 1] {
            for budget in [3, u64::from(u32::MAX) + 17, u64::MAX] {
                let mut cpu = flat_cpu();
                let mut ram = Ram::new();
                cpu.set_tsc(u64::MAX - 1);
                ram.data[..3].copy_from_slice(&[0x90, 0x90, 0xf4]);
                let result = Interpreter::run_batch(&mut cpu, &mut ram, start, budget);
                assert_eq!(
                    result,
                    BatchResult {
                        ran: 3,
                        stop: BatchStop::Step {
                            instruction_step: start.wrapping_add(2),
                            instruction_eip: 2,
                            was_interruptible: false,
                            reason: BatchStepStop::Halted,
                        },
                    }
                );
                assert_eq!(ram.instruction_step, start.wrapping_add(2));
                assert_eq!((ram.instruction_count, cpu.tsc(), cpu.eip), (3, 1, 3));
            }

            let mut cpu = flat_cpu();
            let mut ram = Ram::new();
            ram.data[..4].copy_from_slice(&[0x90, 0x90, 0xf0, 0x90]);
            assert_eq!(
                Interpreter::run_batch(&mut cpu, &mut ram, start, 2),
                BatchResult {
                    ran: 2,
                    stop: BatchStop::Budget,
                }
            );
            assert_eq!(ram.instruction_step, start.wrapping_add(1));
            let result = Interpreter::run_batch(&mut cpu, &mut ram, start.wrapping_add(2), 4);
            assert_eq!(
                result,
                BatchResult {
                    ran: 1,
                    stop: BatchStop::Step {
                        instruction_step: start.wrapping_add(2),
                        instruction_eip: 2,
                        was_interruptible: false,
                        reason: BatchStepStop::Error(StepError::InvalidOpcode { eip: 2 }),
                    },
                }
            );
            assert_eq!(ram.instruction_step, start.wrapping_add(2));
        }
    }

