    #[test]
    fn nonpaging_control_bits_preserve_translations_but_wp_and_cr3_expire_them() {
        let mut cpu = flat_cpu();
        let mut ram = Ram::new();
        ram.cache_data = true;
        map_test_page(&mut ram, 0, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
        map_test_page(&mut ram, 0x3000, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
        enable_test_paging(&mut cpu);
        ram.write_u32(0x100, 0x1111_1111);
        ram.write_u32(0x3100, 0x2222_2222);
        let load = |cpu: &mut Cpu, ram: &mut Ram| {
            mmu::read_linear_u32(cpu, ram, LinearAddr(0x3100), AccessKind::Read).unwrap()
        };
        assert_eq!(load(&mut cpu, &mut ram), 0x1111_1111);
        ram.write_u32(0x200c, 0x3000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
        let cr0 = cpu.cr0;
        write_control_register(&mut cpu, &mut ram, 0, cr0 | CR0_TS | CR0_MP, 0).unwrap();
        write_control_register(&mut cpu, &mut ram, 4, CR4_TSD | CR4_DE, 0).unwrap();
        assert_eq!(load(&mut cpu, &mut ram), 0x1111_1111);
        write_control_register(&mut cpu, &mut ram, 0, cr0 | crate::x86::cpu::CR0_WP, 0).unwrap();
        assert_eq!(load(&mut cpu, &mut ram), 0x2222_2222);
        ram.write_u32(0x200c, TEST_PTE_PRESENT | TEST_PTE_WRITE);
        let cr3 = cpu.cr3;
        write_control_register(&mut cpu, &mut ram, 3, cr3, 0).unwrap();
        assert_eq!(load(&mut cpu, &mut ram), 0x1111_1111);
    }

