        assert_flag(&cpu, EFLAGS_AF, true);
        assert_flag(&cpu, EFLAGS_CF, false);
        assert_flag(&cpu, EFLAGS_OF, false);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xeeee_0100);
