        assert_eq!(cpu.reg(Reg32::Eax), 0x0000_0010);
        assert_flag(&cpu, EFLAGS_AF, true);
        assert_flag(&cpu, EFLAGS_CF, false);
        assert_flag(&cpu, EFLAGS_OF, false);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0x0000_000f);
        cpu.set_flag(EFLAGS_CF, true);
        run_instruction(&mut cpu, &[0x15, 0x00, 0x00, 0x00, 0x00]); // adc eax, 0
        assert_eq!(cpu.reg(Reg32::Eax), 0x0000_0010);
        assert_flag(&cpu, EFLAGS_AF, true);
        assert_flag(&cpu, EFLAGS_CF, false);
        assert_flag(&cpu, EFLAGS_OF, false);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0x0000_0010);
        run_instruction(&mut cpu, &[0x2d, 0x01, 0x00, 0x00, 0x00]); // sub eax, 1
        assert_eq!(cpu.reg(Reg32::Eax), 0x0000_000f);
        assert_flag(&cpu, EFLAGS_AF, true);
        assert_flag(&cpu, EFLAGS_CF, false);
        assert_flag(&cpu, EFLAGS_OF, false);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0x0000_0010);
        cpu.set_flag(EFLAGS_CF, true);
        run_instruction(&mut cpu, &[0x1d, 0x00, 0x00, 0x00, 0x00]); // sbb eax, 0
        assert_eq!(cpu.reg(Reg32::Eax), 0x0000_000f);
        assert_flag(&cpu, EFLAGS_AF, true);
        assert_flag(&cpu, EFLAGS_CF, false);
        assert_flag(&cpu, EFLAGS_OF, false);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0x0000_0010);
        run_instruction(&mut cpu, &[0x3d, 0x01, 0x00, 0x00, 0x00]); // cmp eax, 1
