    #[test]
    fn address16_modrm_base_index_forms_use_word_registers_and_default_segments() {
        let cases = [
            (0, 0x0114, 0x80),
            (1, 0x0118, 0x81),
            (2, 0x0224, 0x82),
            (3, 0x0228, 0x83),
            (4, 0x0104, 0x84),
            (5, 0x0108, 0x85),
            (6, 0x0223, 0x86),
            (7, 0x0110, 0x87),
        ];

        for (rm, linear, expected) in cases {
            let mut ram = Ram::new();
            if rm == 6 {
                ram.data[..5].copy_from_slice(&[
                    0x67, 0x8a, 0x46, 0x03, 0xf4, // mov al, [bp+3]; hlt
                ]);
            } else {
                ram.data[..4].copy_from_slice(&[
                    0x67, 0x8a, rm, 0xf4, // mov al, [address16 rm]; hlt
                ]);
            }
            ram.data[linear] = expected;

            let mut cpu = flat_cpu();
            cpu.set_seg_cache(
                SegmentReg::Ds,
                SegmentCache {
                    base: 0x0100,
                    ..cpu.seg(SegmentReg::Ds)
                },
            );
            cpu.set_seg_cache(
                SegmentReg::Ss,
                SegmentCache {
                    base: 0x0200,
                    ..cpu.seg(SegmentReg::Ss)
                },
            );
            cpu.set_reg(Reg32::Ebx, 0xaaaa_0010);
            cpu.set_reg(Reg32::Ebp, 0xbbbb_0020);
            cpu.set_reg(Reg32::Esi, 0xcccc_0004);
            cpu.set_reg(Reg32::Edi, 0xdddd_0008);

            step_running(&mut cpu, &mut ram);
            assert_eq!(
                read_reg8(&cpu, Reg32::Eax as u8),
                expected,
                "rm {rm} should read expected address16 byte"
            );
        }
    }

