    #[test]
    fn cmovcc_word_and_dword_register_sources_preserve_flags() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x66, 0x0f, 0x44, 0xc3, // cmove ax, bx
            0x0f, 0x45, 0xca, // cmovne ecx, edx
        ]);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_1111);
        cpu.set_reg(Reg32::Ebx, 0xbbbb_2222);
        cpu.set_reg(Reg32::Ecx, 0xcccc_3333);
        cpu.set_reg(Reg32::Edx, 0xdddd_4444);
        cpu.eflags = 0x0000_0002
            | EFLAGS_CF
            | crate::x86::cpu::EFLAGS_ZF
            | crate::x86::cpu::EFLAGS_SF
            | EFLAGS_OF;
        let flags = cpu.eflags;

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xaaaa_2222);
        assert_eq!(cpu.eflags, flags);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Ecx), 0xcccc_3333);
        assert_eq!(cpu.eflags, flags);
    }

