    #[test]
    fn movzx_movsx_operand32_extend_to_full_registers() {
        let mut ram = Ram::new();
        ram.data[..20].copy_from_slice(&[
            0x0f, 0xb6, 0xc3, // movzx eax, bl
            0x0f, 0xb7, 0x0d, 0x80, 0x00, 0x00, 0x00, // movzx ecx, word [0x80]
            0x0f, 0xbe, 0xd3, // movsx edx, bl
            0x0f, 0xbf, 0x35, 0x82, 0x00, 0x00, 0x00, // movsx esi, word [0x82]
        ]);
        ram.write_u16(0x80, 0xf234);
        ram.write_u16(0x82, 0x8001);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_aaaa);
        cpu.set_reg(Reg32::Ebx, 0xbbbb_0080);
        cpu.set_reg(Reg32::Ecx, 0xcccc_cccc);
        cpu.set_reg(Reg32::Edx, 0xdddd_dddd);
        cpu.set_reg(Reg32::Esi, 0xeeee_eeee);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0x0000_0080);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Ecx), 0x0000_f234);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Edx), 0xffff_ff80);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Esi), 0xffff_8001);
    }

