    #[test]
    fn bound_dword_accepts_signed_values_inside_inclusive_bounds() {
        let mut ram = Ram::new();
        ram.data[..12].copy_from_slice(&[
            0x62, 0x05, 0x80, 0x00, 0x00, 0x00, // bound eax, [0x80]
            0x62, 0x0d, 0x88, 0x00, 0x00, 0x00, // bound ecx, [0x88]
        ]);
        ram.write_u32(0x80, (-10i32) as u32);
        ram.write_u32(0x84, 5);
        ram.write_u32(0x88, 0);
        ram.write_u32(0x8c, 100);

        let mut cpu = flat_cpu();
        cpu.eflags = EFLAGS_CF | EFLAGS_OF | EFLAGS_AF | EFLAGS_ZF | 0x0000_0002;
        cpu.set_reg(Reg32::Eax, (-2i32) as u32);
        cpu.set_reg(Reg32::Ecx, 100);
        let flags = cpu.eflags;

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 6);
        assert_eq!(cpu.eflags, flags);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 12);
        assert_eq!(cpu.eflags, flags);
        assert_eq!(cpu.reg(Reg32::Eax), (-2i32) as u32);
        assert_eq!(cpu.reg(Reg32::Ecx), 100);
    }

