    #[test]
    fn lock_prefix_xchg_allows_memory_and_rejects_register_forms() {
        let mut ram = Ram::new();
        ram.data[..15].copy_from_slice(&[
            0xf0, 0x86, 0x05, 0x50, 0x01, 0x00, 0x00, // lock xchg [0x150], al
            0xf0, 0x87, 0x1d, 0x54, 0x01, 0x00, 0x00, // lock xchg [0x154], ebx
            0xf4,
        ]);
        ram.data[0x150] = 0x12;
        ram.write_u32(0x154, 0xaabb_ccdd);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_0034);
        cpu.set_reg(Reg32::Ebx, 0x1122_3344);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 7);
        assert_eq!(ram.data[0x150], 0x34);
        assert_eq!(cpu.reg(Reg32::Eax), 0xaaaa_0012);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 14);
        assert_eq!(ram.read_u32(0x154), 0x1122_3344);
        assert_eq!(cpu.reg(Reg32::Ebx), 0xaabb_ccdd);

        let mut reg_ram = Ram::new();
        reg_ram.data[..3].copy_from_slice(&[
            0xf0, 0x87, 0xc3, // lock xchg ebx, eax
        ]);
        let mut reg_cpu = flat_cpu();
        reg_cpu.set_reg(Reg32::Eax, 1);
        reg_cpu.set_reg(Reg32::Ebx, 2);
        step_ud(&mut reg_cpu, &mut reg_ram, 0);
        assert_eq!(reg_cpu.eip, 3);
        assert_eq!(reg_cpu.reg(Reg32::Eax), 1);
        assert_eq!(reg_cpu.reg(Reg32::Ebx), 2);
    }

    #[test]
    fn lock_prefix_group3_allows_not_neg_memory_only() {
        let mut ram = Ram::new();
        ram.data[..22].copy_from_slice(&[
            0xf0, 0xf6, 0x15, 0x60, 0x01, 0x00, 0x00, // lock not byte [0x160]
            0xf0, 0x66, 0xf7, 0x15, 0x62, 0x01, 0x00, 0x00, // lock not word [0x162]
            0xf0, 0xf7, 0x1d, 0x64, 0x01, 0x00, 0x00, // lock neg dword [0x164]
        ]);
        ram.data[0x160] = 0x55;
        ram.write_u16(0x162, 0x00ff);
        ram.write_u32(0x164, 3);

        let mut cpu = flat_cpu();
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 7);
        assert_eq!(ram.data[0x160], 0xaa);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 15);
        assert_eq!(ram.read_u16(0x162), 0xff00);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 22);
        assert_eq!(ram.read_u32(0x164), (!3u32).wrapping_add(1));
        assert_flag(&cpu, EFLAGS_CF, true);
    }

