    #[test]
    fn lock_prefix_group4_and_group5_allow_memory_inc_dec_only() {
        let mut ram = Ram::new();
        ram.data[..14].copy_from_slice(&[
            0xf0, 0xfe, 0x05, 0x80, 0x01, 0x00, 0x00, // lock inc byte [0x180]
            0xf0, 0xff, 0x0d, 0x84, 0x01, 0x00, 0x00, // lock dec dword [0x184]
        ]);
        ram.data[0x180] = 0xff;
        ram.write_u32(0x184, 0);

        let mut cpu = flat_cpu();
        cpu.set_flag(EFLAGS_CF, true);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 7);
        assert_eq!(ram.data[0x180], 0);
        assert_flag(&cpu, EFLAGS_CF, true);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 14);
        assert_eq!(ram.read_u32(0x184), 0xffff_ffff);
        assert_flag(&cpu, EFLAGS_CF, true);

        let mut call_ram = Ram::new();
        call_ram.data[..3].copy_from_slice(&[
            0xf0, 0xff, 0xd0, // lock call eax
        ]);
        let mut call_cpu = flat_cpu();
        call_cpu.set_reg(Reg32::Eax, 0x1234);
        call_cpu.set_reg(Reg32::Esp, 0x100);
        step_ud(&mut call_cpu, &mut call_ram, 0);
        assert_eq!(call_cpu.eip, 3);
        assert_eq!(call_cpu.reg(Reg32::Esp), 0x100);

        let mut inc_reg_ram = Ram::new();
        inc_reg_ram.data[..3].copy_from_slice(&[
            0xf0, 0xfe, 0xc0, // lock inc al
        ]);
        let mut inc_reg_cpu = flat_cpu();
        inc_reg_cpu.set_reg(Reg32::Eax, 0x1234_00ff);
        step_ud(&mut inc_reg_cpu, &mut inc_reg_ram, 0);
        assert_eq!(inc_reg_cpu.eip, 3);
        assert_eq!(inc_reg_cpu.reg(Reg32::Eax), 0x1234_00ff);
    }

    #[test]
    fn lock_prefix_cmpxchg_and_xadd_allow_memory_operands() {
        let mut ram = Ram::new();
        ram.data[..25].copy_from_slice(&[
            0xf0, 0x0f, 0xb0, 0x0d, 0x90, 0x01, 0x00, 0x00, // lock cmpxchg [0x190], cl
            0xf0, 0x66, 0x0f, 0xc1, 0x15, 0x92, 0x01, 0x00, 0x00, // lock xadd [0x192], dx
            0xf0, 0x0f, 0xc1, 0x1d, 0x94, 0x01, 0x00, 0x00, // lock xadd [0x194], ebx
        ]);
        ram.data[0x190] = 0x42;
        ram.write_u16(0x192, 5);
        ram.write_u32(0x194, 7);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_0042);
        cpu.set_reg(Reg32::Ecx, 0xbbbb_0099);
        cpu.set_reg(Reg32::Edx, 0xcccc_0003);
        cpu.set_reg(Reg32::Ebx, 0x0000_0004);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 8);
        assert_eq!(ram.data[0x190], 0x99);
        assert_flag(&cpu, EFLAGS_ZF, true);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 17);
        assert_eq!(ram.read_u16(0x192), 8);
        assert_eq!(cpu.reg(Reg32::Edx), 0xcccc_0005);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 25);
        assert_eq!(ram.read_u32(0x194), 11);
        assert_eq!(cpu.reg(Reg32::Ebx), 7);
    }

