    #[test]
    fn lock_prefix_bit_modify_allows_memory_bts_btr_btc_but_not_bt() {
        let mut ram = Ram::new();
        ram.data[..25].copy_from_slice(&[
            0xf0, 0x0f, 0xab, 0x1d, 0xb0, 0x01, 0x00, 0x00, // lock bts [0x1b0], ebx
            0xf0, 0x0f, 0xba, 0x35, 0xb4, 0x01, 0x00, 0x00, 0x01, // lock btr [0x1b4], 1
            0xf0, 0x0f, 0xbb, 0x0d, 0xb8, 0x01, 0x00, 0x00, // lock btc [0x1b8], ecx
        ]);
        ram.write_u32(0x1b0, 0);
        ram.write_u32(0x1b4, 0xffff_ffff);
        ram.write_u32(0x1b8, 0);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Ebx, 3);
        cpu.set_reg(Reg32::Ecx, 7);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 8);
        assert_eq!(ram.read_u32(0x1b0), 1 << 3);
        assert_flag(&cpu, EFLAGS_CF, false);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 17);
        assert_eq!(ram.read_u32(0x1b4), 0xffff_fffd);
        assert_flag(&cpu, EFLAGS_CF, true);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 25);
        assert_eq!(ram.read_u32(0x1b8), 1 << 7);
        assert_flag(&cpu, EFLAGS_CF, false);

        let mut bt_ram = Ram::new();
        bt_ram.data[..8].copy_from_slice(&[
            0xf0, 0x0f, 0xa3, 0x1d, 0xc0, 0x01, 0x00, 0x00, // lock bt [0x1c0], ebx
        ]);
        bt_ram.write_u32(0x1c0, 0xffff_ffff);
        let mut bt_cpu = flat_cpu();
        bt_cpu.set_reg(Reg32::Ebx, 0);
        step_ud(&mut bt_cpu, &mut bt_ram, 0);
        assert_eq!(bt_cpu.eip, 8);
        assert_eq!(bt_ram.read_u32(0x1c0), 0xffff_ffff);
    }

