    #[test]
    fn lock_prefix_non_lockable_opcodes_raise_invalid_opcode() {
        let cases: &[&[u8]] = &[
            &[0xf0, 0x90],                               // lock nop
            &[0xf0, 0x50],                               // lock push eax
            &[0xf0, 0x89, 0x05, 0xd0, 0x01, 0x00, 0x00], // lock mov [0x1d0], eax
            &[0xf0, 0x0f, 0xaf, 0xc3],                   // lock imul eax, ebx
        ];

        for code in cases {
            let mut ram = Ram::new();
            ram.data[..code.len()].copy_from_slice(code);
            ram.write_u32(0x1d0, 0xaabb_ccdd);
            let mut cpu = flat_cpu();
            cpu.set_reg(Reg32::Eax, 0x1122_3344);
            cpu.set_reg(Reg32::Ebx, 0x5566_7788);

            step_ud(&mut cpu, &mut ram, 0);

            assert_eq!(cpu.reg(Reg32::Eax), 0x1122_3344);
            assert_eq!(cpu.reg(Reg32::Ebx), 0x5566_7788);
            assert_eq!(ram.read_u32(0x1d0), 0xaabb_ccdd);
        }
    }

    #[test]
    fn double_shift_operand16_immediate_counts_preserve_high_halves() {
        let mut ram = Ram::new();
        ram.data[..10].copy_from_slice(&[
            0x66, 0x0f, 0xa4, 0xd8, 0x04, // shld ax, bx, 4
            0x66, 0x0f, 0xac, 0xd8, 0x04, // shrd ax, bx, 4
        ]);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_1234);
        cpu.set_reg(Reg32::Ebx, 0xbbbb_f000);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xaaaa_234f);
        assert!(cpu.flag(EFLAGS_CF));
        assert!(!cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        assert!(!cpu.flag(crate::x86::cpu::EFLAGS_SF));

        cpu.set_reg(Reg32::Eax, 0xcccc_1234);
        cpu.set_reg(Reg32::Ebx, 0xdddd_000f);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xcccc_f123);
        assert!(!cpu.flag(EFLAGS_CF));
        assert!(!cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_SF));
    }

    #[test]
    fn double_shift_operand16_cl_count_above_word_size_matches_reference_shape() {
        let mut ram = Ram::new();
        ram.data[..8].copy_from_slice(&[
            0x66, 0x0f, 0xa5, 0xd8, // shld ax, bx, cl
            0x66, 0x0f, 0xad, 0xd8, // shrd ax, bx, cl
        ]);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xaaaa_1234);
        cpu.set_reg(Reg32::Ebx, 0xbbbb_abcd);
        cpu.set_reg(Reg32::Ecx, 20);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xaaaa_bcd1);
        assert!(!cpu.flag(EFLAGS_CF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_SF));

        cpu.set_reg(Reg32::Eax, 0xcccc_1234);
        cpu.set_reg(Reg32::Ebx, 0xdddd_abcd);
        cpu.set_reg(Reg32::Ecx, 20);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xcccc_4abc);
        assert!(cpu.flag(EFLAGS_CF));
        assert!(!cpu.flag(crate::x86::cpu::EFLAGS_SF));
    }

