    #[test]
    fn group2_rcl_rcr_byte_use_carry_without_touching_szp() {
        let mut ram = Ram::new();
        ram.data[..6].copy_from_slice(&[
            0xc0, 0xd0, 0x01, // rcl al, 1
            0xc0, 0xd8, 0x01, // rcr al, 1
        ]);

        let mut cpu = flat_cpu();
        write_reg8(&mut cpu, Reg32::Eax as u8, 0x80);
        cpu.eflags = 0x0000_0002
            | EFLAGS_CF
            | crate::x86::cpu::EFLAGS_ZF
            | crate::x86::cpu::EFLAGS_SF
            | crate::x86::cpu::EFLAGS_PF;

        step_running(&mut cpu, &mut ram);
        assert_eq!(read_reg8(&cpu, Reg32::Eax as u8), 0x01);
        assert!(cpu.flag(EFLAGS_CF));
        assert!(cpu.flag(EFLAGS_OF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_SF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_PF));

        step_running(&mut cpu, &mut ram);
        assert_eq!(read_reg8(&cpu, Reg32::Eax as u8), 0x80);
        assert!(cpu.flag(EFLAGS_CF));
        assert!(cpu.flag(EFLAGS_OF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_SF));
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_PF));
    }

