    #[test]
    fn protected_mode_switch_preserves_real_mode_null_data_cache_until_reload() {
        let mut ram = Ram::new();
        let code = [
            0x0f, 0x01, 0x16, 0x40, 0x00, // lgdt [0x40]
            0x0f, 0x20, 0xc0, // mov eax,cr0
            0x66, 0x83, 0xc8, 0x01, // or eax,1
            0x0f, 0x22, 0xc0, // mov cr0,eax
            0xea, 0x14, 0x00, 0x08, 0x00, // jmp far 8:0x14
            0xff, 0x25, 0x20, 0x00, 0x00, 0x00, // jmp dword [0x20]
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        ram.write_u32(0x20, 0x0001_2345);
        ram.write_u16(0x40, 0x000f);
        ram.write_u32(0x42, 0x0000_0050);
        ram.write_u32(0x58, 0x0000_ffff);
        ram.write_u32(0x5c, 0x00cf_9a00);

        let mut cpu = Cpu::new();

        while cpu.eip != 0x0001_2345 {
            assert_eq!(
                Interpreter::step(&mut cpu, &mut ram).unwrap(),
                StepOutcome::Running
            );
        }

        assert_eq!(cpu.seg(SegmentReg::Ds).selector, 0);
        assert_eq!(cpu.seg(SegmentReg::Ds).limit, 0xffff);
    }

    #[test]
    fn far_transfers_touch_code_accessed_after_frame_before_register_commit() {
        for opcode in [0x9a, 0xea, 0xcb, 0xcf] {
            for gate in [false, true] {
                if gate && matches!(opcode, 0xcb | 0xcf) {
                    continue;
                }
                for (accessed, writable) in [(false, true), (false, false), (true, false)] {
                    let mut cpu = flat_cpu();
                    let mut ram = Ram::new();
                    cpu.eip = 0x100;
                    cpu.set_reg(Reg32::Esp, 0x900);
                    cpu.gdtr = TableReg {
                        base: 0x3000,
                        limit: 0x17,
                    };
                    ram.data[0x100..0x107].copy_from_slice(&[
                        opcode,
                        0,
                        8,
                        0,
                        0,
                        if gate { 16 } else { 8 },
                        0,
                    ]);
                    ram.write_u32(0x900, 0x800);
                    ram.write_u32(0x904, 8);
                    ram.write_u32(0x908, 2);
                    ram.write_u32(0x1000, 0x2003);
                    for page in 0..4 {
                        ram.write_u32(0x2000 + page * 4, (page as u32) * 0x1000 | 3);
                    }
                    ram.write_u32(0x200c, 0x3001 | if writable { 2 } else { 0 });
                    ram.write_u32(0x3008, 0xffff);
                    ram.write_u32(0x300c, 0x00cf_9a00 | if accessed { 0x100 } else { 0 });
                    ram.write_u32(0x3010, 0x0008_0800);
                    ram.write_u32(0x3014, 0x0000_8c00);
                    cpu.cr0 |= CR0_PG | crate::x86::cpu::CR0_WP;
                    cpu.cr3 = 0x1000;
                    let old_cs = cpu.seg(SegmentReg::Cs);
                    let old_ss = cpu.seg(SegmentReg::Ss);
                    let result = Interpreter::step(&mut cpu, &mut ram);
                    if !accessed && !writable {
                        assert_eq!(
                            result,
                            Err(StepError::PageFault(mmu::PageFault {
                                linear: LinearAddr(0x300d),
                                code: 3,
                            })),
                            "opcode={opcode:x} gate={gate}"
                        );
                        assert_eq!(cpu.cr2, 0x300d);
                        assert_eq!(cpu.reg(Reg32::Esp), 0x900);
                        assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);
                        assert_eq!(cpu.seg(SegmentReg::Ss), old_ss);
                        assert_eq!(ram.data[0x300d] & 1, 0);
                    } else {
                        result.unwrap();
                        assert_eq!(cpu.eip, 0x800);
                        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 8);
                        assert_ne!(cpu.seg(SegmentReg::Cs).flags & 1, 0);
                        assert_ne!(ram.data[0x300d] & 1, 0);
                    }
                    if opcode == 0x9a {
                        assert_eq!(ram.read_u32(0x8fc), u32::from(old_cs.selector));
                        assert_eq!(ram.read_u32(0x8f8), 0x107);
                    }
                    assert_eq!(
                        ram.read_u32(0x200c) & 0x60,
                        0x20 | if !accessed && writable { 0x40 } else { 0 }
                    );
                }
            }
        }
    }

    #[test]
    fn far_call_keeps_completed_stack_write_when_next_push_faults() {
        for operand16 in [false, true] {
            for gate in [false, true] {
                for bad_target in [false, true] {
                    let mut cpu = flat_cpu();
                    let mut ram = Ram::new();
                    cpu.eip = 0x100;
                    let width = if operand16 { 2 } else { 4 };
                    let old_sp = 0x1000 + width;
                    cpu.set_reg(Reg32::Esp, old_sp);
                    cpu.gdtr = TableReg {
                        base: 0x3000,
                        limit: 0x17,
                    };
                    let selector = if gate { 16 } else { 8 };
                    let code: &[u8] = if operand16 {
                        &[0x66, 0x9a, 0, 6, selector, 0]
                    } else {
                        &[0x9a, 0, 6, 0, 0, selector, 0]
                    };
                    ram.data[0x100..0x100 + code.len()].copy_from_slice(code);
                    ram.write_u32(0x1000, 0xaaaaaaaa);
                    ram.write_u32(0x2000, 1); // code/second push page is read-only
                    ram.write_u32(0x2004, 0x1003);
                    ram.write_u32(0x2008, 0x2003);
                    ram.write_u32(0x200c, 0x3003);
                    ram.write_u32(0x3008, if bad_target { 0x10 } else { 0xffff });
                    ram.write_u32(0x300c, 0x0040_9a00);
                    ram.write_u32(0x3010, 0x0008_0600);
                    ram.write_u32(0x3014, if operand16 { 0x8400 } else { 0x8c00 });
                    cpu.cr0 |= CR0_PG | crate::x86::cpu::CR0_WP;
                    // Directory at zero, away from code and observed stack.
                    ram.write_u32(0, 0x2003);
                    cpu.cr3 = 0;
                    let old_cs = cpu.seg(SegmentReg::Cs);
                    assert_eq!(
                        Interpreter::step(&mut cpu, &mut ram),
                        Err(StepError::PageFault(mmu::PageFault {
                            linear: LinearAddr(0x1000 - width),
                            code: 3,
                        }))
                    );
                    assert_eq!(cpu.reg(Reg32::Esp), old_sp);
                    assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);
                    if operand16 {
                        assert_eq!(ram.read_u16(0x1000), old_cs.selector);
                        assert_eq!(ram.read_u16(0x1002), 0xaaaa);
                    } else {
                        assert_eq!(ram.read_u32(0x1000), u32::from(old_cs.selector));
                    }
                    assert_eq!(ram.data[0x300d] & 1, 0);
                }
            }
        }
    }

    #[test]
    fn call_gate_checks_new_stack_before_parameters_and_keeps_partial_frame() {
        for bad_tss_stack in [false, true] {
            let mut ram = Ram::new();
            install_call_gate_gdt(&mut ram, 0xec, 2, CALL_KERNEL_CODE_SEL, 0x2000);
            ram.data[..7].copy_from_slice(&[0x9a, 0, 0, 0, 0, CALL_GATE_SEL as u8, 0]);
            ram.write_u32(CALL_TSS_BASE + 4, 0x700);
            ram.write_u16(
                CALL_TSS_BASE + 8,
                if bad_tss_stack {
                    0
                } else {
                    CALL_KERNEL_DATA_SEL
                },
            );
            ram.write_u32(0x6fc, 0xaaaaaaaa);
            ram.write_u32(0x6f8, 0xbbbbbbbb);
            let mut cpu = call_gate_cpu_cpl3(0);
            cpu.set_reg(Reg32::Esp, 0x900);
            cpu.set_seg_cache(
                SegmentReg::Ss,
                SegmentCache {
                    limit: 0x900,
                    ..cpu.seg(SegmentReg::Ss)
                },
            );
            let old_cs = cpu.seg(SegmentReg::Cs);
            let old_ss = cpu.seg(SegmentReg::Ss);
            let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
            assert_eq!(
                error.exception(0),
                Some((if bad_tss_stack { 10 } else { 12 }, Some(0), 0))
            );
            assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);
            assert_eq!(cpu.seg(SegmentReg::Ss), old_ss);
            assert_eq!(cpu.reg(Reg32::Esp), 0x900);
            if bad_tss_stack {
                assert_eq!(ram.read_u32(0x6fc), 0xaaaaaaaa);
                assert_eq!(ram.read_u32(0x6f8), 0xbbbbbbbb);
            } else {
                assert_eq!(ram.read_u32(0x6fc), u32::from(old_ss.selector));
                assert_eq!(ram.read_u32(0x6f8), 0x900);
            }
            assert_eq!(ram.data[0x4d] & 1, 0);
            assert_eq!(ram.data[0x55] & 1, 0);
        }
    }

    #[test]
    fn outer_returns_touch_both_descriptors_and_respect_new_stack_width() {
        for opcode in [0xcb, 0xcf] {
            let mut cpu = flat_cpu();
            let mut ram = Ram::new();
            cpu.eip = 0x200;
            cpu.gdtr = TableReg {
                base: 0x40,
                limit: 0x27,
            };
            cpu.set_reg(Reg32::Esp, 0x900);
            ram.data[0x200] = opcode;
            ram.write_descriptor(3, 0x00cf_fa00);
            ram.write_descriptor(4, 0x0080_f200); // SS.B=0, unaccessed
            ram.write_u32(0x900, 0x500);
            ram.write_u32(0x904, 0x1b);
            ram.write_u32(0x908, 2);
            let tail = if opcode == 0xcf { 0x90c } else { 0x908 };
            ram.write_u32(tail, 0xdead_9001);
            ram.write_u32(tail + 4, 0x23);
            Interpreter::step(&mut cpu, &mut ram).unwrap();
            assert_eq!(cpu.eip, 0x500);
            assert_eq!(cpu.cpl(), 3);
            assert_eq!(cpu.reg(Reg32::Esp), 0x9001);
            assert_ne!(ram.data[0x5d] & 1, 0);
            assert_ne!(ram.data[0x65] & 1, 0);
            assert_ne!(cpu.seg(SegmentReg::Cs).flags & 1, 0);
            assert_ne!(cpu.seg(SegmentReg::Ss).flags & 1, 0);
        }
    }

    #[test]
    fn interrupt_frame_fault_retains_only_completed_slots() {
        for gate16 in [false, true] {
            let mut cpu = flat_cpu();
            let mut ram = Ram::new();
            let stack = cpu.seg(SegmentReg::Ss);
            let width = if gate16 { 2 } else { 4 };
            cpu.set_reg(Reg32::Esp, 0x1000 + width);
            cpu.cr0 |= CR0_PG | crate::x86::cpu::CR0_WP;
            cpu.cr3 = 0;
            ram.write_u32(0, 0x2003);
            ram.write_u32(0x2000, 1);
            ram.write_u32(0x2004, 0x1003);
            ram.write_u32(0x1000, 0xaaaaaaaa);
            let result = push_interrupt_frame(
                &mut cpu,
                &mut ram,
                stack,
                0,
                0x1000 + width,
                gate16,
                None,
                0x803,
                8,
                0x444,
                None,
                None,
                0x400,
            );
            assert_eq!(
                result,
                Err(StepError::PageFault(mmu::PageFault {
                    linear: LinearAddr(0x1000 - width),
                    code: 3,
                }))
            );
            assert_eq!(cpu.reg(Reg32::Esp), 0x1000 + width);
            assert_eq!(ram.read_u16(0x1000), 0x803);
            assert_eq!(ram.read_u16(0x1002), if gate16 { 0xaaaa } else { 0 });
        }
    }

    #[test]
    fn fault_exit_uses_instruction_start_after_prefix_operand_and_fetch_decode() {
        for (code, segment, vector) in [
            (&[0x8b, 0x05, 0, 0x10, 0, 0][..], SegmentReg::Ds, 13), // MOV EAX,[1000h]
            (
                &[0x64, 0x66, 0x8b, 0x05, 0, 0x10, 0, 0][..],
                SegmentReg::Fs,
                13,
            ),
            (&[0x8b, 0x45, 0][..], SegmentReg::Ss, 12), // MOV EAX,[EBP]
            (&[0xd9, 0x05, 0, 0x10, 0, 0][..], SegmentReg::Ds, 13), // FLD m32
            (&[0x89, 0x05, 0, 0x10, 0, 0][..], SegmentReg::Ds, 13), // read-only destination
            (&[0x66, 0xb8, 0x34, 0x12][..], SegmentReg::Cs, 13), // truncated immediate
        ] {
            let mut cpu = flat_cpu();
            let mut ram = Ram::new();
            cpu.eip = 0x200;
            cpu.set_reg(Reg32::Eax, 0xdead_beef);
            cpu.set_reg(Reg32::Ebp, 0x1000);
            cpu.set_reg(Reg32::Esp, 0x800);
            cpu.eflags = EFLAGS_CF | EFLAGS_OF | 2;
            ram.data[0x200..0x203].copy_from_slice(&[0x90; 3]);
            ram.data[0x203..0x203 + code.len()].copy_from_slice(code);
            let cache = match segment {
                SegmentReg::Cs => SegmentCache {
                    limit: 0x205,
                    ..cpu.seg(segment)
                },
                SegmentReg::Ss => SegmentCache::new(0x10, 0, 0xfff, 0xc093),
                _ if code[0] == 0x89 => SegmentCache::flat(0x18, 0xc091),
                _ => SegmentCache::new(0, 0, 0, 0),
            };
            cpu.set_seg_cache(segment, cache);
            let regs = cpu.regs;
            let memory = ram.data;
            let result = Interpreter::run_batch(&mut cpu, &mut ram, 700, 20);
            assert_eq!(result.ran, 4);
            let BatchStop::Step {
                instruction_step,
                instruction_eip,
                reason: BatchStepStop::Error(error),
                ..
            } = result.stop
            else {
                panic!("{result:?}")
            };
            assert_eq!((instruction_step, instruction_eip), (703, 0x203));
            assert_eq!(
                error.exception(instruction_eip),
                Some((vector, Some(0), 0x203)),
                "{code:02x?}: {error:?}"
            );
            assert_eq!(cpu.regs, regs);
            assert_eq!(cpu.eflags, EFLAGS_CF | EFLAGS_OF | 2);
            assert_eq!(cpu.fpu.top, 0);
            assert_eq!(ram.data, memory);
        }
    }

    #[test]
    fn fault_exit_preserves_the_committed_task_restart_address() {
        for opcode in [0x9a, 0xea, 0xcf] {
            let mut ram = Ram::new();
            install_task_switch_gdt(&mut ram, opcode == 0xcf, 0x67);
            let (low, high) = descriptor_image(0xb00, 0x17, 0x02, 0);
            ram.write_descriptor_raw(4, low, high); // Incoming LDT is absent.
            ram.write_u16(CURRENT_TSS_BASE, NEXT_TSS_SEL);
            let mut image = test_tss32(0x240, 0x900);
            image.ldtr = 0x20;
            write_tss32(&mut ram, NEXT_TSS_BASE, image);
            ram.data[0x200..0x207].copy_from_slice(&[opcode, 0, 0, 0, 0, NEXT_TSS_SEL as u8, 0]);
            let mut cpu = task_switch_cpu(0x200);
            cpu.eflags = 2 | if opcode == 0xcf { EFLAGS_NT } else { 0 };
            let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
            assert_eq!(error.exception(0x200), Some((10, Some(0x20), 0x240)));
            assert_eq!(cpu.tr, NEXT_TSS_SEL);
            assert_eq!(cpu.eip, 0x240);
        }
    }

