    #[test]
    fn protected_far_jmp_validates_code_descriptor_type_presence_privilege_and_limit() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0xea, 0x20, 0x00, 0x00, 0x00, 0x08, 0x00, // jmp far 8:0x20
        ]);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x0f,
        };
        let old_cs = cpu.seg(SegmentReg::Cs);

        ram.write_descriptor(1, 0x00cf_9200);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 8 })
        );
        assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);

        cpu.eip = 0;
        ram.write_descriptor(1, 0x00cf_1a00);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::SegmentNotPresent { eip: 0, code: 8 })
        );
        assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);

        cpu.eip = 0;
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache::flat(0x1b, SEGMENT_FLAG_DEFAULT_BIG),
        );
        ram.write_descriptor(1, 0x00cf_9a00);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 8 })
        );
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x1b);

        cpu.eip = 0;
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache::flat(0x10, SEGMENT_FLAG_DEFAULT_BIG),
        );
        let (low, high) = descriptor_image(0, 0x0010, 0x9a, 0x00);
        ram.write_descriptor_raw(1, low, high);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 0 })
        );
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x10);

        cpu.eip = 0;
        ram.write_descriptor(1, 0x00cf_9a00);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 0x20);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x08);
    }

