    #[test]
    fn real_mode_iret16_uses_word_frame_sp_and_preserves_high_flags() {
        let mut ram = Ram::new();
        ram.data[0] = 0xcf; // iretw in 16-bit real mode
        ram.write_u16(0x120, 0x4567);
        ram.write_u16(0x122, 0x1234);
        ram.write_u16(0x124, (EFLAGS_IF | EFLAGS_CF | EFLAGS_IOPL) as u16);

        let mut cpu = Cpu::new();
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0));
        cpu.set_seg_cache(
            SegmentReg::Ss,
            SegmentCache {
                selector: 0x2000,
                base: 0x100,
                limit: 0xffff,
                flags: 0,
            },
        );
        cpu.set_reg(Reg32::Esp, 0x1234_0020);
        cpu.eflags = EFLAGS_AC | EFLAGS_ID | 0x0000_0002;

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x4567);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x1234);
        assert_eq!(cpu.seg(SegmentReg::Cs).base, 0x12340);
        assert_eq!(cpu.reg(Reg32::Esp), 0x1234_0026);
        assert_eq!(cpu.eflags & (EFLAGS_AC | EFLAGS_ID), EFLAGS_AC | EFLAGS_ID);
        assert_eq!(
            cpu.eflags & (EFLAGS_IF | EFLAGS_CF | EFLAGS_IOPL),
            EFLAGS_IF | EFLAGS_CF | EFLAGS_IOPL
        );
    }

    #[test]
    fn cpl_follows_cpu_mode_not_real_mode_selector_bits() {
        // FreeDOS loads HIMEMX and JEMMEX at CS=0x029E. After MOV CR0 sets PE
        // and before the far jump, CPL is still 0: LLDT must not fault.
        let mut ram = Ram::new();
        ram.data[0x29e0..0x29e5].copy_from_slice(&[0x31, 0xc0, 0x0f, 0x00, 0xd0]); // xor ax,ax; lldt ax
        let mut cpu = Cpu::new();
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0x029e));
        cpu.eip = 0;
        assert_eq!(cpu.cpl(), 0);
        cpu.cr0 |= CR0_PE;
        step_running(&mut cpu, &mut ram);
        step_running(&mut cpu, &mut ram);
        assert_eq!((cpu.eip, cpu.ldtr), (5, 0));

        // IRET to V86 loads CS before setting VM; V86 runs at CPL 3 even with
        // RPL 0. An interrupt from V86 loads the handler CS before clearing VM.
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0x1000));
        assert_eq!(cpu.cpl(), 0);
        cpu.replace_eflags(cpu.effective_eflags() | EFLAGS_VM);
        assert_eq!(cpu.cpl(), 3);
        cpu.set_seg_cache(SegmentReg::Cs, SegmentCache::flat(0x08, 0xc09b));
        cpu.replace_eflags(cpu.effective_eflags() & !EFLAGS_VM);
        assert_eq!(cpu.cpl(), 0);
    }

    #[test]
    fn real_mode_iretd_uses_dword_slots_and_keeps_vm_virtual_interrupt_flags() {
        let mut ram = Ram::new();
        ram.data[..2].copy_from_slice(&[0x66, 0xcf]); // iretd
        ram.write_u32(0x120, 0x0000_3456);
        ram.write_u32(0x124, 0x0000_2222);
        ram.write_u32(
            0x128,
            EFLAGS_IF | EFLAGS_CF | EFLAGS_RF | EFLAGS_AC | EFLAGS_ID | 0x0000_0002,
        );

        let mut cpu = Cpu::new();
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0));
        cpu.set_seg_cache(
            SegmentReg::Ss,
            SegmentCache {
                selector: 0x3000,
                base: 0x100,
                limit: 0xffff,
                flags: SEGMENT_FLAG_DEFAULT_BIG,
            },
        );
        cpu.set_reg(Reg32::Esp, 0x20);
        cpu.eflags = EFLAGS_VM | EFLAGS_VIF | EFLAGS_VIP | 0x0000_0002;

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x3456);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x2222);
        assert_eq!(cpu.reg(Reg32::Esp), 0x2c);
        assert_eq!(
            cpu.eflags & (EFLAGS_VM | EFLAGS_VIF | EFLAGS_VIP),
            EFLAGS_VM | EFLAGS_VIF | EFLAGS_VIP
        );
        assert_eq!(
            cpu.eflags & (EFLAGS_IF | EFLAGS_CF | EFLAGS_RF | EFLAGS_AC | EFLAGS_ID),
            EFLAGS_IF | EFLAGS_CF | EFLAGS_RF | EFLAGS_AC | EFLAGS_ID
        );
    }

    #[test]
    fn vm86_iret16_with_vme_maps_if_to_vif_and_preserves_iopl_if() {
        let mut ram = Ram::new();
        ram.data[0] = 0xcf; // iretw in virtual-8086 mode
        ram.write_u16(0x120, 0x4567);
        ram.write_u16(0x122, 0x1234);
        ram.write_u16(
            0x124,
            (EFLAGS_IF | EFLAGS_CF | EFLAGS_DF | EFLAGS_OF) as u16,
        );

        let mut cpu = flat_cpu();
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0));
        cpu.set_seg_cache(SegmentReg::Ss, real_mode_segment(0x10));
        cpu.set_reg(Reg32::Esp, 0x20);
        cpu.cr4 = CR4_VME;
        cpu.eflags = EFLAGS_VM | 0x0000_0002;

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x4567);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x1234);
        assert_eq!(cpu.seg(SegmentReg::Cs).base, 0x12340);
        assert_eq!(cpu.reg(Reg32::Esp), 0x26);
        assert_ne!(cpu.eflags & EFLAGS_VM, 0);
        assert_ne!(cpu.eflags & EFLAGS_VIF, 0);
        assert_eq!(cpu.eflags & EFLAGS_IF, 0);
        assert_eq!(cpu.eflags & EFLAGS_IOPL, 0);
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
        assert_ne!(cpu.eflags & EFLAGS_DF, 0);
        assert_ne!(cpu.eflags & EFLAGS_OF, 0);
    }

    #[test]
    fn vm86_iret16_with_vme_faults_on_vip_if_or_trace_without_stack_commit() {
        for stack_flags in [EFLAGS_IF as u16, EFLAGS_TF as u16] {
            let mut ram = Ram::new();
            ram.data[0] = 0xcf; // iretw in virtual-8086 mode
            ram.write_u16(0x120, 0x4567);
            ram.write_u16(0x122, 0x1234);
            ram.write_u16(0x124, stack_flags | EFLAGS_CF as u16);

            let mut cpu = flat_cpu();
            cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0));
            cpu.set_seg_cache(SegmentReg::Ss, real_mode_segment(0x10));
            cpu.set_reg(Reg32::Esp, 0x20);
            cpu.cr4 = CR4_VME;
            cpu.eflags = EFLAGS_VM | EFLAGS_VIP | 0x0000_0002;
            let old_cs = cpu.seg(SegmentReg::Cs);
            let old_flags = cpu.eflags;

            step_gp(&mut cpu, &mut ram, 0);

            assert_eq!(cpu.eip, 1);
            assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);
            assert_eq!(cpu.reg(Reg32::Esp), 0x20);
            assert_eq!(cpu.eflags, old_flags);
        }
    }

