    #[test]
    fn protected_iretd_to_v86_loads_extended_real_mode_frame() {
        let mut ram = Ram::new();
        ram.data[0] = 0xcf;
        ram.write_u32(0x100, 0x0001_2345);
        ram.write_u32(0x104, 0x0000_1234);
        ram.write_u32(
            0x108,
            EFLAGS_VM | EFLAGS_IF | EFLAGS_IOPL | EFLAGS_CF | 0x0000_0002,
        );
        ram.write_u32(0x10c, 0x7777_8888);
        ram.write_u32(0x110, 0x0000_2000);
        ram.write_u32(0x114, 0x0000_3000);
        ram.write_u32(0x118, 0x0000_4000);
        ram.write_u32(0x11c, 0x0000_5000);
        ram.write_u32(0x120, 0x0000_6000);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_reg(Reg32::Esp, 0x100);

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x2345);
        assert_eq!(cpu.reg(Reg32::Esp), 0x7777_8888);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x1234);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x2000);
        assert_eq!(cpu.seg(SegmentReg::Es).base, 0x30000);
        assert_eq!(cpu.seg(SegmentReg::Ds).base, 0x40000);
        assert_eq!(cpu.seg(SegmentReg::Fs).base, 0x50000);
        assert_eq!(cpu.seg(SegmentReg::Gs).base, 0x60000);
        for seg in [
            SegmentReg::Es,
            SegmentReg::Cs,
            SegmentReg::Ss,
            SegmentReg::Ds,
            SegmentReg::Fs,
            SegmentReg::Gs,
        ] {
            let cache = cpu.seg(seg);
            assert_eq!((cache.limit, cache.flags), (0xffff, 0x00f3));
        }
        assert!(cpu.code_default16());
        assert!(!segment_uses_32bit_stack(cpu.seg(SegmentReg::Ss)));
        assert_eq!(cpu.cpl(), 3);
        assert_ne!(cpu.eflags & EFLAGS_VM, 0);
        assert_ne!(cpu.eflags & EFLAGS_IF, 0);
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
    }

