    #[test]
    fn enter_leave_word_stack_separates_address_and_operand_widths() {
        for operand16 in [false, true] {
            for level in [0, 2] {
                let mut ram = Ram::new();
                if operand16 {
                    ram.data[..7].copy_from_slice(&[0x66, 0xc8, 8, 0, level, 0x66, 0xc9]);
                    ram.write_u16(0x17e, 0xbeef);
                } else {
                    ram.data[..5].copy_from_slice(&[0xc8, 8, 0, level, 0xc9]);
                    ram.write_u32(0x17c, 0xcafe_beef);
                }
                let mut cpu = Cpu::new();
                cpu.enter_protected_flat(0, 0);
                cpu.set_seg_cache(SegmentReg::Ss, SegmentCache::new(0x10, 0x100, 0xffff, 0x93));
                cpu.set_reg(Reg32::Esp, 0xabcd_0040);
                cpu.set_reg(Reg32::Ebp, 0x1234_0080);
                let width = if operand16 { 2 } else { 4 };
                let frame = 0x40 - width;
                let frame_register = if operand16 {
                    0x1234_0000 | frame
                } else {
                    0xabcd_0000 | frame
                };
                let slots = if level == 0 { 1 } else { 3 };
                Interpreter::step(&mut cpu, &mut ram).unwrap();
                assert_eq!(
                    cpu.reg(Reg32::Esp),
                    0xabcd_0000 | (0x40 - slots * width - 8)
                );
                assert_eq!(cpu.reg(Reg32::Ebp), frame_register);
                if operand16 {
                    assert_eq!(ram.read_u16((0x100 + frame) as usize), 0x80);
                    if level == 2 {
                        assert_eq!(ram.read_u16((0x100 + frame - 2) as usize), 0xbeef);
                        assert_eq!(ram.read_u16((0x100 + frame - 4) as usize), frame as u16);
                    }
                } else {
                    assert_eq!(ram.read_u32((0x100 + frame) as usize), 0x1234_0080);
                    if level == 2 {
                        assert_eq!(ram.read_u32((0x100 + frame - 4) as usize), 0xcafe_beef);
                        assert_eq!(ram.read_u32((0x100 + frame - 8) as usize), frame_register);
                    }
                }
                Interpreter::step(&mut cpu, &mut ram).unwrap();
                assert_eq!(cpu.reg(Reg32::Esp), 0xabcd_0040);
                assert_eq!(cpu.reg(Reg32::Ebp), 0x1234_0080);
            }
        }
    }

