    #[test]
    fn pusha_popa_word_stack_preserves_high_esp_and_wraps_offsets() {
        let registers = [
            Reg32::Eax,
            Reg32::Ecx,
            Reg32::Edx,
            Reg32::Ebx,
            Reg32::Esp,
            Reg32::Ebp,
            Reg32::Esi,
            Reg32::Edi,
        ];
        for operand16 in [false, true] {
            // The second case crosses SP=0. Its wrapping segment base maps
            // the top of the word stack into this small test RAM.
            for (original_esp, base) in [(0xabcd_0040, 0x100), (0xabcd_0000, 0xffff_1000)] {
                let mut ram = Ram::new();
                if operand16 {
                    ram.data[..4].copy_from_slice(&[0x66, 0x60, 0x66, 0x61]);
                } else {
                    ram.data[..2].copy_from_slice(&[0x60, 0x61]);
                }
                let mut cpu = Cpu::new();
                cpu.enter_protected_flat(0, 0);
                cpu.set_seg_cache(SegmentReg::Ss, SegmentCache::new(0x10, base, 0xffff, 0x93));
                let mut saved = [0; 8];
                for (i, &reg) in registers.iter().enumerate() {
                    saved[i] = if reg == Reg32::Esp {
                        original_esp
                    } else {
                        0x1234_0100 + i as u32
                    };
                    cpu.set_reg(reg, saved[i]);
                }
                Interpreter::step(&mut cpu, &mut ram).unwrap();
                let width = if operand16 { 2 } else { 4 };
                let low_sp = (original_esp as u16).wrapping_sub(8 * width);
                assert_eq!(cpu.reg(Reg32::Esp), 0xabcd_0000 | u32::from(low_sp));
                for (i, &value) in saved.iter().enumerate() {
                    let offset = (original_esp as u16).wrapping_sub((i as u16 + 1) * width);
                    let address = base.wrapping_add(u32::from(offset)) as usize;
                    if operand16 {
                        assert_eq!(ram.read_u16(address), value as u16);
                    } else {
                        assert_eq!(ram.read_u32(address), value);
                    }
                }
                for &reg in &registers {
                    if reg != Reg32::Esp {
                        cpu.set_reg(reg, 0xbeef_0000);
                    }
                }
                Interpreter::step(&mut cpu, &mut ram).unwrap();
                assert_eq!(cpu.reg(Reg32::Esp), original_esp);
                for (i, &reg) in registers.iter().enumerate() {
                    if reg != Reg32::Esp {
                        let expected = if operand16 {
                            0xbeef_0000 | (saved[i] & 0xffff)
                        } else {
                            saved[i]
                        };
                        assert_eq!(cpu.reg(reg), expected);
                    }
                }
            }
        }
    }

    #[test]
    fn pusha32_page_fault_preserves_esp_and_stack_memory() {
        let mut ram = Ram::new();
        ram.data[0] = 0x60; // pusha at physical 0, mapped from CS.base
        ram.write_u32(0x1000, 0x2000 | 0x03);
        ram.write_u32(0x2010, 0x3000 | 0x03);
        ram.write_u32(0x2020, 0x0000_0000 | 0x03);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.cr0 |= crate::x86::cpu::CR0_PG;
        cpu.cr3 = 0x1000;
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache {
                base: 0x8000,
                ..cpu.seg(SegmentReg::Cs)
            },
        );
        cpu.set_reg(Reg32::Eax, 0x1111_1111);
        cpu.set_reg(Reg32::Ecx, 0x2222_2222);
        cpu.set_reg(Reg32::Edx, 0x3333_3333);
        cpu.set_reg(Reg32::Ebx, 0x4444_4444);
        cpu.set_reg(Reg32::Esp, 0x4010);
        cpu.set_reg(Reg32::Ebp, 0x5555_5555);
        cpu.set_reg(Reg32::Esi, 0x6666_6666);
        cpu.set_reg(Reg32::Edi, 0x7777_7777);

        let err = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
        let Some(page) = err.page_fault() else {
            panic!("expected page fault");
        };

        assert_eq!(page.linear.0, 0x3ffc);
        assert_eq!(cpu.reg(Reg32::Esp), 0x4010);
        assert_eq!(&ram.data[0x3000..0x3010], &[0; 16]);
    }

