    #[test]
    fn size_prefixes_are_ignored_by_byte_and_fixed_width_instructions() {
        for default16 in [false, true] {
            let mut ram = Ram::new();
            let code = [
                0x66, 0x67, 0xb0, 0x12, // MOV AL,12h
                0x66, 0x67, 0x04, 0x34, // ADD AL,34h
                0x66, 0x67, 0x9e, // SAHF
                0x66, 0x67, 0xfc, // CLD
                0x66, 0x67, 0xf9, // STC
                0x66, 0x67, 0xe6, 0x80, // OUT 80h,AL
                0x66, 0x67, 0xd9, 0xe8, // FLD1
                0x66, 0x67, 0xf4, // HLT
            ];
            ram.data[..code.len()].copy_from_slice(&code);
            let mut cpu = if default16 { Cpu::new() } else { flat_cpu() };
            cpu.set_reg(Reg32::Eax, 0xaabb_ccdd);
            cpu.set_flag(EFLAGS_DF, true);

            for _ in 0..7 {
                step_running(&mut cpu, &mut ram);
            }
            step_halted(&mut cpu, &mut ram);

            assert_eq!(cpu.eip, code.len() as u32);
            assert_eq!(cpu.reg(Reg32::Eax), 0xaabb_cc46);
            assert_eq!(cpu.effective_eflags() & (EFLAGS_DF | 0xd5), 0xc5);
            assert_eq!(ram.io_write_count, 1);
            assert_eq!(ram.io_writes[0], (0x80, 0x46, 1));
            assert_eq!(cpu.fpu.get(0), 1.0);
        }
    }

    #[test]
    fn repeated_size_prefixes_select_one_override_in_both_code_sizes() {
        for default16 in [false, true] {
            let mut code = std::vec![0x66, 0x66, 0xb8, 0x78, 0x56]; // MOV AX/EAX,imm
            if default16 {
                code.extend_from_slice(&[0x34, 0x12]);
            }
            code.extend_from_slice(&[0x66, 0x66, 0x91]); // XCHG AX/EAX,CX/ECX
            code.extend_from_slice(&[0x67, 0x67, 0xa0, 0, 3]); // MOV AL,[300h]
            if default16 {
                code.extend_from_slice(&[0, 0]);
            }
            code.extend_from_slice(&[0x66, 0x66, 0x1e, 0x66, 0x66, 0x1f]); // PUSH/POP DS
            let mut ram = Ram::new();
            ram.data[..code.len()].copy_from_slice(&code);
            ram.data[0x300] = 0x5a;
            ram.data[0x7fc..0x800].fill(0xaa);
            let mut cpu = if default16 { Cpu::new() } else { flat_cpu() };
            cpu.cr0 &= !CR0_PE;
            cpu.set_reg(Reg32::Eax, 0xaaaa_0000);
            cpu.set_reg(Reg32::Ecx, 0xbbbb_9988);
            cpu.set_reg(Reg32::Esp, 0x800);
            let selector = cpu.seg(SegmentReg::Ds).selector;

            step_running(&mut cpu, &mut ram);
            assert_eq!(
                cpu.reg(Reg32::Eax),
                if default16 { 0x1234_5678 } else { 0xaaaa_5678 }
            );
            step_running(&mut cpu, &mut ram);
            assert_eq!(
                cpu.reg(Reg32::Ecx),
                if default16 { 0x1234_5678 } else { 0xbbbb_5678 }
            );
            step_running(&mut cpu, &mut ram);
            assert_eq!(
                cpu.reg(Reg32::Eax),
                if default16 { 0xbbbb_995a } else { 0xaaaa_995a }
            );
            step_running(&mut cpu, &mut ram);
            let sp = if default16 { 0x7fc } else { 0x7fe };
            assert_eq!(cpu.reg(Reg32::Esp), sp);
            assert_eq!(ram.read_u16(sp as usize), selector);
            if default16 {
                assert_eq!(ram.read_u16(0x7fe), 0xaaaa);
            }
            step_running(&mut cpu, &mut ram);
            assert_eq!(cpu.reg(Reg32::Esp), 0x800);
            assert_eq!(cpu.seg(SegmentReg::Ds).selector, selector);
            assert_eq!(cpu.eip, code.len() as u32);
        }
    }

    #[test]
    fn mmx_movd_movq_round_trip_and_emms_clears_active_state() {
        let mut ram = Ram::new();
        let code = [
            0xb8, 0xef, 0xcd, 0xab, 0x89, // mov eax, 0x89abcdef
            0x0f, 0x6e, 0xc0, // movd mm0, eax
            0x0f, 0x7f, 0x05, 0x00, 0x03, 0x00, 0x00, // movq [0x300], mm0
            0x0f, 0x6f, 0x0d, 0x00, 0x03, 0x00, 0x00, // movq mm1, [0x300]
            0x0f, 0x7e, 0xcb, // movd ebx, mm1
            0x0f, 0x77, // emms
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);

        let mut cpu = flat_cpu();
        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(ram.read_u64(0x300), 0x0000_0000_89ab_cdef);
        assert_eq!(cpu.fpu.mmx(0), 0x0000_0000_89ab_cdef);
        assert_eq!(cpu.fpu.mmx(1), 0x0000_0000_89ab_cdef);
        assert_eq!(cpu.reg(Reg32::Ebx), 0x89ab_cdef);
        assert_eq!(cpu.fpu.top, 0);
        assert!(!cpu.fpu.mmx_active);
    }

    #[test]
    fn mmx_uses_literal_prefixes_independently_of_code_size() {
        for default16 in [false, true] {
            for prefixes in [
                &[][..],
                &[0x66][..],
                &[0x66, 0x66][..],
                &[0xf2][..],
                &[0xf3][..],
            ] {
                for instruction in [&[0x0f, 0x6e, 0xc0][..], &[0x0f, 0x77][..]] {
                    let mut ram = Ram::new();
                    ram.data[..prefixes.len()].copy_from_slice(prefixes);
                    ram.data[prefixes.len()..prefixes.len() + instruction.len()]
                        .copy_from_slice(instruction);
                    let mut cpu = if default16 { Cpu::new() } else { flat_cpu() };
                    cpu.set_reg(Reg32::Eax, 0x1234_5678);
                    cpu.fpu.set_mmx(0, 0x8877_6655_4433_2211);

                    if prefixes.is_empty() {
                        step_running(&mut cpu, &mut ram);
                        if instruction[1] == 0x6e {
                            assert_eq!(cpu.fpu.mmx(0), 0x1234_5678);
                        } else {
                            assert!(!cpu.fpu.mmx_active);
                        }
                    } else {
                        step_ud(&mut cpu, &mut ram, 0);
                        assert_eq!(cpu.fpu.mmx(0), 0x8877_6655_4433_2211);
                        assert!(cpu.fpu.mmx_active);
                    }
                }
            }
        }
    }

    #[test]
    fn mmx_arithmetic_logic_compare_and_pack_ops_update_lanes() {
        let lhs_bytes = pack_bytes([1, 2, 0x7f, 0x80, 0xfe, 0xff, 0, 0x10]);
        let rhs_bytes = pack_bytes([1, 0xff, 1, 0x80, 2, 1, 0xff, 0xf0]);

        assert_eq!(
            run_mmx_reg_op(0xfc, lhs_bytes, rhs_bytes).fpu.mmx(0),
            pack_bytes([2, 1, 0x80, 0, 0, 0, 0xff, 0])
        );
        assert_eq!(
            run_mmx_reg_op(0xec, lhs_bytes, rhs_bytes).fpu.mmx(0),
            pack_bytes([2, 1, 0x7f, 0x80, 0, 0, 0xff, 0])
        );
        assert_eq!(
            run_mmx_reg_op(0xdc, lhs_bytes, rhs_bytes).fpu.mmx(0),
            pack_bytes([2, 0xff, 0x80, 0xff, 0xff, 0xff, 0xff, 0xff])
        );
        assert_eq!(
            run_mmx_reg_op(0x64, lhs_bytes, rhs_bytes).fpu.mmx(0),
            pack_bytes([0, 0xff, 0xff, 0, 0, 0, 0xff, 0xff])
        );
        assert_eq!(
            run_mmx_reg_op(0x74, lhs_bytes, rhs_bytes).fpu.mmx(0),
            pack_bytes([0xff, 0, 0, 0xff, 0, 0, 0, 0])
        );
        assert_eq!(
            run_mmx_reg_op(0xdb, lhs_bytes, rhs_bytes).fpu.mmx(0),
            lhs_bytes & rhs_bytes
        );
        assert_eq!(
            run_mmx_reg_op(0xdf, lhs_bytes, rhs_bytes).fpu.mmx(0),
            (!lhs_bytes) & rhs_bytes
        );

        let lhs_words = pack_words([0xff38, 0xffff, 0, 0x012c]);
        let rhs_words = pack_words([0x007f, 0x0080, 0xff7f, 0x002a]);
        assert_eq!(
            run_mmx_reg_op(0x63, lhs_words, rhs_words).fpu.mmx(0),
            pack_bytes([0x80, 0xff, 0, 0x7f, 0x7f, 0x7f, 0x80, 0x2a])
        );
        assert_eq!(
            run_mmx_reg_op(0x67, lhs_words, rhs_words).fpu.mmx(0),
            pack_bytes([0, 0, 0, 0xff, 0x7f, 0x80, 0, 0x2a])
        );
        assert_eq!(
            run_mmx_reg_op(
                0x6b,
                pack_dwords([0xffff_0000, 0x0000_7fff]),
                pack_dwords([0x0000_8000, 0x0001_0000]),
            )
            .fpu
            .mmx(0),
            pack_words([0x8000, 0x7fff, 0x7fff, 0x7fff])
        );
    }

    #[test]
    fn mmx_unpack_multiply_and_shift_ops_follow_packed_integer_rules() {
        assert_eq!(
            run_mmx_reg_op(
                0x60,
                pack_bytes([0, 1, 2, 3, 4, 5, 6, 7]),
                pack_bytes([10, 11, 12, 13, 14, 15, 16, 17]),
            )
            .fpu
            .mmx(0),
            pack_bytes([0, 10, 1, 11, 2, 12, 3, 13])
        );
        assert_eq!(
            run_mmx_reg_op(
                0x6a,
                pack_dwords([0x1122_3344, 0x5566_7788]),
                pack_dwords([0xaabb_ccdd, 0xeeff_0011]),
            )
            .fpu
            .mmx(0),
            pack_dwords([0x5566_7788, 0xeeff_0011])
        );
        assert_eq!(
            run_mmx_reg_op(
                0xd5,
                pack_words([2, 0xffff, 0x8000, 0x1234]),
                pack_words([3, 2, 2, 0x0010]),
            )
            .fpu
            .mmx(0),
            pack_words([6, 0xfffe, 0, 0x2340])
        );
        assert_eq!(
            run_mmx_reg_op(
                0xe5,
                pack_words([0x8000, 0x7fff, 0xffff, 0x4000]),
                pack_words([2, 2, 2, 4]),
            )
            .fpu
            .mmx(0),
            pack_words([0xffff, 0, 0xffff, 1])
        );
        assert_eq!(
            run_mmx_reg_op(
                0xf5,
                pack_words([2, 3, 0xffff, 0x8000]),
                pack_words([4, 5, 2, 0xffff]),
            )
            .fpu
            .mmx(0),
            pack_dwords([23, 0x0000_7ffe])
        );

        let shifted = run_mmx_reg_op(0xd1, pack_words([0x8000, 0x00f0, 0xffff, 1]), 4);
        assert_eq!(shifted.fpu.mmx(0), pack_words([0x0800, 0x000f, 0x0fff, 0]));
        let oversized_full_qword = run_mmx_reg_op(
            0xd1,
            pack_words([0xffff, 0xffff, 0xffff, 0xffff]),
            0x0001_0000,
        );
        assert_eq!(oversized_full_qword.fpu.mmx(0), 0);
        let arithmetic = run_mmx_shift_imm(0x71, 4, pack_words([0x8000, 0x7fff, 0xffff, 1]), 20);
        assert_eq!(arithmetic.fpu.mmx(0), pack_words([0xffff, 0, 0xffff, 0]));
        let left_qword = run_mmx_shift_imm(0x73, 6, 0x0000_0000_0000_0001, 63);
        assert_eq!(left_qword.fpu.mmx(0), 0x8000_0000_0000_0000);
    }

    #[test]
    fn mmx_movq_paged_qwords_preserve_split_bytes_and_segment_base() {
        for offset in [0x80, 0xffb, 0xffc, 0xffe] {
            let mut ram = Ram::new();
            ram.cache_data = true;
            ram.data[0x100..0x106].copy_from_slice(&[0x0f, 0x6f, 0x06, 0x0f, 0x7f, 0x07]);
            map_test_page(&mut ram, 0, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
            map_test_page(&mut ram, 0x4000, 0x3000, TEST_PTE_PRESENT | TEST_PTE_WRITE);
            map_test_page(&mut ram, 0x5000, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
            let physical = |i: usize| (0x3000 + offset + i) & 0x3fff;
            let value = 0xfedc_ba98_7654_3210u64;
            for (i, byte) in value.to_le_bytes().into_iter().enumerate() {
                ram.data[physical(i)] = byte;
            }
            let mut cpu = flat_cpu();
            enable_test_paging(&mut cpu);
            cpu.eip = 0x100;
            cpu.set_seg_cache(
                SegmentReg::Ds,
                SegmentCache {
                    base: 0x1000,
                    ..cpu.seg(SegmentReg::Ds)
                },
            );
            cpu.set_reg(Reg32::Esi, 0x3000 + offset as u32);
            cpu.set_reg(Reg32::Edi, 0x3000 + offset as u32);
            let flags = cpu.effective_eflags();
            step_running(&mut cpu, &mut ram);
            assert_eq!(cpu.fpu.mmx(0), value, "offset={offset:x}");
            cpu.fpu.set_mmx(0, !value);
            step_running(&mut cpu, &mut ram);
            for (i, byte) in (!value).to_le_bytes().into_iter().enumerate() {
                assert_eq!(ram.data[physical(i)], byte, "offset={offset:x} byte={i}");
            }
            assert_eq!(cpu.effective_eflags(), flags);
            assert_eq!(cpu.eip, 0x106);
        }
    }

    #[test]
    fn mmx_movq_segment_and_high_page_faults_preserve_operand() {
        for (store, high_flags, short_segment, error_code) in [
            (false, 0, false, 0),
            (true, 0, false, 2),
            (true, TEST_PTE_PRESENT, false, 3),
            (false, 0, true, 0),
            (true, 0, true, 0),
        ] {
            let mut ram = Ram::new();
            ram.cache_data = true;
            ram.data[0x100..0x103].copy_from_slice(&[0x0f, if store { 0x7f } else { 0x6f }, 0x07]);
            map_test_page(&mut ram, 0, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
            map_test_page(&mut ram, 0x4000, 0x3000, TEST_PTE_PRESENT | TEST_PTE_WRITE);
            map_test_page(&mut ram, 0x5000, 0, high_flags);
            ram.data[0x3ffc..0x4000].fill(0xa5);
            ram.data[..4].fill(0x5a);
            let mut cpu = flat_cpu();
            enable_test_paging(&mut cpu);
            cpu.cr0 |= CR0_WP;
            cpu.cr2 = 0xdead_beef;
            cpu.eip = 0x100;
            cpu.set_seg_cache(
                SegmentReg::Ds,
                SegmentCache {
                    base: 0x4000,
                    limit: if short_segment { 0xfff } else { u32::MAX },
                    ..cpu.seg(SegmentReg::Ds)
                },
            );
            cpu.set_reg(Reg32::Edi, 0xffc);
            cpu.fpu.set_mmx(0, 0x8877_6655_4433_2211);
            if short_segment {
                step_gp(&mut cpu, &mut ram, 0x100);
                assert_eq!(cpu.cr2, 0xdead_beef);
            } else {
                assert_eq!(
                    Interpreter::step(&mut cpu, &mut ram),
                    Err(StepError::PageFault(mmu::PageFault {
                        linear: LinearAddr(0x5000),
                        code: error_code,
                    }))
                );
                assert_eq!(cpu.cr2, 0x5000);
            }
            assert_eq!(&ram.data[0x3ffc..0x4000], &[0xa5; 4]);
            assert_eq!(&ram.data[..4], &[0x5a; 4]);
            assert_eq!(cpu.fpu.mmx(0), 0x8877_6655_4433_2211);
        }
    }

    #[test]
    fn mmx_movq_memory_fault_does_not_partially_commit() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x0f, 0x7f, 0x05, 0xfc, 0x3f, 0x00, 0x00, // movq [0x3ffc], mm0
        ]);
        ram.write_u32(0x3ffc, 0x5566_7788);

        let mut cpu = flat_cpu();
        cpu.fpu.set_mmx(0, 0xaabb_ccdd_1122_3344);

        let err = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
        let Some(MemError::OutOfRange { addr }) = err.mem_error() else {
            panic!("expected memory fault");
        };

        assert_eq!(addr.0, 0x4000);
        assert_eq!(ram.read_u32(0x3ffc), 0x5566_7788);
    }

