    #[test]
    fn fxsave_and_fxrstor_preserve_active_mmx_register_images() {
        let mut ram = Ram::new();
        let code = [
            0x0f, 0xae, 0x05, 0x00, 0x03, 0x00, 0x00, // fxsave [0x300]
            0x0f, 0xae, 0x0d, 0x00, 0x03, 0x00, 0x00, // fxrstor [0x300]
            0x0f, 0x7f, 0x15, 0x00, 0x02, 0x00, 0x00, // movq [0x200], mm2
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        ram.data[0x300..0x500].fill(0xaa);

        let mut cpu = flat_cpu();
        cpu.fpu.set_mmx(2, 0x1122_3344_5566_7788);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        let slot = 0x300 + FXSAVE_X87_REG_BASE + 2 * 16;
        assert_eq!(ram.read_u64(slot), 0x1122_3344_5566_7788);
        assert_eq!(ram.read_u16(slot + 8), 0xffff);
        assert_eq!(ram.read_u64(0x200), 0x1122_3344_5566_7788);
        assert!(cpu.fpu.mmx_active);
    }

    #[test]
    fn cpuid_leaf_two_reports_descriptors_and_replaces_stale_outputs() {
        for ecx in [0, 1, 2, 0x1234_5678, 0xffff_ffff] {
            let mut cpu = flat_cpu();
            cpu.set_reg(Reg32::Eax, 2);
            cpu.set_reg(Reg32::Ebx, 0xffff_ffff);
            cpu.set_reg(Reg32::Ecx, ecx);
            cpu.set_reg(Reg32::Edx, 0xdddd_dddd);
            run_instruction(&mut cpu, &[0x0f, 0xa2]);

            // One descriptor set: ITLB/DTLB and L1/L2 caches of the selected
            // P6 profile. Do not derive the oracle from CPUID_CACHE_TLB_*.
            assert_cpuid_regs(&cpu, CpuidLeaf::new(0x0302_0101, 0, 0, 0x0c04_0843));
            assert_eq!(cpu.eip, 2);
        }
    }

