    #[test]
    fn cpuid_multiple_calls_use_current_eax_input_each_time() {
        let mut ram = Ram::new();
        ram.data[..9].copy_from_slice(&[
            0x0f, 0xa2, // cpuid leaf 1 from initial eax
            0xb8, 0x00, 0x00, 0x00, 0x00, // mov eax,0
            0x0f, 0xa2, // cpuid leaf 0 from updated eax
        ]);

        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 1);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), CPUID_SIGNATURE);
        assert_eq!(cpu.reg(Reg32::Edx), CPUID_FEATURES_EDX);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), CPUID_MAX_BASIC_LEAF);
        assert_eq!(cpu.reg(Reg32::Ebx), CPUID_VENDOR_EBX);
        assert_eq!(cpu.reg(Reg32::Ecx), CPUID_VENDOR_ECX);
        assert_eq!(cpu.reg(Reg32::Edx), CPUID_VENDOR_EDX);
        assert_eq!(cpu.eip, 9);
    }

