    #[test]
    fn fpu_escape_opcodes_raise_nm_before_modrm_fetch_when_ts_or_em_set() {
        for opcode in 0xd8..=0xdf {
            for cr0 in [CR0_TS, CR0_EM, CR0_TS | CR0_EM] {
                let mut ram = Ram::new();
                ram.data[0] = opcode;
                ram.data[1] = 0xc0;

                let mut cpu = flat_cpu_with_code_limit(0, 0);
                cpu.cr0 |= cr0;
                cpu.fpu.set(0, 11.0);

                step_nm(&mut cpu, &mut ram, 0);
                assert_eq!(cpu.eip, 1);
                assert_close(cpu.fpu.get(0), 11.0, 0.0);
            }
        }
    }

