    #[test]
    fn legacy_x87_controls_preserve_state_and_check_ts() {
        let state = crate::x86::cpu::FpuState {
            control: 0x027e,
            status: 0x82c1,
            top: 5,
            mxcsr: 0x0000_5f80,
            st: [
                0.0,
                -0.0,
                1.5,
                -3.0,
                f64::INFINITY,
                f64::NEG_INFINITY,
                f64::from_bits(0x7ff8_1234_5678_9abc),
                f64::from_bits(1),
            ],
            mm: [1, 2, 3, 4, 5, 6, 7, u64::MAX],
            mmx_active: true,
        };
        let snapshot = |fpu: &crate::x86::cpu::FpuState| {
            (
                fpu.control,
                fpu.status,
                fpu.top,
                fpu.mxcsr,
                fpu.st.map(f64::to_bits),
                fpu.mm,
                fpu.mmx_active,
            )
        };
        for modrm in [0xe0, 0xe1, 0xe4] {
            for ts in [0, CR0_TS] {
                let mut ram = Ram::new();
                ram.data[0x20..0x22].copy_from_slice(&[0xdb, modrm]);
                let mut cpu = Cpu::new();
                cpu.eip = 0x20;
                cpu.cr0 |= ts;
                cpu.fpu = state;

                if ts != 0 {
                    step_nm(&mut cpu, &mut ram, 0x20);
                } else {
                    step_running(&mut cpu, &mut ram);
                    assert_eq!(cpu.eip, 0x22);
                }
                assert_eq!(snapshot(&cpu.fpu), snapshot(&state));
            }
        }
    }

