    fn write_fxsave_instr(ram: &mut Ram, op: u8, addr: u32) {
        ram.data[..7].copy_from_slice(&fxsave_moffs(op, addr));
    }

    fn fxsave_moffs(op: u8, addr: u32) -> [u8; 7] {
        let mut code = [0x0f, 0xae, (op << 3) | 0x05, 0, 0, 0, 0];
        code[3..7].copy_from_slice(&addr.to_le_bytes());
        code
    }

    #[test]
    fn fxsave_group_uses_literal_prefixes_independently_of_code_size() {
        for default16 in [false, true] {
            for prefix in [None, Some(0x66), Some(0xf2), Some(0xf3)] {
                for op in [0, 1, 7] {
                    // FXSAVE, FXRSTOR, CLFLUSH
                    let mut code = Vec::new();
                    if let Some(prefix) = prefix {
                        code.push(prefix);
                    }
                    if default16 {
                        code.push(0x67);
                    }
                    code.extend_from_slice(&[0x0f, 0xae, 0x05 | (op << 3), 0, 3, 0, 0]);
                    let mut ram = Ram::new();
                    ram.data[..code.len()].copy_from_slice(&code);
                    ram.data[0x300..0x500].fill(0xaa);
                    ram.write_u16(0x300, 0x037f);
                    let before = ram.data;
                    let mut cpu = if default16 { Cpu::new() } else { flat_cpu() };
                    if prefix.is_some() {
                        cpu.cr0 |= CR0_TS; // An unsupported opcode precedes FPU availability.
                        step_ud(&mut cpu, &mut ram, 0);
                        assert_eq!(ram.data, before);
                    } else {
                        step_running(&mut cpu, &mut ram);
                        assert_eq!(cpu.eip, code.len() as u32);
                        if op == 0 {
                            assert_eq!(ram.read_u16(0x300), 0x037f);
                            assert_eq!(ram.read_u16(0x302), 0);
                        } else if op == 1 {
                            assert_eq!(cpu.fpu.status_word(), 0xaaaa);
                        } else {
                            assert_eq!(ram.data, before);
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fxsave_writes_p6_state_without_touching_xmm_or_software_bytes() {
        let mut ram = Ram::new();
        write_fxsave_instr(&mut ram, 0, 0x300);
        ram.data[7] = 0xf4;
        ram.data[0x300..0x500].fill(0xaa);

        let mut cpu = flat_cpu();
        cpu.fpu.control = 0x027f;
        cpu.fpu.status = 0x0101;
        cpu.fpu.top = 6;
        cpu.fpu.mxcsr = 0x0000_7fa0;
        cpu.fpu.set(0, 1.5);
        cpu.fpu.set(1, -2.0);

        step_running(&mut cpu, &mut ram);

        assert_eq!(ram.read_u16(0x300), 0x027f);
        assert_eq!(ram.read_u16(0x302), 0x3101);
        assert_eq!(ram.read_u32(0x318), 0);
        assert_eq!(ram.read_u32(0x31c), 0);
        assert_eq!(
            &ram.data[0x300 + FXSAVE_X87_REG_BASE..0x300 + FXSAVE_X87_REG_BASE + 10],
            &[0, 0, 0, 0, 0, 0, 0, 0xc0, 0xff, 0x3f]
        );
        assert_eq!(
            &ram.data[0x300 + FXSAVE_X87_REG_BASE + 16..0x300 + FXSAVE_X87_REG_BASE + 26],
            &[0, 0, 0, 0, 0, 0, 0, 0x80, 0x00, 0xc0]
        );
        assert!(
            ram.data[0x300 + FXSAVE_XMM_REG_BASE..0x500]
                .iter()
                .all(|byte| *byte == 0xaa)
        );
        assert_eq!(cpu.fpu.control, 0x027f);
        assert_eq!(cpu.fpu.top, 6);

        step_halted(&mut cpu, &mut ram);
    }

    #[test]
    fn fxrstor_restores_p6_control_status_and_register_image() {
        let mut ram = Ram::new();
        write_fxsave_instr(&mut ram, 1, 0x300);
        ram.data[7] = 0xf4;
        image_write_u16(&mut ram.data, 0x300, 0x027f);
        image_write_u16(&mut ram.data, 0x302, 0x2804);
        image_write_u32(&mut ram.data, 0x318, 0x0000_5f80);
        f64_to_fpu_m80(3.5, &mut ram.data, 0x300 + FXSAVE_X87_REG_BASE);
        f64_to_fpu_m80(-4.25, &mut ram.data, 0x300 + FXSAVE_X87_REG_BASE + 16);

        let mut cpu = flat_cpu();
        cpu.fpu.control = 0x037f;
        cpu.fpu.status = 0;
        cpu.fpu.top = 0;
        cpu.fpu.mxcsr = 0x0000_1f80;
        cpu.fpu.set(0, 99.0);
        cpu.fpu.set(1, 88.0);

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.fpu.control, 0x027f);
        assert_eq!(cpu.fpu.status, 0x0004);
        assert_eq!(cpu.fpu.top, 5);
        assert_eq!(cpu.fpu.mxcsr, 0x0000_1f80);
        assert_close(cpu.fpu.get(0), 3.5, 0.0);
        assert_close(cpu.fpu.get(1), -4.25, 0.0);

        step_halted(&mut cpu, &mut ram);
    }

