    #[test]
    fn fxsave_cross_page_fault_does_not_partially_commit_image() {
        let mut ram = Ram::new();
        write_fxsave_instr(&mut ram, 0, 0x0ff0);
        ram.data[0x0ff0..0x1000].fill(0xaa);

        let mut cpu = flat_cpu();
        enable_test_paging(&mut cpu);
        map_test_page(&mut ram, 0x0000, 0x0000, TEST_PTE_PRESENT | TEST_PTE_WRITE);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::PageFault(mmu::PageFault {
                linear: LinearAddr(0x1000),
                code: crate::x86::mmu::PFEC_WRITE,
            }))
        );
        assert!(ram.data[0x0ff0..0x1000].iter().all(|byte| *byte == 0xaa));
    }

    #[test]
    fn p6_fxsave_and_fxrstor_do_not_access_an_unmapped_sse_tail() {
        for op in [0, 1] {
            for osfxsr in [0, CR4_OSFXSR] {
                let mut ram = Ram::new();
                // The x87/MMX prefix ends at the page boundary. Everything
                // beyond it (including the software-owned tail) is unmapped.
                write_fxsave_instr(&mut ram, op, 0x0f60);
                image_write_u16(&mut ram.data, 0x0f60, 0x027f);
                image_write_u32(&mut ram.data, 0x0f60 + 24, 0xffff_ffff);
                f64_to_fpu_m80(1.5, &mut ram.data, 0x0f60 + FXSAVE_X87_REG_BASE);
                let mut cpu = flat_cpu();
                cpu.cr4 |= osfxsr;
                cpu.fpu.set(0, 2.5);
                enable_test_paging(&mut cpu);
                map_test_page(&mut ram, 0, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);

                step_running(&mut cpu, &mut ram);

                assert_eq!(cpu.fpu.mxcsr, 0x1f80);
                if op == 1 {
                    assert_eq!(cpu.fpu.control, 0x027f);
                    assert_close(cpu.fpu.get(0), 1.5, 0.0);
                } else {
                    assert_eq!(ram.read_u16(0x0f60), 0x037f);
                    assert_close(cpu.fpu.get(0), 2.5, 0.0);
                }
            }
        }
    }

    #[test]
    fn fxrstor_cross_page_fault_preserves_existing_state() {
        let mut ram = Ram::new();
        write_fxsave_instr(&mut ram, 1, 0x0ff0);
        image_write_u32(&mut ram.data, 0x0ff0 + 24, 0x0000_5f80);

        let mut cpu = flat_cpu();
        cpu.fpu.control = 0x027f;
        cpu.fpu.status = 0x0001;
        cpu.fpu.top = 3;
        cpu.fpu.mxcsr = 0x0000_1f80;
        cpu.fpu.set(0, 7.0);
        enable_test_paging(&mut cpu);
        map_test_page(&mut ram, 0x0000, 0x0000, TEST_PTE_PRESENT | TEST_PTE_WRITE);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::PageFault(mmu::PageFault {
                linear: LinearAddr(0x1000),
                code: 0,
            }))
        );
        assert_eq!(cpu.fpu.control, 0x027f);
        assert_eq!(cpu.fpu.status, 0x0001);
        assert_eq!(cpu.fpu.top, 3);
        assert_eq!(cpu.fpu.mxcsr, 0x0000_1f80);
        assert_close(cpu.fpu.get(0), 7.0, 0.0);
    }

