    #[test]
    fn upstream_prefetch_decodes_memory_without_accessing_it() {
        for default16 in [false, true] {
            for address16 in [false, true] {
                for hint in [0, 1] {
                    let mut ram = Ram::new();
                    let mut code = std::vec![0x66, 0x64];
                    if address16 != default16 {
                        code.push(0x67);
                    }
                    code.extend_from_slice(&[0x0f, 0x0d]);
                    if address16 {
                        code.extend_from_slice(&[0x86 | (hint << 3), 0xfe, 0xff]);
                    } else {
                        code.extend_from_slice(&[0x84 | (hint << 3), 0x88, 0x78, 0x56, 0x34, 0x12]);
                    }
                    ram.data[..code.len()].copy_from_slice(&code);
                    ram.data[code.len()] = 0xf4;
                    let mut cpu = flat_cpu();
                    cpu.set_seg_cache(
                        SegmentReg::Cs,
                        SegmentCache {
                            flags: if default16 {
                                0
                            } else {
                                SEGMENT_FLAG_DEFAULT_BIG
                            },
                            ..cpu.seg(SegmentReg::Cs)
                        },
                    );
                    cpu.set_seg_cache(
                        SegmentReg::Fs,
                        SegmentCache {
                            base: 0xffff_0000,
                            limit: 0,
                            ..cpu.seg(SegmentReg::Fs)
                        },
                    );
                    cpu.set_reg(Reg32::Eax, 0xffff_ffff);
                    cpu.set_reg(Reg32::Ecx, 0x100);
                    cpu.set_reg(Reg32::Ebp, 0x100);
                    cpu.eflags = EFLAGS_CF | EFLAGS_OF | EFLAGS_DF | 2;
                    let regs = cpu.regs;
                    let flags = cpu.eflags;
                    step_running(&mut cpu, &mut ram);
                    assert_eq!(cpu.eip, code.len() as u32);
                    assert_eq!(cpu.regs, regs);
                    assert_eq!(cpu.eflags, flags);
                    step_halted(&mut cpu, &mut ram);
                }
            }
        }
    }

    #[test]
    fn upstream_prefetch_does_not_walk_operand_or_set_ad_bits() {
        for hint in [0, 1] {
            for mapped in [false, true] {
                let mut ram = Ram::new();
                ram.data[..3].copy_from_slice(&[0x0f, 0x0d, hint << 3]);
                map_test_page(&mut ram, 0, 0, TEST_PTE_PRESENT | TEST_PTE_WRITE);
                if mapped {
                    map_test_page(&mut ram, 0x3000, 0x3000, TEST_PTE_PRESENT);
                }
                let old_pte = ram.read_u32(0x200c);
                let mut cpu = flat_cpu();
                enable_test_paging(&mut cpu);
                cpu.cr0 |= CR0_EM | CR0_TS;
                cpu.cr2 = 0xdead_beef;
                cpu.set_reg(Reg32::Eax, 0x3000);
                step_running(&mut cpu, &mut ram);
                assert_eq!(cpu.eip, 3);
                assert_eq!(cpu.cr2, 0xdead_beef);
                assert_eq!(ram.read_u32(0x200c), old_pte);
                assert_eq!(ram.translate_count, ram.execute_translate_count);
            }
        }
    }

