    #[test]
    fn upstream_simd_encodings_raise_guest_ud_on_the_p6_model() {
        // Neither SSSE3 map nor SSE2 MOVNTI belongs to the advertised CPU.
        // Reject them before operand decoding, even with an unavailable FPU.
        for opcode2 in [0x38, 0x3a, 0xc3] {
            for prefix in [0x66, 0xf2, 0xf3] {
                let mut ram = Ram::new();
                ram.data[..3].copy_from_slice(&[prefix, 0x0f, opcode2]);
                let mut cpu = flat_cpu_with_code_limit(0, 2);
                cpu.cr0 |= CR0_EM | CR0_TS;
                cpu.regs = [0x1234_5678; 8];
                cpu.eflags = EFLAGS_CF | EFLAGS_OF | 2;
                step_ud(&mut cpu, &mut ram, 0);
                assert_eq!(cpu.regs, [0x1234_5678; 8]);
                assert_eq!(cpu.eflags, EFLAGS_CF | EFLAGS_OF | 2);
                assert_eq!(cpu.eip, 3);
            }
        }
    }

    #[test]
    fn hint_nop_register_forms_consume_modrm_without_state_changes() {
        for opcode2 in 0x18..=0x1f {
            let mut ram = Ram::new();
            ram.data[..4].copy_from_slice(&[0x0f, opcode2, 0xc0, 0xf4]);

            let mut cpu = flat_cpu();
            cpu.set_reg(Reg32::Eax, 0x1122_3344);
            cpu.set_reg(Reg32::Ecx, 0x5566_7788);
            cpu.eflags = EFLAGS_CF | EFLAGS_OF | EFLAGS_DF | 0x0000_0002;

            step_running(&mut cpu, &mut ram);

            assert_eq!(cpu.eip, 3, "0f {opcode2:02x} register-form length");
            assert_eq!(cpu.reg(Reg32::Eax), 0x1122_3344);
            assert_eq!(cpu.reg(Reg32::Ecx), 0x5566_7788);
            assert_eq!(
                cpu.eflags & (EFLAGS_CF | EFLAGS_OF | EFLAGS_DF),
                EFLAGS_CF | EFLAGS_OF | EFLAGS_DF
            );
            assert!(!cpu.halted);
        }
    }

