        let mut ram = Ram::new();
        ram.data[..5].copy_from_slice(&[
            0x64, 0x0f, 0x1f, 0x00, // fs: nop [eax]
            0xa0, // mov al,moffs8
        ]);
        ram.data[5..9].copy_from_slice(&0x0010u32.to_le_bytes());
        ram.data[0x010] = 0x11;
