    #[test]
    fn xadd_same_register_keeps_sum_for_every_operand_width() {
        // The destination commits last (v86 instructions_0f.rs agrees).
        for bits in [8, 16, 32] {
            for reg in 0..8 {
                let mut ram = Ram::new();
                let mut code = Vec::new();
                if bits == 16 {
                    code.push(0x66);
                }
                code.extend([
                    0x0f,
                    if bits == 8 { 0xc0 } else { 0xc1 },
                    0xc0 | (reg << 3) | reg,
                ]);
                ram.data[..code.len()].copy_from_slice(&code);
                let mut cpu = flat_cpu();
                cpu.regs.fill(0x1234_ffff);
                step_running(&mut cpu, &mut ram);
                let index = if bits == 8 { reg & 3 } else { reg } as usize;
                let expected = if bits == 32 {
                    0x2469_fffe
                } else if bits == 8 && reg >= 4 {
                    0x1234_feff
                } else {
                    0x1234_fffe
                };
                assert_eq!(cpu.regs[index], expected);
                assert_flag(&cpu, EFLAGS_CF, bits != 32);
                assert_flag(&cpu, EFLAGS_OF, false);
            }
        }
    }

    #[test]
    fn scalar_cmpxchg_read_only_destination_faults_before_registers_and_flags() {
        for bits in [8, 16, 32] {
            for equal in [false, true] {
                let mut ram = Ram::new();
                let mut code = Vec::new();
                if bits == 16 {
                    code.push(0x66);
                }
                code.extend([
                    0x0f,
                    if bits == 8 { 0xb0 } else { 0xb1 },
                    0x0d,
                    0,
                    0x30,
                    0,
                    0,
                ]);
                ram.data[..code.len()].copy_from_slice(&code);
                ram.write_u32(0x3000, 0x1234_5678);
                ram.write_u32(0x1000, 0x2000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
                ram.write_u32(0x2000, TEST_PTE_PRESENT | TEST_PTE_WRITE);
                ram.write_u32(0x200c, 0x3000 | TEST_PTE_PRESENT);
                let mut cpu = flat_cpu();
                cpu.cr0 = CR0_PE | CR0_PG | CR0_WP;
                cpu.cr3 = 0x1000;
                cpu.regs[0] = 0x1234_5678 ^ u32::from(!equal);
                cpu.regs[1] = 0xfedc_ba98;
                cpu.replace_eflags(0x8d7);
                let regs = cpu.regs;
                let fault = Interpreter::step(&mut cpu, &mut ram)
                    .unwrap_err()
                    .page_fault()
                    .unwrap();
                assert_eq!(fault.linear.0, 0x3000);
                assert_eq!(
                    fault.code,
                    crate::x86::mmu::PFEC_PRESENT | crate::x86::mmu::PFEC_WRITE
                );
                assert_eq!(cpu.regs, regs);
                assert_eq!(cpu.effective_eflags(), 0x8d7);
                assert_eq!(ram.read_u32(0x3000), 0x1234_5678);
            }
        }
    }

