        assert_ne!(cpu.eflags & EFLAGS_ZF, 0);
        assert_eq!(cpu.eflags & (EFLAGS_CF | EFLAGS_OF), EFLAGS_CF | EFLAGS_OF);
        assert_eq!(cpu.eip, 7);
