    #[test]
    fn cmpxchg8b_write_probes_set_dirty_bits_for_both_pages() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x0f, 0xc7, 0x0d, 0xfc, 0x2f, 0x00, 0x00, // cmpxchg8b [0x2ffc]
        ]);
        ram.write_u32(0x3ffc, 0x0102_0304);
        ram.write_u32(0x3000, 0xa0b0_c0d0);
        ram.write_u32(0x1000, 0x2000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000, TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000 + 2 * 4, 0x3000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000 + 3 * 4, 0x3000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);

        let mut cpu = flat_cpu();
        cpu.cr0 = CR0_PE | CR0_PG;
        cpu.cr3 = 0x1000;
        cpu.set_reg(Reg32::Eax, 0x0102_0304);
        cpu.set_reg(Reg32::Edx, 0xa0b0_c0d0);
        cpu.set_reg(Reg32::Ebx, 0x1111_2222);
        cpu.set_reg(Reg32::Ecx, 0x3333_4444);

        step_running(&mut cpu, &mut ram);

        let low_pte = ram.read_u32(0x2000 + 2 * 4);
        let high_pte = ram.read_u32(0x2000 + 3 * 4);
        assert_eq!(
            low_pte & (TEST_PTE_ACCESSED | TEST_PTE_DIRTY),
            TEST_PTE_ACCESSED | TEST_PTE_DIRTY
        );
        assert_eq!(
            high_pte & (TEST_PTE_ACCESSED | TEST_PTE_DIRTY),
            TEST_PTE_ACCESSED | TEST_PTE_DIRTY
        );
        assert_eq!(ram.read_u32(0x3ffc), 0x1111_2222);
        assert_eq!(ram.read_u32(0x3000), 0x3333_4444);
    }

