    #[test]
    fn writing_integer_rm32_faults_have_write_intent_and_preserve_state() {
        for (opcode, group) in [
            (0x01, 0),
            (0x09, 0),
            (0x11, 0),
            (0x19, 0),
            (0x21, 0),
            (0x29, 0),
            (0x31, 0),
            (0x81, 0),
            (0x81, 1),
            (0x81, 2),
            (0x81, 3),
            (0x81, 4),
            (0x81, 5),
            (0x81, 6),
            (0x81, 7),
            (0x83, 0),
            (0x83, 1),
            (0x83, 2),
            (0x83, 3),
            (0x83, 4),
            (0x83, 5),
            (0x83, 6),
            (0x83, 7),
        ] {
            let mut ram = Ram::new();
            ram.data[..10].copy_from_slice(&[opcode, 0x05 | group << 3, 0, 0x30, 0, 0, 1, 0, 0, 0]);
            ram.write_u32(0x1000, 0x2003);
            ram.write_u32(0x2000, 3);
            ram.write_u32(0x3000, 0x12345678);
            let mut cpu = flat_cpu();
            cpu.cr0 = CR0_PE | CR0_PG | CR0_WP;
            cpu.cr3 = 0x1000;
            cpu.set_reg(Reg32::Eax, 0x11223344);
            cpu.replace_eflags(0x47);
            let before = cpu.regs;
            let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
            let fault = error.page_fault().expect("missing data PTE must fault");
            let writing = !matches!((opcode, group), (0x81 | 0x83, 7));
            assert_eq!(fault.linear.0, 0x3000);
            assert_eq!(
                fault.code,
                if writing { mmu::PFEC_WRITE } else { 0 },
                "opcode={opcode:x} group={group}"
            );
            assert_eq!(cpu.regs, before);
            assert_eq!(cpu.effective_eflags(), 0x47);
            assert_eq!(ram.read_u32(0x3000), 0x12345678);
        }
    }

    #[test]
    fn cmpxchg8b_probes_write_permission_before_compare_failure_register_updates() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x0f, 0xc7, 0x0d, 0x00, 0x30, 0x00, 0x00, // cmpxchg8b [0x3000]
        ]);
        ram.write_u64(0x3000, 0x1111_2222_3333_4444);
        ram.write_u32(0x1000, 0x2000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000, TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000 + 3 * 4, 0x3000 | TEST_PTE_PRESENT);

        let mut cpu = flat_cpu();
        cpu.cr0 = CR0_PE | CR0_PG | CR0_WP;
        cpu.cr3 = 0x1000;
        cpu.set_reg(Reg32::Eax, 0x3333_4445);
        cpu.set_reg(Reg32::Edx, 0x1111_2222);
        cpu.eflags = EFLAGS_ZF | 0x0000_0002;

        let err = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
        let Some(page) = err.page_fault() else {
            panic!("expected page fault");
        };

        assert_eq!(page.linear.0, 0x3000);
        assert_ne!(page.code & crate::x86::mmu::PFEC_PRESENT, 0);
        assert_ne!(page.code & crate::x86::mmu::PFEC_WRITE, 0);
        assert_eq!(ram.read_u64(0x3000), 0x1111_2222_3333_4444);
        assert_eq!(cpu.reg(Reg32::Eax), 0x3333_4445);
        assert_eq!(cpu.reg(Reg32::Edx), 0x1111_2222);
        assert_ne!(cpu.eflags & EFLAGS_ZF, 0);
    }

    #[test]
    fn cmpxchg8b_low_dword_probe_fault_preserves_registers_flags_and_memory() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x0f, 0xc7, 0x0d, 0x00, 0x30, 0x00, 0x00, // cmpxchg8b [0x3000]
        ]);
        ram.write_u64(0x3000, 0x1111_2222_3333_4444);
        ram.write_u32(0x1000, 0x2000 | TEST_PTE_PRESENT | TEST_PTE_WRITE);
        ram.write_u32(0x2000, TEST_PTE_PRESENT | TEST_PTE_WRITE);

        let mut cpu = flat_cpu();
        cpu.cr0 = CR0_PE | CR0_PG;
        cpu.cr3 = 0x1000;
        cpu.set_reg(Reg32::Eax, 0x3333_4444);
        cpu.set_reg(Reg32::Edx, 0x1111_2222);
        cpu.set_reg(Reg32::Ebx, 0xaaaa_bbbb);
        cpu.set_reg(Reg32::Ecx, 0xcccc_dddd);
        cpu.eflags = EFLAGS_CF | EFLAGS_ZF | 0x0000_0002;

        let err = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
        let Some(page) = err.page_fault() else {
            panic!("expected page fault");
        };

        assert_eq!(page.linear.0, 0x3000);
        assert_eq!(page.code & crate::x86::mmu::PFEC_PRESENT, 0);
        assert_ne!(page.code & crate::x86::mmu::PFEC_WRITE, 0);
        assert_eq!(ram.read_u64(0x3000), 0x1111_2222_3333_4444);
        assert_eq!(cpu.reg(Reg32::Eax), 0x3333_4444);
        assert_eq!(cpu.reg(Reg32::Edx), 0x1111_2222);
        assert_eq!(cpu.reg(Reg32::Ebx), 0xaaaa_bbbb);
        assert_eq!(cpu.reg(Reg32::Ecx), 0xcccc_dddd);
        assert_eq!(cpu.eflags & (EFLAGS_CF | EFLAGS_ZF), EFLAGS_CF | EFLAGS_ZF);
    }

