    #[test]
    fn rdtsc_segment_override_prefix_does_not_leak_to_next_memory_read() {
        let mut ram = Ram::new();
        ram.data[..8].copy_from_slice(&[
            0x64, 0x0f, 0x31, // fs: rdtsc
            0xa0, // mov al,moffs8
            0x10, 0x00, 0x00, 0x00,
        ]);
        ram.data[0x010] = 0x5a;
        ram.data[0x210] = 0xa5;

        let mut cpu = flat_cpu();
        cpu.set_tsc(0);
        cpu.set_seg_cache(
            SegmentReg::Ds,
            SegmentCache {
                base: 0x000,
                ..cpu.seg(SegmentReg::Ds)
            },
        );
        cpu.set_seg_cache(
            SegmentReg::Fs,
            SegmentCache {
                base: 0x200,
                ..cpu.seg(SegmentReg::Fs)
            },
        );

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 1);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax) & 0xff, 0x5a);
        assert_eq!(cpu.eip, 8);
    }

