    #[test]
    fn perf_counter_linux_probe_sequence_reads_and_programs_evntsel_zero() {
        let mut ram = Ram::new();
        let code = [
            0xb9,
            MSR_EVNTSEL0 as u8,
            (MSR_EVNTSEL0 >> 8) as u8,
            0,
            0, // mov ecx,MSR_EVNTSEL0
            0x0f,
            0x32, // rdmsr
            0x89,
            0xc3, // mov ebx,eax
            0xba,
            0x00,
            0x00,
            0x00,
            0x00, // mov edx,0
            0xb8,
            0x79,
            0x00,
            0x47,
            0x00, // mov eax,0x0047_0079
            0x0f,
            0x30, // wrmsr
            0xb9,
            MSR_EVNTSEL1 as u8,
            (MSR_EVNTSEL1 >> 8) as u8,
            0,
            0, // mov ecx,MSR_EVNTSEL1
            0x31,
            0xc0, // xor eax,eax
            0x31,
            0xd2, // xor edx,edx
            0x0f,
            0x30, // wrmsr
            0xb9,
            MSR_EVNTSEL0 as u8,
            (MSR_EVNTSEL0 >> 8) as u8,
            0,
            0, // mov ecx,MSR_EVNTSEL0
            0x0f,
            0x32, // rdmsr
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);

        let mut cpu = flat_cpu();
        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(cpu.reg(Reg32::Ebx), 0);
        assert_eq!(cpu.reg(Reg32::Eax), 0x0047_0079);
        assert_eq!(cpu.reg(Reg32::Edx), 0);
        assert_eq!(cpu.msr_evntsel, [0x0000_0000_0047_0079, 0]);
    }

