        assert_eq!(step_rdmsr(&mut cpu, MSR_PERFCTR1), Ok(0));
        assert_eq!(step_rdmsr(&mut cpu, MSR_EVNTSEL0), Ok(0));
        assert_eq!(step_rdmsr(&mut cpu, MSR_EVNTSEL1), Ok(0));

        step_wrmsr(&mut cpu, MSR_PERFCTR0, 0xaaaa_bbbb_cccc_dddd).unwrap();
        step_wrmsr(&mut cpu, MSR_PERFCTR1, 0x1234_5678_9abc_def0).unwrap();

        assert_eq!(cpu.tsc(), 0x1111_2222_3333_444a);
