    fn perf_counter_msr_accesses_do_not_advance_or_rebase_tsc() {
        let mut cpu = flat_cpu();
        cpu.set_tsc(0x0102_0304_0506_0708);

        step_wrmsr(&mut cpu, MSR_EVNTSEL0, 0x0000_0000_0047_0079).unwrap();
        assert_eq!(cpu.tsc(), 0x0102_0304_0506_0709);

        step_rdmsr(&mut cpu, MSR_EVNTSEL0).unwrap();
        assert_eq!(cpu.tsc(), 0x0102_0304_0506_070a);

        step_wrmsr(&mut cpu, MSR_PERFCTR0, 0x1234).unwrap();
        assert_eq!(cpu.tsc(), 0x0102_0304_0506_070b);

        step_rdmsr(&mut cpu, MSR_PERFCTR0).unwrap();
        assert_eq!(cpu.tsc(), 0x0102_0304_0506_070c);
        assert_eq!(cpu.msr_perfctr[0], 0x1234);
    }

