    #[test]
    fn p6_wrmsr_filters_high_ecx_bits() {
        // v86 instructions_0f.rs matches the full ECX value.
        let mut cpu = flat_cpu();

        step_wrmsr(
            &mut cpu,
            MSR_BIOS_UPDT_TRIG | 0xffff_c000,
            0x1111_2222_3333_4444,
        )
        .unwrap();
        step_wrmsr(
            &mut cpu,
            MSR_BBL_CR_BUSY | 0x8000_0000,
            0x5555_6666_7777_8888,
        )
        .unwrap();

        assert_eq!(cpu.msr_bios_update_trigger, 0x1111_2222_3333_4444);
        assert_eq!(cpu.msr_bbl_cr_busy, 0x5555_6666_7777_8888);
        assert_eq!(
            step_rdmsr(&mut cpu, MSR_BIOS_UPDT_TRIG),
            Ok(0x1111_2222_3333_4444)
        );
        assert_eq!(
            step_rdmsr(&mut cpu, MSR_BBL_CR_BUSY),
            Ok(0x5555_6666_7777_8888)
        );
    }

