    #[test]
    fn machine_check_linux_probe_sequence_can_enable_and_clear_supported_msrs() {
        let mut ram = Ram::new();
        let code = [
            0xb9,
            MSR_MCG_CTL as u8,
            (MSR_MCG_CTL >> 8) as u8,
            0,
            0, // mov ecx,MSR_MCG_CTL
            0xb8,
            0xff,
            0xff,
            0xff,
            0xff, // mov eax,0xffff_ffff
            0xba,
            0xff,
            0xff,
            0xff,
            0xff, // mov edx,0xffff_ffff
            0x0f,
            0x30, // wrmsr
            0xb9,
            MSR_MC0_CTL as u8,
            (MSR_MC0_CTL >> 8) as u8,
            0,
            0, // mov ecx,MSR_MC0_CTL
            0xb8,
            0xaa,
            0xaa,
            0x55,
            0x55, // mov eax,0x5555_aaaa
            0xba,
            0x78,
            0x56,
            0x34,
            0x12, // mov edx,0x1234_5678
            0x0f,
            0x30, // wrmsr
            0xb9,
            MSR_MCG_STATUS as u8,
            (MSR_MCG_STATUS >> 8) as u8,
            0,
            0, // mov ecx,MSR_MCG_STATUS
            0x31,
            0xc0, // xor eax,eax
            0x31,
            0xd2, // xor edx,edx
            0x0f,
            0x30, // wrmsr
            0xb9,
            (MSR_MC0_CTL + 1) as u8,
            ((MSR_MC0_CTL + 1) >> 8) as u8,
            0,
            0, // mov ecx,MSR_MC0_STATUS
            0x0f,
            0x30, // wrmsr
            0xb9,
            MSR_MCG_STATUS as u8,
            (MSR_MCG_STATUS >> 8) as u8,
            0,
            0, // mov ecx,MSR_MCG_STATUS
            0x0f,
            0x32, // rdmsr
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);

        let mut cpu = flat_cpu();
        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(cpu.msr_mcg_ctl, 0xffff_ffff_ffff_ffff);
        assert_eq!(cpu.msr_mca_ctl[0], 0x1234_5678_5555_aaaa);
        assert_eq!(cpu.reg(Reg32::Eax), 0);
        assert_eq!(cpu.reg(Reg32::Edx), 0);
    }

    #[test]
    fn machine_check_bank_indices_follow_p6_order() {
        // v86 instructions_0f.rs has no MCA banks; IA32_MCG_CAP reads zero.
        let mut cpu = flat_cpu();
        let expected = [
            (0, MSR_MC0_CTL, MSR_MC0_CTL + 1, MSR_MC0_CTL + 2),
            (1, MSR_MC0_CTL + 4, MSR_MC0_CTL + 5, MSR_MC0_CTL + 6),
            (2, MSR_MC0_CTL + 8, MSR_MC0_CTL + 9, MSR_MC0_CTL + 10),
            (3, MSR_MC0_CTL + 12, MSR_MC0_CTL + 13, MSR_MC0_CTL + 14),
            (4, MSR_MC0_CTL + 16, MSR_MC0_CTL + 17, MSR_MC0_CTL + 18),
        ];

        for (bank, ctl, status, addr) in expected {
            let value = 0x0101_0101_0101_0101_u64.wrapping_mul((bank + 1) as u64);
            step_wrmsr(&mut cpu, ctl, value).unwrap();

            assert_eq!(step_rdmsr(&mut cpu, ctl), Ok(value));
            assert_eq!(step_rdmsr(&mut cpu, status), Ok(0));
            assert_eq!(step_rdmsr(&mut cpu, addr), Ok(0));
            assert_eq!(cpu.msr_mca_ctl[bank], value);
        }

        assert_eq!(
            cpu.msr_mca_ctl,
            [
                0x0101_0101_0101_0101,
                0x0202_0202_0202_0202,
                0x0303_0303_0303_0303,
                0x0404_0404_0404_0404,
                0x0505_0505_0505_0505,
            ]
        );
    }

