    #[test]
    fn mtrr_phys_range_edges_work_and_adjacent_indices_fault() {
        let mut cpu = flat_cpu();
        step_wrmsr(&mut cpu, MSR_MTRR_PHYS_BASE0, 0x0000_0000_0010_0006).unwrap();
        step_wrmsr(&mut cpu, MSR_MTRR_PHYS_MASK7, 0x0000_0000_0ff0_0800).unwrap();

        assert_eq!(
            step_rdmsr(&mut cpu, MSR_MTRR_PHYS_BASE0),
            Ok(0x0000_0000_0010_0006)
        );
        assert_eq!(
            step_rdmsr(&mut cpu, MSR_MTRR_PHYS_MASK7),
            Ok(0x0000_0000_0ff0_0800)
        );
        assert_eq!(
            step_rdmsr(&mut cpu, MSR_MTRR_PHYS_BASE0 - 1),
            Err(StepError::GeneralProtection { eip: 0, code: 0 })
        );
        assert_eq!(
            step_rdmsr(&mut cpu, MSR_MTRR_PHYS_MASK7 + 1),
            Err(StepError::GeneralProtection { eip: 0, code: 0 })
        );
        assert_wrmsr_gp(&mut cpu, MSR_MTRR_PHYS_BASE0 - 1, 0);
        assert_wrmsr_gp(&mut cpu, MSR_MTRR_PHYS_MASK7 + 1, 0);
    }

