    #[test]
    fn mtrr_fixed_range_msrs_round_trip_valid_memory_types() {
        let mut cpu = flat_cpu();
        let fixed = 0x0605_0401_0006_0504;
        let fixed_alt = 0x0001_0405_0600_0104;

        step_wrmsr(&mut cpu, MSR_MTRR_FIX64K_00000, fixed).unwrap();
        step_wrmsr(&mut cpu, MSR_MTRR_FIX16K_80000, fixed_alt).unwrap();
        step_wrmsr(&mut cpu, MSR_MTRR_FIX16K_A0000, fixed).unwrap();
        step_wrmsr(&mut cpu, MSR_MTRR_FIX4K_C0000, fixed_alt).unwrap();
        step_wrmsr(&mut cpu, MSR_MTRR_FIX4K_F8000, fixed).unwrap();

        assert_eq!(step_rdmsr(&mut cpu, MSR_MTRR_FIX64K_00000), Ok(fixed));
        assert_eq!(step_rdmsr(&mut cpu, MSR_MTRR_FIX16K_80000), Ok(fixed_alt));
        assert_eq!(step_rdmsr(&mut cpu, MSR_MTRR_FIX16K_A0000), Ok(fixed));
        assert_eq!(step_rdmsr(&mut cpu, MSR_MTRR_FIX4K_C0000), Ok(fixed_alt));
        assert_eq!(step_rdmsr(&mut cpu, MSR_MTRR_FIX4K_F8000), Ok(fixed));
        assert_eq!(cpu.msr_mtrr_fix64k_00000, fixed);
        assert_eq!(cpu.msr_mtrr_fix16k, [fixed_alt, fixed]);
        assert_eq!(cpu.msr_mtrr_fix4k[0], fixed_alt);
        assert_eq!(cpu.msr_mtrr_fix4k[7], fixed);
    }

