    #[test]
    fn pat_msr_accepts_uc_minus_but_rejects_reserved_memory_types() {
        let mut cpu = flat_cpu();
        let valid_pat = 0x0706_0504_0100_0706;
        let old_pat = cpu.msr_pat;

        step_wrmsr(&mut cpu, MSR_PAT, valid_pat).unwrap();
        assert_eq!(cpu.msr_pat, valid_pat);
        assert_eq!(step_rdmsr(&mut cpu, MSR_PAT), Ok(valid_pat));

        assert_wrmsr_gp(&mut cpu, MSR_PAT, (valid_pat & !0xff) | 0x02);
        assert_eq!(cpu.msr_pat, valid_pat);
        assert_wrmsr_gp(&mut cpu, MSR_PAT, 0x0806_0504_0100_0706);
        assert_eq!(cpu.msr_pat, valid_pat);

        cpu.msr_pat = old_pat;
        assert_eq!(step_rdmsr(&mut cpu, MSR_PAT), Ok(old_pat));
    }

    #[test]
    fn pat_msr_accepts_each_valid_pat_memory_type_byte() {
        let mut cpu = flat_cpu();
        let mut pat = 0;
        for (slot, mem_type) in [0_u64, 1, 4, 5, 6, 7, 0, 6].into_iter().enumerate() {
            pat |= mem_type << (slot * 8);
        }

        step_wrmsr(&mut cpu, MSR_PAT, pat).unwrap();
        assert_eq!(step_rdmsr(&mut cpu, MSR_PAT), Ok(pat));

        for slot in 0..8 {
            let invalid = (pat & !(0xff << (slot * 8))) | (0x03 << (slot * 8));
            assert_wrmsr_gp(&mut cpu, MSR_PAT, invalid);
            assert_eq!(cpu.msr_pat, pat);
        }
    }

