        cpu.msr_mtrr_phys[0] = 0x0000_0000_0010_0006;
        cpu.msr_mtrr_fix64k_00000 = 0x0605_0401_0006_0504;
        cpu.msr_mtrr_fix16k = [0x0605_0401_0006_0504, 0x0001_0405_0600_0104];
        cpu.msr_mtrr_fix4k[7] = 0x0605_0401_0006_0504;
        cpu.msr_mtrr_def_type = 0x0c06;
