    #[test]
    fn fninit_and_fwait_reset_x87_state() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0xd9, 0xee, // fldz
            0x9b, // fwait
            0xdb, 0xe3, // fninit
            0xdf, 0xe0, // fnstsw ax
        ]);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        for _ in 0..4 {
            assert_eq!(
                Interpreter::step(&mut cpu, &mut ram).unwrap(),
                StepOutcome::Running
            );
        }
        assert_eq!(read_reg16(&cpu, Reg32::Eax as u8), 0);
        assert_eq!(cpu.fpu.control, 0x037f);
        assert_eq!(cpu.fpu.top, 0);
    }

    #[test]
    fn x87_selftest_stores_real_stack_values() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xd9, 0x7d, 0xea, // fnstcw word [ebp - 22]
            0xd9, 0x6d, 0xea, // fldcw word [ebp - 22]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xdc, 0x05, 0x08, 0x03, 0x00, 0x00, // fadd qword [0x308]
            0xdd, 0x55, 0xe0, // fst qword [ebp - 32]
            0xdd, 0x5d, 0xf0, // fstp qword [ebp - 16]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308]
            0xd9, 0xc9, // fxch st(1)
            0xde, 0xc1, // faddp st(1), st
            0xdf, 0x7d, 0xd8, // fistp qword [ebp - 40]
            0xdf, 0x2d, 0x10, 0x03, 0x00, 0x00, // fild qword [0x310]
            0xdb, 0x5d, 0xfc, // fistp dword [ebp - 4]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xde, 0xd9, // fcompp
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300]
            0xda, 0xe9, // fucompp
            0xdf, 0xe0, // fnstsw ax
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        ram.data[0x300..0x308].copy_from_slice(&2.0f64.to_bits().to_le_bytes());
        ram.data[0x308..0x310].copy_from_slice(&1.5f64.to_bits().to_le_bytes());
        ram.data[0x310..0x318].copy_from_slice(&(-6_i64).to_le_bytes());
        let frame = 0x200usize;

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_reg(Reg32::Ebp, frame as u32);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(
            u16::from_le_bytes(ram.data[frame - 22..frame - 20].try_into().unwrap()),
            0x037f
        );
        assert_eq!(
            f64::from_bits(u64::from_le_bytes(
                ram.data[frame - 32..frame - 24].try_into().unwrap()
            )),
            3.5
        );
        assert_eq!(
            u64::from_le_bytes(ram.data[frame - 40..frame - 32].try_into().unwrap()),
            4
        );
        assert_eq!(
            u64::from_le_bytes(ram.data[frame - 16..frame - 8].try_into().unwrap()),
            3.5f64.to_bits()
        );
        assert_eq!(
            u32::from_le_bytes(ram.data[frame - 4..frame].try_into().unwrap()),
            (-6_i32) as u32
        );
        assert_eq!(read_reg16(&cpu, Reg32::Eax as u8) & 0x4500, 0x4000);
    }

