    #[test]
    fn d9_group6_log_tangent_and_atan_update_stack_like_x87() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xd9, 0xe8, // fld1
            0xd9, 0xf0, // f2xm1
            0xdd, 0x1d, 0x20, 0x03, 0x00, 0x00, // fstp qword [0x320]
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300] = 3.0
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308] = 4.0
            0xd9, 0xf1, // fyl2x: 3.0 * log2(4.0)
            0xdd, 0x1d, 0x28, 0x03, 0x00, 0x00, // fstp qword [0x328]
            0xdd, 0x05, 0x10, 0x03, 0x00, 0x00, // fld qword [0x310] = 0.0
            0xd9, 0xf2, // fptan: push 1.0 over tan(0.0)
            0xdd, 0x1d, 0x30, 0x03, 0x00, 0x00, // fstp qword [0x330]
            0xdd, 0x1d, 0x38, 0x03, 0x00, 0x00, // fstp qword [0x338]
            0xd9, 0xe8, // fld1
            0xd9, 0xe8, // fld1
            0xd9, 0xf3, // fpatan: atan2(1.0, 1.0)
            0xdd, 0x1d, 0x40, 0x03, 0x00, 0x00, // fstp qword [0x340]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        write_f64_mem(&mut ram, 0x300, 3.0);
        write_f64_mem(&mut ram, 0x308, 4.0);
        write_f64_mem(&mut ram, 0x310, 0.0);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_close(read_f64_mem(&ram, 0x320), 1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x328), 6.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x330), 1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x338), 0.0, 0.000_000_001);
        assert_close(
            read_f64_mem(&ram, 0x340),
            core::f64::consts::FRAC_PI_4,
            0.006,
        );
        assert_eq!(cpu.fpu.top, 0);
    }

    #[test]
    fn d9_group6_fxtract_and_stack_pointer_controls_match_reference_shape() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300] = 8.0
            0xd9, 0xf4, // fxtract: ST0 significand, ST1 exponent
            0xdd, 0x1d, 0x08, 0x03, 0x00, 0x00, // fstp qword [0x308]
            0xdd, 0x1d, 0x10, 0x03, 0x00, 0x00, // fstp qword [0x310]
            0xd9, 0xe8, // fld1: TOP 7
            0xd9, 0xf6, // fdecstp: TOP 6, clear C1
            0xdf, 0xe0, // fnstsw ax
            0xd9, 0xf7, // fincstp: TOP 7, clear C1
            0xdd, 0x3d, 0x18, 0x03, 0x00, 0x00, // fnstsw [0x318]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        write_f64_mem(&mut ram, 0x300, 8.0);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.fpu.status = 0x0200;

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_close(read_f64_mem(&ram, 0x308), 1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x310), 3.0, 0.000_000_001);
        assert_eq!(read_reg16(&cpu, Reg32::Eax as u8) & 0x3a00, 0x3000);
        assert_eq!(ram.read_u16(0x318) & 0x3a00, 0x3800);
    }

    #[test]
    fn d9_group7_remainder_sqrt_round_and_scale_are_executed() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300] = divisor 3.0
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308] = dividend 8.0
            0xd9, 0xf8, // fprem: trunc quotient => 2.0
            0xdd, 0x1d, 0x30, 0x03, 0x00, 0x00, // fstp qword [0x330]
            0xdd, 0xd8, // fstp st(0), discard divisor
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300] = divisor 3.0
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308] = dividend 8.0
            0xd9, 0xf5, // fprem1: nearest quotient => -1.0
            0xdd, 0x1d, 0x38, 0x03, 0x00, 0x00, // fstp qword [0x338]
            0xdd, 0xd8, // fstp st(0), discard divisor
            0xdd, 0x05, 0x10, 0x03, 0x00, 0x00, // fld qword [0x310] = 9.0
            0xd9, 0xfa, // fsqrt
            0xdd, 0x1d, 0x40, 0x03, 0x00, 0x00, // fstp qword [0x340]
            0xdd, 0x05, 0x18, 0x03, 0x00, 0x00, // fld qword [0x318] = 2.5
            0xd9, 0xfc, // frndint, nearest-even
            0xdd, 0x1d, 0x48, 0x03, 0x00, 0x00, // fstp qword [0x348]
            0xdd, 0x05, 0x20, 0x03, 0x00, 0x00, // fld qword [0x320] = scale 3.0
            0xdd, 0x05, 0x28, 0x03, 0x00, 0x00, // fld qword [0x328] = 1.5
            0xd9, 0xfd, // fscale
            0xdd, 0x1d, 0x50, 0x03, 0x00, 0x00, // fstp qword [0x350]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        write_f64_mem(&mut ram, 0x300, 3.0);
        write_f64_mem(&mut ram, 0x308, 8.0);
        write_f64_mem(&mut ram, 0x310, 9.0);
        write_f64_mem(&mut ram, 0x318, 2.5);
        write_f64_mem(&mut ram, 0x320, 3.0);
        write_f64_mem(&mut ram, 0x328, 1.5);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_close(read_f64_mem(&ram, 0x330), 2.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x338), -1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x340), 3.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x348), 2.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x350), 12.0, 0.000_000_001);
    }

    #[test]
    fn d9_group7_log1p_and_trig_push_results_in_x87_order() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xdd, 0x05, 0x00, 0x03, 0x00, 0x00, // fld qword [0x300] = multiplier 3.0
            0xd9, 0xe8, // fld1
            0xd9, 0xf9, // fyl2xp1: 3.0 * log2(2.0)
            0xdd, 0x1d, 0x18, 0x03, 0x00, 0x00, // fstp qword [0x318]
            0xd9, 0xe8, // fld1
            0xd9, 0xfe, // fsin(1.0)
            0xdd, 0x1d, 0x20, 0x03, 0x00, 0x00, // fstp qword [0x320]
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308] = 0.0
            0xd9, 0xff, // fcos(0.0)
            0xdd, 0x1d, 0x28, 0x03, 0x00, 0x00, // fstp qword [0x328]
            0xdd, 0x05, 0x08, 0x03, 0x00, 0x00, // fld qword [0x308] = 0.0
            0xd9, 0xfb, // fsincos: push cos over sin
            0xdd, 0x1d, 0x30, 0x03, 0x00, 0x00, // fstp qword [0x330]
            0xdd, 0x1d, 0x38, 0x03, 0x00, 0x00, // fstp qword [0x338]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        write_f64_mem(&mut ram, 0x300, 3.0);
        write_f64_mem(&mut ram, 0x308, 0.0);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_close(read_f64_mem(&ram, 0x318), 3.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x320), 0.841_470_984, 0.000_001);
        assert_close(read_f64_mem(&ram, 0x328), 1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x330), 1.0, 0.000_000_001);
        assert_close(read_f64_mem(&ram, 0x338), 0.0, 0.000_000_001);
        assert_eq!(cpu.fpu.top, 0);
        assert_eq!(cpu.fpu.status & 0x0400, 0);
    }

