    #[test]
    fn daa_adjusts_packed_bcd_and_sets_flags() {
        // OF is undefined; v86 arith.rs does not write it, so a pending lazy
        // OF reverts to the stored bit.
        let mut ram = Ram::new();
        ram.data[0] = 0x27; // daa

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_reg(Reg32::Eax, 0x1234_009a);
        cpu.eflags = EFLAGS_OF | 0x0000_0002;

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );

        assert_eq!(cpu.reg(Reg32::Eax), 0x1234_0000);
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
        assert_ne!(cpu.eflags & EFLAGS_AF, 0);
        assert_ne!(cpu.eflags & crate::x86::cpu::EFLAGS_ZF, 0);
        assert_ne!(cpu.eflags & crate::x86::cpu::EFLAGS_PF, 0);
        assert_eq!(cpu.eflags & (crate::x86::cpu::EFLAGS_SF | EFLAGS_OF), 0);
    }

