    #[test]
    fn vm86_pushfw_with_vme_uses_virtual_interrupt_flag_image() {
        for (vif, expected_if) in [(false, 0), (true, EFLAGS_IF as u16)] {
            let mut ram = Ram::new();
            ram.data[0] = 0x9c; // pushfw in virtual-8086 mode
            ram.data[0x11e..0x120].copy_from_slice(&[0xaa, 0xaa]);

            let mut cpu = flat_cpu();
            cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0));
            cpu.set_seg_cache(SegmentReg::Ss, real_mode_segment(0x10));
            cpu.set_reg(Reg32::Esp, 0x20);
            cpu.cr4 = CR4_VME;
            cpu.eflags = EFLAGS_VM | EFLAGS_IF | EFLAGS_CF | 0x0000_0002;
            if vif {
                cpu.eflags |= EFLAGS_VIF;
            }

            step_running(&mut cpu, &mut ram);

            let image = ram.read_u16(0x11e);
            assert_eq!(cpu.reg(Reg32::Esp), 0x1e);
            assert_eq!(image & EFLAGS_IOPL as u16, EFLAGS_IOPL as u16);
            assert_eq!(image & EFLAGS_IF as u16, expected_if);
            assert_ne!(image & EFLAGS_CF as u16, 0);
            assert_ne!(image & 0x0002, 0);
        }
    }

