    #[test]
    fn cli_sti_ignore_operand_size_override_and_keep_privilege_checks() {
        for opcode in [0xfa, 0xfb] {
            for cpl in [0, 3] {
                for initial_if in [false, true] {
                    let mut cpu = Cpu::new();
                    cpu.enter_protected_flat(0, 0);
                    cpu.set_seg_cache(
                        SegmentReg::Cs,
                        SegmentCache::flat(8 | cpl, SEGMENT_FLAG_DEFAULT_BIG),
                    );
                    cpu.replace_eflags(2 | if initial_if { EFLAGS_IF } else { 0 });
                    let mut ram = Ram::new();
                    ram.data[..2].copy_from_slice(&[0x66, opcode]);
                    let result = Interpreter::step(&mut cpu, &mut ram);
                    assert_eq!(cpu.tsc(), 1);
                    if cpl == 0 {
                        assert_eq!(result, Ok(StepOutcome::Running));
                        assert_eq!(cpu.eip, 2);
                        assert_eq!(cpu.flag(EFLAGS_IF), opcode == 0xfb);
                        assert_eq!(cpu.interrupt_shadow(), opcode == 0xfb && !initial_if);
                    } else {
                        assert_eq!(
                            result,
                            Err(StepError::GeneralProtection { eip: 0, code: 0 })
                        );
                        assert_eq!(cpu.flag(EFLAGS_IF), initial_if);
                        assert!(!cpu.interrupt_shadow());
                    }
                }
            }
        }
    }

