    #[test]
    fn cli_and_sti_update_if_when_iopl_allows() {
        let mut ram = Ram::new();
        ram.data[..4].copy_from_slice(&[0xfa, 0xfb, 0x90, 0xf4]);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.eflags = EFLAGS_IF | 0x0000_0002;

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );
        assert_eq!(cpu.eflags & EFLAGS_IF, 0);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );
        assert_ne!(cpu.eflags & EFLAGS_IF, 0);
        assert!(cpu.interrupt_shadow());
        assert!(!cpu.maskable_interrupts_enabled());

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );
        assert!(!cpu.interrupt_shadow());
        assert!(cpu.maskable_interrupts_enabled());
    }

