    #[test]
    fn real_mode_segment_reloads_keep_unreal_data_and_stack_caches() {
        for (instruction, seg, prefix, pop) in [
            (&[0x8e, 0xd8][..], SegmentReg::Ds, 0x3e, false), // MOV DS,AX
            (&[0x1f][..], SegmentReg::Ds, 0x3e, true),        // POP DS
            (&[0xc5, 0x1d, 0, 9, 0, 0][..], SegmentReg::Ds, 0x3e, false), // LDS
            (&[0x8e, 0xd0][..], SegmentReg::Ss, 0x36, false), // MOV SS,AX
            (&[0x17][..], SegmentReg::Ss, 0x36, true),        // POP SS
            (
                &[0x0f, 0xb2, 0x1d, 0, 9, 0, 0][..],
                SegmentReg::Ss,
                0x36,
                false,
            ), // LSS
        ] {
            let mut ram = WideRam {
                data: std::vec![0; 0x22000],
            };
            let mut code = std::vec![
                0x0f, 0x20, 0xc0, // MOV EAX,CR0
                0x25, 0xfe, 0xff, 0xff, 0xff, // AND EAX,~PE
                0x0f, 0x22, 0xc0, // MOV CR0,EAX
                0xb8, 0x10, 0, 0, 0, // MOV EAX,10h
            ];
            code.extend_from_slice(instruction);
            code.extend_from_slice(&[prefix, 0xa1, 0, 0, 1, 0, 0x50]); // MOV EAX,seg:[10000h]; PUSH
            ram.data[..code.len()].copy_from_slice(&code);
            ram.data[0x904..0x906].copy_from_slice(&0x10u16.to_le_bytes());
            ram.data[0x10004..0x10008].copy_from_slice(&0x10u32.to_le_bytes());
            ram.data[0x10100..0x10104].copy_from_slice(&0x1234_5678u32.to_le_bytes());
            let mut cpu = flat_cpu();
            let flags = if seg == SegmentReg::Ss {
                0xd093
            } else {
                0xd0b3
            };
            let limit = if seg == SegmentReg::Ss {
                0x1ffff
            } else {
                u32::MAX
            };
            cpu.set_seg_cache(seg, SegmentCache::new(0x18, 0, limit, flags));
            cpu.set_reg(Reg32::Esp, 0x10004);

            for _ in 0..5 {
                step_running(&mut cpu, &mut ram);
            }
            assert_eq!(cpu.cr0 & CR0_PE, 0);
            assert_eq!(cpu.seg(seg), SegmentCache::new(0x10, 0x100, limit, flags));
            step_running(&mut cpu, &mut ram);
            assert_eq!(cpu.reg(Reg32::Eax), 0x1234_5678);
            step_running(&mut cpu, &mut ram);
            let sp = 0x10000 + if pop { 4 } else { 0 };
            assert_eq!(cpu.reg(Reg32::Esp), sp);
            let physical = sp as usize + cpu.seg(SegmentReg::Ss).base as usize;
            assert_eq!(
                &ram.data[physical..physical + 4],
                &0x1234_5678u32.to_le_bytes()
            );
        }
    }

    #[test]
    fn real_mode_cs_transfers_keep_unreal_limits_and_default_size() {
        for opcode in [0xea, 0x9a, 0xcb, 0xcf, 0xcd] {
            for limit in [0xff, 0x1ffff] {
                let mut ram = WideRam {
                    data: std::vec![0; 0x22000],
                };
                let target = if opcode == 0xcd { 0x200u32 } else { 0x10020 };
                ram.data[..7].copy_from_slice(&[opcode, 0x20, 0, 1, 0, 0x10, 0]);
                if opcode == 0xcd {
                    ram.data[1] = 0x21;
                }
                ram.data[0x1084..0x1088].copy_from_slice(&[0, 2, 0x10, 0]);
                ram.data[0x10014..0x10020].fill(0xaa);
                ram.data[0x10020..0x10024].copy_from_slice(&target.to_le_bytes());
                ram.data[0x10024..0x10028].copy_from_slice(&0x10u32.to_le_bytes());
                ram.data[0x10028..0x1002c].copy_from_slice(&2u32.to_le_bytes());
                let physical = 0x100 + target as usize;
                ram.data[physical..physical + 5].copy_from_slice(&[0xb8, 0x44, 0x33, 0x22, 0x11]);
                let mut cpu = flat_cpu();
                cpu.cr0 &= !CR0_PE;
                let flags = if limit == 0xff { 0x509b } else { 0xd09b };
                let old_cs = SegmentCache::new(0x20, 0, limit, flags);
                cpu.set_seg_cache(SegmentReg::Cs, old_cs);
                cpu.idtr = TableReg {
                    base: 0x1000,
                    limit: 0x3ff,
                };
                cpu.set_reg(Reg32::Esp, 0x10020);

                let result = match Interpreter::step(&mut cpu, &mut ram) {
                    Err(StepError::SoftwareInterrupt {
                        vector,
                        return_eip,
                        fault_eip,
                    }) => {
                        // Observe entry faults before the event dispatcher delivers them.
                        enter_interrupt(
                            &mut cpu, &mut ram, vector, return_eip, None, true, fault_eip,
                        )
                        .map(|()| StepOutcome::Running)
                    }
                    result => result,
                };
                if limit < target {
                    assert_eq!(
                        result,
                        Err(StepError::GeneralProtection { eip: 0, code: 0 })
                    );
                    assert_eq!(cpu.seg(SegmentReg::Cs), old_cs);
                    assert_eq!(cpu.reg(Reg32::Esp), 0x10020);
                    if opcode == 0xcd {
                        assert_eq!(&ram.data[0x1001a..0x10020], &[2, 0, 0x20, 0, 2, 0]);
                    } else {
                        assert_eq!(&ram.data[0x10014..0x10020], &[0xaa; 12]);
                    }
                    continue;
                }
                assert_eq!(result, Ok(StepOutcome::Running));
                assert_eq!(cpu.eip, target);
                assert_eq!(
                    cpu.seg(SegmentReg::Cs),
                    SegmentCache::new(0x10, 0x100, limit, flags)
                );
                let sp = match opcode {
                    0x9a => 0x10018,
                    0xcb => 0x10028,
                    0xcf => 0x1002c,
                    0xcd => 0x1001a,
                    _ => 0x10020,
                };
                assert_eq!(cpu.reg(Reg32::Esp), sp);
                step_running(&mut cpu, &mut ram);
                assert_eq!(cpu.reg(Reg32::Eax), 0x1122_3344);
                assert_eq!(cpu.eip, target + 5);
            }
        }
    }

    #[test]
    fn reset_real_cache_reload_stays_writable_after_entering_protected_mode() {
        for reset in [false, true] {
            let mut ram = Ram::new();
            let code = [
                0xb8, 0x10, 0, // MOV AX,10h
                0x8e, 0xd8, // MOV DS,AX
                0x0f, 0x20, 0xc0, // MOV EAX,CR0
                0x66, 0x83, 0xc8, 1, // OR EAX,PE
                0x0f, 0x22, 0xc0, // MOV CR0,EAX
                0xc7, 0x06, 0, 2, 0x34, 0x12, // MOV WORD [200h],1234h
            ];
            ram.data[..code.len()].copy_from_slice(&code);
            let mut cpu = Cpu::new();
            if reset {
                cpu.reset_bios();
                let mut cs = cpu.seg(SegmentReg::Cs);
                cs.selector = 0;
                cs.base = 0;
                cpu.set_seg_cache(SegmentReg::Cs, cs);
                cpu.eip = 0;
            }
            for _ in 0..6 {
                step_running(&mut cpu, &mut ram);
            }
            assert_ne!(cpu.cr0 & CR0_PE, 0);
            assert_eq!(cpu.seg(SegmentReg::Ds).flags, 0x0093);
            assert_eq!(ram.read_u16(0x300), 0x1234);
        }
    }

    #[test]
    fn virtual_8086_segment_load_forces_64k_cache_and_16bit_stack() {
        let mut ram = Ram::new();
        ram.data[..5].copy_from_slice(&[0x8e, 0xe8, 0x8e, 0xd0, 0x50]); // MOV GS/SS,AX; PUSH AX

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_seg_cache(SegmentReg::Cs, v86_segment(0));
        cpu.replace_eflags(cpu.effective_eflags() | EFLAGS_VM);
        cpu.set_reg(Reg32::Eax, 0x10);
        cpu.set_reg(Reg32::Esp, 0x1234_0020);

        step_running(&mut cpu, &mut ram);
        step_running(&mut cpu, &mut ram);
        step_running(&mut cpu, &mut ram);

        for seg in [SegmentReg::Gs, SegmentReg::Ss] {
            assert_eq!(cpu.seg(seg), SegmentCache::new(0x10, 0x100, 0xffff, 0x00f3));
        }
        assert_eq!(cpu.reg(Reg32::Esp), 0x1234_001e);
        assert_eq!(ram.read_u16(0x11e), 0x10);
    }

    #[test]
    fn segment_accessed_write_precedes_hidden_cache_stack_and_offset_commit() {
        // GDT is supervisor-only even for the CPL3 loads. Descriptor reads
        // succeed; only the accessed-byte write can require WP or set PTE.D.
        for cpl in [0u16, 3] {
            for wp in [false, true] {
                for writable in [false, true] {
                    for accessed in [false, true] {
                        for form in 0..6 {
                            for operand16 in [false, true] {
                                let stack_segment = form >= 3;
                                let seg = if stack_segment {
                                    SegmentReg::Ss
                                } else {
                                    SegmentReg::Gs
                                };
                                let mut ram = Ram::new();
                                let instruction: &[u8] = match form {
                                    0 => &[0x8e, 0xe8],                   // MOV GS,AX
                                    1 => &[0x0f, 0xa9],                   // POP GS
                                    2 => &[0x0f, 0xb5, 0x1d, 0, 9, 0, 0], // LGS EBX,[900h]
                                    3 => &[0x8e, 0xd0],                   // MOV SS,AX
                                    4 => &[0x17],                         // POP SS
                                    _ => &[0x0f, 0xb2, 0x1d, 0, 9, 0, 0], // LSS EBX,[900h]
                                };
                                let start = usize::from(operand16);
                                ram.data[0] = 0x66;
                                ram.data[start..start + instruction.len()]
                                    .copy_from_slice(instruction);
                                let selector = 0x10 | cpl;
                                ram.write_u32(0x800, u32::from(selector));
                                ram.write_u32(0x900, 0x1234);
                                ram.write_u16(if operand16 { 0x902 } else { 0x904 }, selector);
                                ram.write_u32(0x1000, 0x2007);
                                ram.write_u32(0x2000, 7);
                                ram.write_u32(0x200c, 0x3001 | if writable { 2 } else { 0 });
                                ram.write_u32(0x3010, 0xffff);
                                let rights = 0x92 | ((cpl as u8) << 5) | u8::from(accessed);
                                ram.write_u32(0x3014, 0x00cf_0000 | (u32::from(rights) << 8));
                                let mut cpu = Cpu::new();
                                cpu.enter_protected_flat(0, 0);
                                cpu.set_seg_cache(
                                    SegmentReg::Cs,
                                    SegmentCache::flat(8 | cpl, 0xc09b | (cpl << 5)),
                                );
                                cpu.set_seg_cache(
                                    SegmentReg::Ds,
                                    SegmentCache::flat(0x10 | cpl, 0xc093 | (cpl << 5)),
                                );
                                // Old 16-bit SS and high ESP also check POP SS's
                                // successful advancement after loading a 32-bit SS.
                                cpu.set_seg_cache(
                                    SegmentReg::Ss,
                                    SegmentCache::flat(0x10 | cpl, 0x8093 | (cpl << 5)),
                                );
                                cpu.cr0 |= CR0_PG | if wp { crate::x86::cpu::CR0_WP } else { 0 };
                                cpu.cr3 = 0x1000;
                                cpu.gdtr = TableReg {
                                    base: 0x3000,
                                    limit: 0x17,
                                };
                                cpu.regs[0] = 0xcafe_0000 | u32::from(selector);
                                cpu.regs[3] = 0xdead_beef;
                                cpu.regs[4] = 0xbeef_0800;
                                cpu.cr2 = 0xdead_beef;
                                let old_segment = cpu.seg(seg);
                                let old_regs = cpu.regs;
                                let result = Interpreter::step(&mut cpu, &mut ram);
                                let fault = wp && !writable && !accessed;
                                if fault {
                                    assert_eq!(
                                        result,
                                        Err(StepError::PageFault(mmu::PageFault {
                                            linear: LinearAddr(0x3015),
                                            code: 3,
                                        })),
                                        "form={form} cpl={cpl} operand16={operand16}"
                                    );
                                    assert_eq!(cpu.cr2, 0x3015);
                                    assert_eq!(cpu.seg(seg), old_segment);
                                    assert_eq!(cpu.regs, old_regs);
                                    assert_eq!(ram.data[0x3015], rights);
                                } else {
                                    assert!(result.is_ok(), "{result:?} form={form} cpl={cpl}");
                                    assert_eq!(cpu.seg(seg).selector, selector);
                                    assert_eq!(cpu.seg(seg).flags & 0xff, u16::from(rights | 1));
                                    assert_eq!(ram.data[0x3015], rights | 1);
                                    assert_eq!(cpu.cr2, 0xdead_beef);
                                    let popped = matches!(form, 1 | 4);
                                    assert_eq!(
                                        cpu.regs[4],
                                        old_regs[4]
                                            + if popped {
                                                if operand16 { 2 } else { 4 }
                                            } else {
                                                0
                                            }
                                    );
                                    if matches!(form, 2 | 5) {
                                        assert_eq!(
                                            cpu.regs[3],
                                            if operand16 { 0xdead_1234 } else { 0x1234 }
                                        );
                                    }
                                }
                                let wrote = !fault && !accessed;
                                assert_eq!(
                                    ram.read_u32(0x200c) & 0x60,
                                    0x20 | if wrote { 0x40 } else { 0 }
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn segment_faults_preserve_restart_selector_and_destinations() {
        // The same absent LDT descriptor is reached through data/stack loads
        // and far transfers. The OS needs its TI bit and the original EIP to
        // make the descriptor present and retry without losing a stack frame.
        for (code, access, vector) in [
            (&[0x8e, 0xd8][..], 0x12, 11),                // mov ds, ax
            (&[0x8e, 0xd0][..], 0x12, 12),                // mov ss, ax
            (&[0x1f][..], 0x12, 11),                      // pop ds
            (&[0xc5, 0x05, 0, 1, 0, 0][..], 0x12, 11),    // lds eax, [100h]
            (&[0x9a, 0, 0, 0, 0, 0x0c, 0][..], 0x1a, 11), // call far
            (&[0xea, 0, 0, 0, 0, 0x0c, 0][..], 0x1a, 11), // jmp far
            (&[0xcb][..], 0x1a, 11),                      // retf
            (&[0xcf][..], 0x1a, 11),                      // iret
        ] {
            let mut ram = Ram::new();
            let mut cpu = Cpu::new();
            cpu.enter_protected_flat(0x200, 0);
            cpu.set_reg(Reg32::Esp, 0x300);
            cpu.ldtr = 0x28;
            cpu.ldtr_cache = SegmentCache::new(0x28, 0x40, 0x0f, 0x82);
            ram.write_descriptor(1, 0x00cf_0000 | (access << 8));
            ram.data[0x200..0x200 + code.len()].copy_from_slice(code);
            ram.write_u32(0x100, 0x1122_3344);
            ram.write_u16(0x104, 0x0c);
            ram.write_u32(0x300, if code[0] == 0x1f { 0x0c } else { 0 });
            ram.write_u32(0x304, 0x0c);
            ram.write_u32(0x308, 2);
            cpu.set_reg(Reg32::Eax, 0x0c);
            let regs = cpu.regs;
            let segments = [
                cpu.seg(SegmentReg::Cs),
                cpu.seg(SegmentReg::Ss),
                cpu.seg(SegmentReg::Ds),
            ];
            let before = ram.data;
            let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
            assert_eq!(
                error.exception(0x200),
                Some((vector, Some(0x0c), 0x200)),
                "{code:02x?}: {error:?}"
            );
            assert_eq!(cpu.regs, regs, "{code:02x?}");
            assert_eq!(
                [
                    cpu.seg(SegmentReg::Cs),
                    cpu.seg(SegmentReg::Ss),
                    cpu.seg(SegmentReg::Ds)
                ],
                segments
            );
            assert_eq!(ram.data, before);
        }
    }

    #[test]
    fn segment_faults_null_data_selectors_skip_descriptors_but_ss_faults() {
        for selector in 0..4 {
            let mut ram = Ram::new();
            let mut cpu = Cpu::new();
            cpu.enter_protected_flat(0x200, 0);
            cpu.set_reg(Reg32::Esp, 0x300);
            cpu.gdtr.base = u32::MAX - 7;
            cpu.gdtr.limit = 0xffff;
            cpu.set_reg(Reg32::Eax, selector);
            ram.data[0x200..0x202].copy_from_slice(&[0x8e, 0xd8]); // mov ds, ax
            step_running(&mut cpu, &mut ram);
            assert_eq!(
                cpu.seg(SegmentReg::Ds),
                SegmentCache::new(selector as u16, 0, 0, 0)
            );
            cpu.eip = 0x200;
            ram.data[0x201] = 0xd0; // mov ss, ax
            let old_ss = cpu.seg(SegmentReg::Ss);
            assert_eq!(
                Interpreter::step(&mut cpu, &mut ram),
                Err(StepError::GeneralProtection {
                    eip: 0x200,
                    code: 0
                })
            );
            assert_eq!(cpu.seg(SegmentReg::Ss), old_ss);
        }
    }

    #[test]
    fn segment_faults_outer_returns_check_stack_type_before_presence() {
        for opcode in [0xcb, 0xcf] {
            for (access, vector) in [(0x72, 12), (0x12, 13), (0x7a, 13)] {
                let mut ram = Ram::new();
                let mut cpu = Cpu::new();
                cpu.enter_protected_flat(0x200, 0);
                cpu.set_reg(Reg32::Esp, 0x300);
                cpu.gdtr = TableReg {
                    base: 0x40,
                    limit: 0x1f,
                };
                ram.write_descriptor(3, 0x00cf_fb00); // ring 3 code, already accessed
                cpu.ldtr = 0x28;
                cpu.ldtr_cache = SegmentCache::new(0x28, 0x40, 0x27, 0x82);
                ram.write_descriptor(4, 0x00cf_0000 | (access << 8));
                ram.data[0x200] = opcode;
                ram.write_u32(0x300, 0x1234);
                ram.write_u32(0x304, 0x1b);
                let tail = if opcode == 0xcf {
                    ram.write_u32(0x308, 0x202);
                    0x30c
                } else {
                    0x308
                };
                ram.write_u32(tail, 0x400);
                ram.write_u32(tail + 4, 0x27); // LDT index 4, RPL3
                let cs = cpu.seg(SegmentReg::Cs);
                let ss = cpu.seg(SegmentReg::Ss);
                let flags = cpu.eflags;
                let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
                assert_eq!(
                    error.exception(0x200),
                    Some((vector, Some(0x24), 0x200)),
                    "opcode={opcode:02x} access={access:02x}"
                );
                assert_eq!(cpu.seg(SegmentReg::Cs), cs);
                assert_eq!(cpu.seg(SegmentReg::Ss), ss);
                assert_eq!(cpu.reg(Reg32::Esp), 0x300);
                assert_eq!(cpu.eflags, flags);
            }
        }
    }

    #[test]
    fn segment_faults_system_descriptors_preserve_context_and_selector() {
        for (modrm, descriptor_type) in [(0xd0, 2), (0xd8, 9)] {
            for (selector, access, vector) in [
                (0x0b, descriptor_type, 11),
                (0x0b, 0x12, 13),
                (0x0f, descriptor_type, 13),
            ] {
                let mut ram = Ram::new();
                let mut cpu = Cpu::new();
                cpu.enter_protected_flat(0x200, 0);
                cpu.gdtr = TableReg {
                    base: 0x40,
                    limit: 0x0f,
                };
                ram.write_descriptor(1, access << 8);
                ram.data[0x200..0x203].copy_from_slice(&[0x0f, 0x00, modrm]);
                cpu.set_reg(Reg32::Eax, selector);
                cpu.ldtr = 0x18;
                cpu.ldtr_cache = SegmentCache::new(0x18, 0x1000, 0x1f, 0x82);
                cpu.tr = 0x20;
                cpu.tr_cache = SegmentCache::new(0x20, 0x2000, 0x67, 0x8b);
                let old = (cpu.ldtr_cache, cpu.tr_cache);
                let before = ram.data;
                let error = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
                assert_eq!(
                    error.exception(0x200),
                    Some((vector, Some(selector & !3), 0x200))
                );
                assert_eq!((cpu.ldtr, cpu.tr), (0x18, 0x20));
                assert_eq!((cpu.ldtr_cache, cpu.tr_cache), old);
                assert_eq!(ram.data, before);
            }
        }

        // A call/task gate may itself be in the LDT. Its absence names that
        // gate, not its target TSS/code selector, and must retain the TI bit.
        for gate_type in [4, 12, 5] {
            let mut ram = Ram::new();
            let mut cpu = Cpu::new();
            cpu.enter_protected_flat(0x200, 0);
            cpu.ldtr = 0x18;
            cpu.ldtr_cache = SegmentCache::new(0x18, 0x40, 0x0f, 0x82);
            write_call_gate_descriptor(&mut ram, 1, 0x20, 0, gate_type, 0);
            ram.data[0x200..0x207].copy_from_slice(&[0x9a, 0, 0, 0, 0, 0x0c, 0]);
            let old_sp = cpu.reg(Reg32::Esp);
            assert_eq!(
                Interpreter::step(&mut cpu, &mut ram),
                Err(StepError::SegmentNotPresent {
                    eip: 0x200,
                    code: 0x0c
                })
            );
            assert_eq!(cpu.reg(Reg32::Esp), old_sp);
        }
        // LLDT faults in the old context; a task's absent LDT is #TS after
        // committing the new task. Do not fold those into the same validator.
        let mut ram = Ram::new();
        install_task_switch_gdt(&mut ram, false, 0x67);
        let (low, high) = descriptor_image(0xb00, 0x17, 0x02, 0);
        ram.write_descriptor_raw(4, low, high);
        let mut incoming = test_tss32(0x2222, 0x900);
        incoming.ldtr = 0x20;
        write_tss32(&mut ram, NEXT_TSS_BASE, incoming);
        let mut cpu = task_switch_cpu(0x111);
        assert_eq!(
            task_switch_for_far_selector(
                &mut cpu,
                &mut ram,
                NEXT_TSS_SEL,
                TaskSwitchSource::Call,
                0x100
            ),
            Err(StepError::TaskSwitchFault {
                eip: 0x2222,
                vector: 10,
                code: 0x20
            })
        );
        assert_eq!(cpu.tr, NEXT_TSS_SEL);
        assert_eq!(cpu.eip, 0x2222);
    }

    #[test]
    fn protected_data_segment_load_validates_type_present_and_privilege() {
        let mut ram = Ram::new();
        ram.data[..2].copy_from_slice(&[0x8e, 0xd8]); // mov ds, ax

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x17,
        };
        cpu.set_reg(Reg32::Eax, 0x10);
        ram.write_descriptor(2, 0x0000_8200);
        let old_ds = cpu.seg(SegmentReg::Ds);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 0x10 })
        );
        assert_eq!(cpu.seg(SegmentReg::Ds), old_ds);

        cpu.eip = 0;
        ram.write_descriptor(2, 0x004f_1200);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::SegmentNotPresent { eip: 0, code: 0x10 })
        );
        assert_eq!(cpu.seg(SegmentReg::Ds), old_ds);

        cpu.eip = 0;
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache::flat(0x1b, SEGMENT_FLAG_DEFAULT_BIG),
        );
        ram.write_descriptor(2, 0x00cf_9200);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 0x10 })
        );
        assert_eq!(cpu.seg(SegmentReg::Ds), old_ds);

        cpu.eip = 0;
        cpu.set_reg(Reg32::Eax, 0x13);
        ram.write_descriptor(2, 0x00cf_f200);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.seg(SegmentReg::Ds).selector, 0x13);
    }

    #[test]
    fn mov_ss_requires_writable_dpl_matching_stack_selector() {
        let mut ram = Ram::new();
        ram.data[..2].copy_from_slice(&[0x8e, 0xd0]); // mov ss, ax
        ram.write_descriptor(2, 0x00cf_9200);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x17,
        };
        cpu.set_reg(Reg32::Eax, 0x10);

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x10);

        cpu.eip = 0;
        cpu.set_reg(Reg32::Eax, 0x13);
        let old_ss = cpu.seg(SegmentReg::Ss);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 0x10 })
        );
        assert_eq!(cpu.seg(SegmentReg::Ss), old_ss);

        cpu.eip = 0;
        cpu.set_reg(Reg32::Eax, 0x10);
        ram.write_descriptor(2, 0x00cf_9a00);
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::GeneralProtection { eip: 0, code: 0x10 })
        );
        assert_eq!(cpu.seg(SegmentReg::Ss), old_ss);
    }

