    #[test]
    fn arpl_virtual_8086_mode_is_ud_and_preserves_memory_destination() {
        let mut ram = Ram::new();
        ram.data[..6].copy_from_slice(&[
            0x63, 0x0d, 0x20, 0x00, 0x00, 0x00, // arpl [0x20], cx
        ]);
        ram.write_u16(0x20, 0x0010);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.eflags |= EFLAGS_VM | crate::x86::cpu::EFLAGS_ZF;
        cpu.set_reg(Reg32::Ecx, 0x0003);

        step_ud(&mut cpu, &mut ram, 0);

        assert_eq!(cpu.eip, 2);
        assert_eq!(ram.read_u16(0x20), 0x0010);
        assert!(cpu.flag(crate::x86::cpu::EFLAGS_ZF));
    }

