    #[test]
    fn code_segment_update_changes_fetch_base_and_operand_size() {
        let mut ram = Ram::new();
        ram.data[..3].copy_from_slice(&[0xb8, 0x34, 0x12]); // mov ax,0x1234
        ram.data[0x100..0x105].copy_from_slice(&[0xb8, 0x78, 0x56, 0x34, 0x12]); // mov eax,0x12345678
        let mut cpu = flat_cpu();
        cpu.set_reg(Reg32::Eax, 0xabcd_0000);
        cpu.set_seg_cache(SegmentReg::Cs, SegmentCache::new(0x10, 0, 0xffff, 0x009a));

        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0xabcd_1234);
        assert_eq!(cpu.eip, 3);

        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache::new(0x10, 0x100, 0xffff, 0x409a),
        );
        cpu.eip = 0;
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.reg(Reg32::Eax), 0x1234_5678);
        assert_eq!(cpu.eip, 5);
    }

