    #[test]
    fn ltr_caches_tss_descriptor_for_later_io_bitmap_checks() {
        let mut ram = Ram::new();
        let code = [
            0xb8, 0x28, 0x00, 0x00, 0x00, // mov eax,0x28
            0x0f, 0x00, 0xd8, // ltr ax
            0xec, // in al,dx
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        install_io_tss_at(&mut ram, IO_TSS_BASE, false, IO_TSS_LIMIT);
        ram.write_u16(IO_TSS_ALT_BASE + 0x66, IO_BITMAP_BASE);
        set_io_bitmap_denied_at(&mut ram, IO_TSS_ALT_BASE, 0x03f8, true);
        ram.io_reads[0] = 0x5a;

        let mut cpu = flat_cpu();
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x2f,
        };
        cpu.set_reg(Reg32::Edx, 0x03f8);

        step_running(&mut cpu, &mut ram);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.tr, IO_TSS_SEL);
        assert_eq!(cpu.tr_cache.selector, IO_TSS_SEL);
        assert_eq!(cpu.tr_cache.base, IO_TSS_BASE as u32);
        assert_eq!(cpu.tr_cache.limit, IO_TSS_LIMIT);
        assert_eq!(cpu.tr_cache.flags & 0x00ff, 0x008b);
        assert_ne!(
            ram.descriptor_high(usize::from(IO_TSS_SEL >> 3)) & 0x0000_0200,
            0
        );

        let (alt_low, alt_high) = descriptor_image(IO_TSS_ALT_BASE as u32, IO_TSS_LIMIT, 0x8b, 0);
        ram.write_descriptor_raw(usize::from(IO_TSS_SEL >> 3), alt_low, alt_high);
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache {
                selector: 0x1b,
                ..cpu.seg(SegmentReg::Cs)
            },
        );

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );
        assert_eq!(ram.io_read_count, 1);
        assert_eq!(ram.io_read_ports[0], 0x03f8);
        assert_eq!(cpu.reg(Reg32::Eax) & 0xff, 0x5a);
    }

