    #[test]
    fn long_rep_movsb_chunks_at_restartable_instruction_boundary() {
        let mut ram = Ram::new();
        ram.data[..2].copy_from_slice(&[
            0xf3, 0xa4, // rep movsb
        ]);
        let count = MAX_STRING_REPEAT_UNITS_PER_STEP + 2;
        for index in 0..count as usize {
            ram.data[0x0100 + index] = (index & 0xff) as u8;
        }

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_reg(Reg32::Esi, 0x0100);
        cpu.set_reg(Reg32::Edi, 0x2000);
        cpu.set_reg(Reg32::Ecx, count);

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0);
        assert_eq!(
            cpu.reg(Reg32::Esi),
            0x0100 + MAX_STRING_REPEAT_UNITS_PER_STEP
        );
        assert_eq!(
            cpu.reg(Reg32::Edi),
            0x2000 + MAX_STRING_REPEAT_UNITS_PER_STEP
        );
        assert_eq!(cpu.reg(Reg32::Ecx), 2);
        assert_eq!(ram.data[0x2000], 0);
        assert_eq!(
            ram.data[0x2000 + MAX_STRING_REPEAT_UNITS_PER_STEP as usize - 1],
            0xff
        );

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 2);
        assert_eq!(cpu.reg(Reg32::Ecx), 0);
        assert_eq!(
            ram.data[0x2000 + MAX_STRING_REPEAT_UNITS_PER_STEP as usize],
            0
        );
        assert_eq!(
            ram.data[0x2000 + MAX_STRING_REPEAT_UNITS_PER_STEP as usize + 1],
            1
        );
    }

