    #[test]
    fn dd_fnsave_frstor_preserve_environment_and_register_images() {
        let mut ram = Ram::new();
        let code = [
            0xdb, 0xe3, // fninit
            0xd9, 0xe8, // fld1: physical ST7 = 1.0
            0xd9, 0xee, // fldz: physical ST6 = 0.0, TOP 6
            0xdd, 0x35, 0x00, 0x03, 0x00, 0x00, // fnsave [0x300]
            0xdd, 0x25, 0x00, 0x03, 0x00, 0x00, // frstor [0x300]
            0xdd, 0x1d, 0x80, 0x03, 0x00, 0x00, // fstp qword [0x380]
            0xdd, 0x1d, 0x88, 0x03, 0x00, 0x00, // fstp qword [0x388]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        ram.data[0x300..0x36c].fill(0xaa);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(ram.read_u16(0x300), 0x037f);
        assert_eq!(ram.read_u16(0x304) & 0x3800, 0x3000);
        assert_eq!(ram.data[0x300 + 28..0x300 + 28 + 10], [0; 10]);
        assert_eq!(
            &ram.data[0x300 + 28 + 10..0x300 + 28 + 20],
            &[0, 0, 0, 0, 0, 0, 0, 0x80, 0xff, 0x3f]
        );
        assert_eq!(
            f64::from_bits(u64::from_le_bytes(
                ram.data[0x380..0x388].try_into().unwrap()
            )),
            0.0
        );
        assert_eq!(
            f64::from_bits(u64::from_le_bytes(
                ram.data[0x388..0x390].try_into().unwrap()
            )),
            1.0
        );
    }

