    #[test]
    fn descriptor_query_instructions_are_ud_outside_protected_mode() {
        let cases = [
            (
                [0x0f, 0x02, 0xc3], // lar eax,bx
                Reg32::Eax,
                0x1111_2222,
            ),
            (
                [0x0f, 0x03, 0xcb], // lsl ecx,bx
                Reg32::Ecx,
                0x3333_4444,
            ),
            (
                [0x0f, 0x00, 0xe3], // verr bx
                Reg32::Edx,
                0x5555_6666,
            ),
            (
                [0x0f, 0x00, 0xeb], // verw bx
                Reg32::Esi,
                0x7777_8888,
            ),
        ];

        for (code, watched_reg, watched_value) in cases {
            let mut ram = Ram::new();
            ram.data[..3].copy_from_slice(&code);
            let mut cpu = Cpu::new();
            cpu.set_reg(Reg32::Ebx, 0x10);
            cpu.set_reg(watched_reg, watched_value);
            cpu.set_flag(crate::x86::cpu::EFLAGS_ZF, true);

            step_ud(&mut cpu, &mut ram, 0);
            assert_eq!(cpu.reg(watched_reg), watched_value);
            assert!(cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        }

        for (code, watched_reg, watched_value) in cases {
            let mut ram = Ram::new();
            ram.data[..3].copy_from_slice(&code);
            let mut cpu = Cpu::new();
            cpu.enter_protected_flat(0, 0);
            cpu.eflags |= EFLAGS_VM;
            cpu.set_reg(Reg32::Ebx, 0x10);
            cpu.set_reg(watched_reg, watched_value);
            cpu.set_flag(crate::x86::cpu::EFLAGS_ZF, true);

            step_ud(&mut cpu, &mut ram, 0);
            assert_eq!(cpu.reg(watched_reg), watched_value);
            assert!(cpu.flag(crate::x86::cpu::EFLAGS_ZF));
        }
    }

