    #[test]
    fn verr_and_verw_follow_read_write_and_privilege_rules() {
        let mut ram = Ram::new();
        let code = [
            0xbb, 0x1b, 0x00, 0x00, 0x00, // mov ebx,0x1b
            0x0f, 0x00, 0xe3, // verr bx
            0x0f, 0x94, 0x05, 0x00, 0x03, 0x00, 0x00, // setz [0x300]
            0x0f, 0x00, 0xeb, // verw bx
            0x0f, 0x94, 0x05, 0x01, 0x03, 0x00, 0x00, // setz [0x301]
            0xbb, 0x23, 0x00, 0x00, 0x00, // mov ebx,0x23
            0x0f, 0x00, 0xe3, // verr bx
            0x0f, 0x94, 0x05, 0x02, 0x03, 0x00, 0x00, // setz [0x302]
            0x0f, 0x00, 0xeb, // verw bx
            0x0f, 0x94, 0x05, 0x03, 0x03, 0x00, 0x00, // setz [0x303]
            0xbb, 0x2b, 0x00, 0x00, 0x00, // mov ebx,0x2b
            0x0f, 0x00, 0xe3, // verr bx
            0x0f, 0x94, 0x05, 0x04, 0x03, 0x00, 0x00, // setz [0x304]
            0x0f, 0x00, 0xeb, // verw bx
            0x0f, 0x94, 0x05, 0x05, 0x03, 0x00, 0x00, // setz [0x305]
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        ram.write_descriptor(3, 0x00cf_f000);
        ram.write_descriptor(4, 0x00cf_f200);
        ram.write_descriptor(5, 0x00cf_fa00);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x2f,
        };
        cpu.set_seg_cache(SegmentReg::Cs, flat_big_cache(0x1b));

        while cpu.eip < (code.len() - 1) as u32 {
            step_running(&mut cpu, &mut ram);
        }

        assert_eq!(ram.data[0x300], 1);
        assert_eq!(ram.data[0x301], 0);
        assert_eq!(ram.data[0x302], 1);
        assert_eq!(ram.data[0x303], 1);
        assert_eq!(ram.data[0x304], 1);
        assert_eq!(ram.data[0x305], 0);
    }

