    #[test]
    fn mov_control_registers_read_write_cr0_cr2_cr3_cr4() {
        let mut ram = Ram::new();
        let cr4_value = CR4_VME
            | CR4_PVI
            | CR4_TSD
            | CR4_DE
            | CR4_PSE
            | CR4_PAE
            | CR4_MCE
            | CR4_PGE
            | CR4_PCE
            | CR4_OSFXSR;
        let code = [
            0xb8,
            0x00,
            0x10,
            0x00,
            0x00, // mov eax,0x1000
            0x0f,
            0x22,
            0xd8, // mov cr3,eax
            0x0f,
            0x20,
            0xdb, // mov ebx,cr3
            0xb8,
            0xaa,
            0x55,
            0x00,
            0x00, // mov eax,0x55aa
            0x0f,
            0x22,
            0xd0, // mov cr2,eax
            0x0f,
            0x20,
            0xd1, // mov ecx,cr2
            0xb8,
            cr4_value as u8,
            (cr4_value >> 8) as u8,
            (cr4_value >> 16) as u8,
            (cr4_value >> 24) as u8, // mov eax,cr4_value
            0x0f,
            0x22,
            0xe0, // mov cr4,eax
            0x0f,
            0x20,
            0xe2, // mov edx,cr4
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(cpu.cr3, 0x1000);
        assert_eq!(cpu.reg(Reg32::Ebx), 0x1000);
        assert_eq!(cpu.cr2, 0x55aa);
        assert_eq!(cpu.reg(Reg32::Ecx), 0x55aa);
        assert_eq!(cpu.cr4, cr4_value);
        assert_eq!(cpu.reg(Reg32::Edx), cr4_value);
    }

