    #[test]
    fn mov_control_registers_ignore_mod_bits_and_consume_only_modrm() {
        let mut ram = Ram::new();
        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        ram.data[..4].copy_from_slice(&[
            0x0f, 0x20, 0x40, 0xf4, // mod bits are ignored: mov eax,cr0; hlt
        ]);
        cpu.cr0 = CR0_PE | CR0_WP | CR0_TS;
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.reg(Reg32::Eax), CR0_PE | CR0_WP | CR0_TS);

        ram.data[..4].copy_from_slice(&[
            0x0f, 0x22, 0x53, 0xf4, // mod bits are ignored: mov cr2,ebx; hlt
        ]);
        cpu.eip = 0;
        cpu.cr2 = 0;
        cpu.set_reg(Reg32::Ebx, 0x1122_3344);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.cr2, 0x1122_3344);

        ram.data[..4].copy_from_slice(&[
            0x0f, 0x22, 0x9b, 0xf4, // mod bits are ignored: mov cr3,ebx; hlt
        ]);
        cpu.eip = 0;
        cpu.cr3 = 0;
        cpu.set_reg(Reg32::Ebx, 0x0000_2000);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.cr3, 0x0000_2000);

        ram.data[..4].copy_from_slice(&[
            0x0f, 0x20, 0xa2, 0xf4, // mod bits are ignored: mov edx,cr4; hlt
        ]);
        cpu.eip = 0;
        cpu.cr4 = CR4_VME | CR4_PSE | CR4_PGE;
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.reg(Reg32::Edx), CR4_VME | CR4_PSE | CR4_PGE);
    }

    #[test]
    fn mov_control_registers_do_not_consume_sib_or_displacement_bytes() {
        let mut ram = Ram::new();
        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);

        ram.data[..4].copy_from_slice(&[
            0x0f, 0x20, 0x1c, 0xf4, // rm=100 would be SIB for memory forms
        ]);
        cpu.cr3 = 0x0000_3000;
        cpu.set_reg(Reg32::Esp, 0xaaaa_bbbb);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.reg(Reg32::Esp), 0x0000_3000);
        assert_eq!(ram.data[3], 0xf4);

        ram.data[..7].copy_from_slice(&[
            0x0f, 0x22, 0x95, 0xf4, 0x90, 0x90, 0x90, // mod=10 would have disp32
        ]);
        cpu.eip = 0;
        cpu.cr2 = 0;
        cpu.set_reg(Reg32::Ebp, 0x5566_7788);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 3);
        assert_eq!(cpu.cr2, 0x5566_7788);
        assert_eq!(ram.data[3], 0xf4);
    }

    #[test]
    fn mov_control_registers_reject_unknown_indices_as_invalid_opcode() {
        let mut ram = Ram::new();
        ram.data[..3].copy_from_slice(&[0x0f, 0x20, 0xe8]); // mov eax,cr5

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.set_reg(Reg32::Eax, 0xaabb_ccdd);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::InvalidOpcode { eip: 0 })
        );
        assert_eq!(cpu.reg(Reg32::Eax), 0xaabb_ccdd);

        ram.data[..3].copy_from_slice(&[0x0f, 0x22, 0xe8]); // mov cr5,eax
        cpu.eip = 0;
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::InvalidOpcode { eip: 0 })
        );
        assert_eq!(cpu.cr0, CR0_PE);
        assert_eq!(cpu.cr2, 0);
        assert_eq!(cpu.cr3, 0);
        assert_eq!(cpu.cr4, 0);

        for code in [
            [0x0f, 0x20, 0xc8], // mov eax,cr1
            [0x0f, 0x20, 0xf0], // mov eax,cr6
            [0x0f, 0x20, 0xf8], // mov eax,cr7
            [0x0f, 0x22, 0xc8], // mov cr1,eax
            [0x0f, 0x22, 0xf0], // mov cr6,eax
            [0x0f, 0x22, 0xf8], // mov cr7,eax
        ] {
            ram.data[..3].copy_from_slice(&code);
            cpu.eip = 0;
            cpu.set_reg(Reg32::Eax, 0x5566_7788);
            step_ud(&mut cpu, &mut ram, 0);
            assert_eq!(cpu.reg(Reg32::Eax), 0x5566_7788);
            assert_eq!(cpu.cr0, CR0_PE);
            assert_eq!(cpu.cr2, 0);
            assert_eq!(cpu.cr3, 0);
            assert_eq!(cpu.cr4, 0);
        }
    }

