    #[test]
    fn lldt_and_ltr_validate_system_descriptors_and_ltr_marks_busy() {
        let mut ram = Ram::new();
        let code = [
            0xb8, 0x28, 0x00, 0x00, 0x00, // mov eax,0x28
            0x0f, 0x00, 0xd0, // lldt ax
            0xb8, 0x30, 0x00, 0x00, 0x00, // mov eax,0x30
            0x0f, 0x00, 0xd8, // ltr ax
            0xf4, // hlt
        ];
        ram.data[..code.len()].copy_from_slice(&code);
        let (ldt_low, ldt_high) = descriptor_image(0x0300, 0x0027, 0x82, 0x00);
        let (tss_low, tss_high) = descriptor_image(0x0400, 0x0067, 0x89, 0x00);
        ram.write_descriptor_raw(5, ldt_low, ldt_high);
        ram.write_descriptor_raw(6, tss_low, tss_high);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x37,
        };

        while Interpreter::step(&mut cpu, &mut ram).unwrap() != StepOutcome::Halted {}

        assert_eq!(cpu.ldtr, 0x28);
        assert_eq!(cpu.ldtr_cache.base, 0x0300);
        assert_eq!(cpu.ldtr_cache.limit, 0x0027);
        assert_eq!(cpu.ldtr_cache.flags, 0x82);
        assert_eq!(cpu.tr, 0x30);
        assert_eq!(cpu.tr_cache.selector, 0x30);
        assert_eq!(cpu.tr_cache.base, 0x0400);
        assert_eq!(cpu.tr_cache.limit, 0x0067);
        assert_eq!(cpu.tr_cache.flags & 0x00ff, 0x008b);
        assert_eq!(ram.descriptor_high(6) & 0x0000_0200, 0x0000_0200);
    }

    #[test]
    fn task_switch_to_v86_initializes_all_segment_caches() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[0xea, 0, 0, 0, 0, NEXT_TSS_SEL as u8, 0]);
        install_task_switch_gdt(&mut ram, false, 0x67);
        let mut image = test_tss32(0x200, 0x1234_0020);
        image.eflags |= EFLAGS_VM;
        image.segments = [0x10, 0x20, 0x30, 0x40, 0x50, 0x60];
        write_tss32(&mut ram, NEXT_TSS_BASE, image);
        ram.data[0x400..0x403].copy_from_slice(&[0xb8, 0x34, 0x12]); // MOV AX,1234h
        let mut cpu = task_switch_cpu(0);

        step_running(&mut cpu, &mut ram);

        for seg in [
            SegmentReg::Es,
            SegmentReg::Cs,
            SegmentReg::Ss,
            SegmentReg::Ds,
            SegmentReg::Fs,
            SegmentReg::Gs,
        ] {
            let selector = image.segments[seg as usize];
            assert_eq!(
                cpu.seg(seg),
                SegmentCache::new(selector, u32::from(selector) << 4, 0xffff, 0x00f3)
            );
        }
        assert_eq!(cpu.cpl(), 3);
        step_running(&mut cpu, &mut ram);
        assert_eq!(cpu.eip, 0x203);
        assert_eq!(cpu.reg(Reg32::Eax) as u16, 0x1234);
    }

    #[test]
    fn far_call_to_32bit_tss_sets_busy_backlink_nt_and_saves_current_task() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x9a, // call far ptr16:32
            0xef,
            0xbe,
            0xad,
            0xde, // ignored offset for task switch
            (NEXT_TSS_SEL & 0x00ff) as u8,
            (NEXT_TSS_SEL >> 8) as u8,
        ]);
        install_task_switch_gdt(&mut ram, false, 0x0067);

        let mut image = test_tss32(0x2222, 0x0200);
        image.cr3 = 0x0012_3000;
        image.eflags = EFLAGS_IF | EFLAGS_ZF | 0x0000_0002;
        write_tss32(&mut ram, NEXT_TSS_BASE, image);
        ram.write_u32(CURRENT_TSS_BASE + 0x1c, 0xdead_c0de);

        let mut cpu = task_switch_cpu(0);
        cpu.cr3 = 0xfeed_0000;
        cpu.eflags = EFLAGS_CF | 0x0000_0002;
        cpu.set_reg(Reg32::Eax, 0xaabb_ccdd);
        cpu.set_reg(Reg32::Esp, 0x0180);
        cpu.dr[7] = 0xffff_ffff;

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );

        assert_eq!(cpu.tr, NEXT_TSS_SEL);
        assert_eq!(cpu.tr_cache.selector, NEXT_TSS_SEL);
        assert_eq!(cpu.tr_cache.base, NEXT_TSS_BASE as u32);
        assert_eq!(cpu.tr_cache.limit, 0x0067);
        assert_eq!(cpu.tr_cache.flags & 0x00ff, 0x008b);
        assert_eq!(cpu.eip, image.eip);
        assert_eq!(cpu.cr3, 0xfeed_0000); // PG=0 leaves CR3 unchanged.
        assert_eq!(cpu.regs, image.regs);
        assert_eq!(cpu.ldtr, 0);
        assert_task_segments_loaded(&cpu);
        assert_ne!(cpu.cr0 & CR0_TS, 0);
        assert_eq!(cpu.dr[7] & 0x0000_0155, 0);
        assert_eq!(
            cpu.eflags,
            image.eflags | EFLAGS_NT | 0x0000_0002,
            "CALL task switch forces NT after loading the new EFLAGS image"
        );

        assert_ne!(ram.descriptor_high(5) & 0x0000_0200, 0);
        assert_ne!(ram.descriptor_high(6) & 0x0000_0200, 0);
        assert_eq!(ram.read_u16(NEXT_TSS_BASE), CURRENT_TSS_SEL);
        assert_eq!(ram.read_u32(CURRENT_TSS_BASE + 0x1c), 0xdead_c0de);
        assert_current_tss_saved(
            &ram,
            CURRENT_TSS_BASE,
            7,
            EFLAGS_CF | 0x0000_0002,
            0x0180,
            0xaabb_ccdd,
        );
    }

