    #[test]
    fn task_switch_trap_precedes_the_first_instruction_and_returns_to_it() {
        for opcode in [0x9a, 0xea, 0xcf] {
            // CALL, JMP, nested-task IRET
            let mut ram = Ram::new();
            ram.data[..7].copy_from_slice(&[opcode, 0, 0, 0, 0, NEXT_TSS_SEL as u8, 0]);
            ram.data[0x200] = 0xcf; // #DB handler: IRET
            ram.data[0x240..0x245].copy_from_slice(&[0xb8, 0xef, 0xbe, 0xad, 0xde]);
            install_task_switch_gdt(&mut ram, opcode == 0xcf, 0x67);
            ram.write_u16(CURRENT_TSS_BASE, NEXT_TSS_SEL);
            ram.write_idt_gate(0x300, 1, TASK_CODE_SEL, 0x200, 0x8e);
            let mut image = test_tss32(0x240, 0x280);
            image.eflags = EFLAGS_CF | 2; // IF=0 must not block a task trap.
            image.trap = 1;
            write_tss32(&mut ram, NEXT_TSS_BASE, image);
            let mut cpu = task_switch_cpu(0);
            cpu.idtr = TableReg {
                base: 0x300,
                limit: 0x1ff,
            };
            cpu.eflags = 2 | if opcode == 0xcf { EFLAGS_NT } else { 0 };
            cpu.dr[6] = 0x600f; // retain BS/BD, replace stale address-breakpoint bits
            cpu.dr[7] = 0x2400; // GD must clear when #DB is entered

            let trap = Interpreter::step(&mut cpu, &mut ram).expect_err("TSS T bit must raise #DB");
            #[cfg(feature = "r86chip")]
            assert_eq!(
                (cpu.chip_counts.completed, cpu.chip_counts.fault_attempts),
                (1, 0),
                "a committed task switch counts even though its #DB is delivered next"
            );
            assert_eq!(trap.exception(0), Some((1, None, image.eip)));
            assert_eq!(cpu.tr, NEXT_TSS_SEL);
            assert_eq!(cpu.reg(Reg32::Eax), image.regs[Reg32::Eax as usize]);
            assert_eq!(cpu.dr[6], 0xe000);
            assert_eq!(cpu.dr[7] & (1 << 13), 0);
            deliver_exception(&mut cpu, &mut ram, 1, None, image.eip).unwrap();
            assert_eq!(cpu.eip, 0x200);
            assert_eq!(cpu.reg(Reg32::Esp), 0x274);
            assert_eq!(ram.read_u32(0x274), image.eip);
            assert_eq!(ram.read_u32(0x278), u32::from(TASK_CODE_SEL));
            let expected_flags = image.eflags | if opcode == 0x9a { EFLAGS_NT } else { 0 };
            assert_eq!(ram.read_u32(0x27c), expected_flags); // no synthesized RF
            step_running(&mut cpu, &mut ram); // IRET returns to unexecuted first instruction
            assert_eq!(cpu.eip, image.eip);
            step_running(&mut cpu, &mut ram);
            assert_eq!(cpu.reg(Reg32::Eax), 0xdead_beef);
            assert_eq!(ram.read_u16(NEXT_TSS_BASE + 0x64), 1);
        }
    }

    #[test]
    fn task_gate_trap_is_a_new_event_even_after_double_fault_entry() {
        for event in 0..3 {
            let mut ram = Ram::new();
            install_task_switch_gdt(&mut ram, false, 0x67);
            ram.write_idt_gate(0x300, 1, TASK_CODE_SEL, 0x200, 0x8e);
            let vector = if event == 0 { 8 } else { 0x30 };
            ram.write_idt_gate(0x300, vector, NEXT_TSS_SEL, 0, 0x85);
            let mut image = test_tss32(0x240, 0x280);
            image.eflags = EFLAGS_CF | 2;
            image.trap = 1;
            write_tss32(&mut ram, NEXT_TSS_BASE, image);
            let mut cpu = task_switch_cpu(0x1234);
            cpu.idtr = TableReg {
                base: 0x300,
                limit: 0x1ff,
            };
            let result = match event {
                0 => deliver_exception(&mut cpu, &mut ram, 8, Some(0), 0x1234),
                1 => deliver_software_interrupt_event(&mut cpu, &mut ram, vector, 0x1236, 0x1234),
                _ => deliver_external_interrupt(&mut cpu, &mut ram, vector, 0x1234),
            };
            result.unwrap();
            assert_eq!(cpu.tr, NEXT_TSS_SEL);
            assert_eq!(cpu.eip, 0x200, "#DB must precede the task entry point");
            let stack = if event == 0 { 0x270 } else { 0x274 };
            assert_eq!(cpu.reg(Reg32::Esp), stack as u32);
            assert_eq!(ram.read_u32(stack), image.eip);
            assert_eq!(ram.read_u32(stack + 8), image.eflags | EFLAGS_NT);
            if event == 0 {
                assert_eq!(ram.read_u32(stack + 12), 0); // #DF error code below #DB frame
            }
            assert_ne!(cpu.dr[6] & (1 << 15), 0);
        }
    }

    #[test]
    fn task_switch_trap_does_not_hide_incoming_segment_faults() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[0x9a, 0, 0, 0, 0, NEXT_TSS_SEL as u8, 0]);
        install_task_switch_gdt(&mut ram, false, 0x67);
        let mut image = test_tss32(0x240, 0x280);
        image.trap = 1;
        image.segments[SegmentReg::Ss as usize] = 0x40; // beyond GDT
        write_tss32(&mut ram, NEXT_TSS_BASE, image);
        let mut cpu = task_switch_cpu(0);
        cpu.dr[6] = 0;
        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::TaskSwitchFault {
                eip: image.eip,
                vector: 10,
                code: 0x40
            })
        );
        assert_eq!(cpu.tr, NEXT_TSS_SEL);
        assert_eq!(cpu.dr[6] & (1 << 15), 0);
    }

    #[test]
    fn task_switch_rejects_short_tss_descriptor_without_mutation() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x9a,
            0,
            0,
            0,
            0,
            (NEXT_TSS_SEL & 0x00ff) as u8,
            (NEXT_TSS_SEL >> 8) as u8,
        ]);
        install_task_switch_gdt(&mut ram, false, 0x0066);
        ram.write_u32(CURRENT_TSS_BASE + 0x20, 0xfeed_face);
        let old_current_high = ram.descriptor_high(5);
        let old_next_high = ram.descriptor_high(6);

        let mut cpu = task_switch_cpu(0);
        cpu.set_reg(Reg32::Eax, 0x0102_0304);
        cpu.set_reg(Reg32::Esp, 0x01c0);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram),
            Err(StepError::InvalidTss {
                eip: 0,
                code: u32::from(NEXT_TSS_SEL)
            })
        );
        assert_eq!(cpu.tr, CURRENT_TSS_SEL);
        assert_eq!(cpu.reg(Reg32::Eax), 0x0102_0304);
        assert_eq!(cpu.reg(Reg32::Esp), 0x01c0);
        assert_eq!(ram.descriptor_high(5), old_current_high);
        assert_eq!(ram.descriptor_high(6), old_next_high);
        assert_eq!(ram.read_u32(CURRENT_TSS_BASE + 0x20), 0xfeed_face);
    }

    #[test]
    fn task16_call_and_iret_preserve_paging_and_both_task_formats() {
        for paging in [false, true] {
            let mut ram = Ram::new();
            install_task_switch_gdt(&mut ram, false, 0x2b);
            let (low, high) = descriptor_image(NEXT_TSS_BASE as u32, 0x2b, 0x81, 0);
            ram.write_descriptor_raw(6, low, high);
            let (low, high) = descriptor_image(0, 0xffff, 0x93, 0);
            ram.write_descriptor_raw(3, low, high); // Word stack, still a 32-bit CS.
            ram.data[..7].copy_from_slice(&[0x9a, 0, 0, 0, 0, NEXT_TSS_SEL as u8, 0]);
            ram.data[0x200] = 0xcf;
            ram.data[NEXT_TSS_BASE + 0x2c..NEXT_TSS_BASE + 0x68].fill(0xa5);
            let mut image = test_tss32(0x200, 0x280);
            image.eflags = EFLAGS_CF | 2;
            write_tss16(&mut ram, NEXT_TSS_BASE, image);
            ram.write_u32(CURRENT_TSS_BASE + 0x1c, 0x1000);
            ram.write_u32(0x1000, 0x2003);
            ram.write_u32(0x2000, 3);
            let mut cpu = task_switch_cpu(0);
            cpu.cr3 = 0x1000;
            if paging {
                cpu.cr0 |= CR0_PG;
            }
            cpu.set_reg(Reg32::Eax, 0x1234_5678);
            cpu.set_reg(Reg32::Esp, 0x190);
            cpu.replace_eflags(EFLAGS_ID | EFLAGS_CF | 2);
            let original_regs = cpu.regs;
            step_running(&mut cpu, &mut ram);
            assert_eq!(cpu.tr, NEXT_TSS_SEL);
            assert_eq!(cpu.tr_cache.flags & 15, 3);
            assert_eq!(cpu.cr3, 0x1000); // No CR3 field exists in a 286 TSS.
            assert_eq!(cpu.regs, image.regs.map(|reg| 0xffff_0000 | (reg & 0xffff)));
            assert_eq!(cpu.eip, 0x200);
            assert_eq!(cpu.effective_eflags(), EFLAGS_NT | EFLAGS_CF | 2);
            assert_eq!(cpu.seg(SegmentReg::Fs).selector, 0);
            assert_eq!(cpu.seg(SegmentReg::Gs).selector, 0);
            assert_eq!(ram.read_u16(NEXT_TSS_BASE), CURRENT_TSS_SEL);
            assert_ne!(ram.descriptor_high(5) & 0x200, 0);

            step_running(&mut cpu, &mut ram); // IRET from word TSS to dword TSS.
            assert_eq!(cpu.tr, CURRENT_TSS_SEL);
            assert_eq!(cpu.eip, 7);
            assert_eq!(cpu.regs, original_regs);
            assert_eq!(cpu.effective_eflags(), EFLAGS_ID | EFLAGS_CF | 2);
            assert_eq!(cpu.cr3, 0x1000);
            assert_eq!(ram.descriptor_high(6) >> 8 & 15, 1);
            assert_eq!(ram.read_u16(NEXT_TSS_BASE + 0x0e), 0x201);
            assert_eq!(ram.read_u16(NEXT_TSS_BASE + 0x10), EFLAGS_CF as u16 | 2);
            assert_eq!(ram.read_u16(NEXT_TSS_BASE + 0x1a), 0x280);
            assert!(
                ram.data[NEXT_TSS_BASE + 0x2c..NEXT_TSS_BASE + 0x68]
                    .iter()
                    .all(|v| *v == 0xa5)
            );
        }
    }

    #[test]
    fn task16_exception_gate_pushes_a_word_before_a_late_ip_fault() {
        for code_limit in [0xffff, 0x1ff] {
            let mut ram = Ram::new();
            install_task_switch_gdt(&mut ram, false, 0x2b);
            let (low, high) = descriptor_image(NEXT_TSS_BASE as u32, 0x2b, 0x81, 0);
            ram.write_descriptor_raw(6, low, high);
            let (low, high) = descriptor_image(0, code_limit, 0x9b, 0x40);
            ram.write_descriptor_raw(2, low, high);
            let (low, high) = descriptor_image(0, 0xffff, 0x93, 0);
            ram.write_descriptor_raw(3, low, high);
            ram.write_idt_gate(0x300, 13, NEXT_TSS_SEL, 0, 0x85);
            write_tss16(&mut ram, NEXT_TSS_BASE, test_tss32(0x200, 0x280));
            ram.write_u32(0x27c, 0xa5a5_a5a5);
            let mut cpu = task_switch_cpu(0x180);
            cpu.idtr = TableReg {
                base: 0x300,
                limit: 0x1ff,
            };
            // Inspect the first task-entry fault before recursive #DF delivery.
            let result = enter_interrupt(&mut cpu, &mut ram, 13, 0x180, Some(0xbeef), false, 0x180);
            assert_eq!(
                result,
                if code_limit >= 0x200 {
                    Ok(())
                } else {
                    Err(StepError::TaskSwitchFault {
                        eip: 0x200,
                        vector: 13,
                        code: 0,
                    })
                }
            );
            assert_eq!(cpu.tr, NEXT_TSS_SEL);
            assert_eq!(cpu.eip, 0x200);
            assert_eq!(cpu.reg(Reg32::Esp), 0xffff_027e);
            assert_eq!(ram.read_u16(0x27e), 0xbeef);
            assert_eq!(ram.read_u16(0x27c), 0xa5a5); // CS.D does not choose the error width.
            assert_eq!(ram.read_u16(NEXT_TSS_BASE), CURRENT_TSS_SEL);
        }
    }

