    #[test]
    fn call_gate_to_inner_privilege_switches_stack_and_copies_parameters() {
        let mut ram = Ram::new();
        ram.data[..7].copy_from_slice(&[
            0x9a, // call far ptr16:32 through a DPL3 call gate
            0,
            0,
            0,
            0, // ignored by the call gate path
            (CALL_GATE_SEL & 0x00ff) as u8,
            (CALL_GATE_SEL >> 8) as u8,
        ]);
        install_call_gate_gdt(&mut ram, 0xec, 2, CALL_KERNEL_CODE_SEL, 0x0000_2000);
        ram.write_u32(CALL_TSS_BASE + 0x04, 0x0300);
        ram.write_u16(CALL_TSS_BASE + 0x08, CALL_KERNEL_DATA_SEL);
        ram.write_u32(0x0200, 0xaaaa_1111);
        ram.write_u32(0x0204, 0xbbbb_2222);

        let mut cpu = call_gate_cpu_cpl3(0);
        cpu.set_reg(Reg32::Esp, 0x0200);

        assert_eq!(
            Interpreter::step(&mut cpu, &mut ram).unwrap(),
            StepOutcome::Running
        );

        assert_eq!(ram.data[0x4d] & 1, 1);
        assert_eq!(ram.data[0x55] & 1, 1);
        assert_eq!(cpu.eip, 0x0000_2000);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, CALL_KERNEL_CODE_SEL);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, CALL_KERNEL_DATA_SEL);
        assert_eq!(cpu.cpl(), 0);
        assert_eq!(cpu.reg(Reg32::Esp), 0x02e8);
        assert_eq!(ram.read_u32(0x02e8), 7);
        assert_eq!(ram.read_u32(0x02ec), u32::from(CALL_USER_CODE_SEL));
        assert_eq!(ram.read_u32(0x02f0), 0xaaaa_1111);
        assert_eq!(ram.read_u32(0x02f4), 0xbbbb_2222);
        assert_eq!(ram.read_u32(0x02f8), 0x0200);
        assert_eq!(ram.read_u32(0x02fc), u32::from(CALL_USER_DATA_SEL));
    }

