    #[test]
    fn upstream_near_branches_use_operand_size_in_both_code_segment_sizes() {
        for default16 in [false, true] {
            for override_size in [false, true] {
                let operand16 = default16 != override_size;
                for opcode in [0x74, 0xeb, 0xe0, 0xe1, 0xe2, 0xe3, 0xe8, 0xe9, 0x0f] {
                    let mut code = std::vec::Vec::new();
                    if override_size {
                        code.push(0x66);
                    }
                    code.push(opcode);
                    if opcode == 0x0f {
                        code.push(0x84);
                    }
                    code.push(2);
                    if matches!(opcode, 0xe8 | 0xe9 | 0x0f) {
                        code.push(0);
                        if !operand16 {
                            code.extend_from_slice(&[0, 0]);
                        }
                    }
                    let mut ram = Ram::new();
                    ram.data[..code.len()].copy_from_slice(&code);
                    let mut cpu = wrap_code_cpu(0x1_0000);
                    cpu.set_seg_cache(
                        SegmentReg::Cs,
                        SegmentCache {
                            flags: if default16 {
                                0
                            } else {
                                SEGMENT_FLAG_DEFAULT_BIG
                            },
                            ..cpu.seg(SegmentReg::Cs)
                        },
                    );
                    cpu.set_reg(Reg32::Ecx, if opcode == 0xe3 { 0 } else { 2 });
                    cpu.set_reg(Reg32::Esp, 0x200);
                    cpu.set_flag(EFLAGS_ZF, opcode != 0xe0);
                    step_running(&mut cpu, &mut ram);
                    let next = 0x1_0000 + code.len() as u32;
                    let target = if operand16 {
                        (next + 2) & 0xffff
                    } else {
                        next + 2
                    };
                    assert_eq!(
                        cpu.eip, target,
                        "opcode {opcode:02x}, default16={default16}, override={override_size}"
                    );
                    if opcode == 0xe8 {
                        if operand16 {
                            assert_eq!(cpu.reg(Reg32::Esp), 0x1fe);
                            assert_eq!(ram.read_u16(0x1fe), next as u16);
                        } else {
                            assert_eq!(cpu.reg(Reg32::Esp), 0x1fc);
                            assert_eq!(ram.read_u32(0x1fc), next);
                        }
                    }
                }
            }
        }
    }

