    #[test]
    fn upstream_loop_target_fault_preserves_count_for_retry() {
        for opcode in [0xe0, 0xe1, 0xe2] {
            for default16 in [false, true] {
                for address_override in [false, true] {
                    for operand_override in [false, true] {
                        let mut ram = Ram::new();
                        let mut code = std::vec::Vec::new();
                        if operand_override {
                            code.push(0x66);
                        }
                        if address_override {
                            code.push(0x67);
                        }
                        code.extend_from_slice(&[opcode, 4]);
                        ram.data[..code.len()].copy_from_slice(&code);
                        let mut cpu = flat_cpu_with_code_limit(0, code.len() as u32);
                        cpu.set_seg_cache(
                            SegmentReg::Cs,
                            SegmentCache {
                                flags: if default16 {
                                    0
                                } else {
                                    SEGMENT_FLAG_DEFAULT_BIG
                                },
                                ..cpu.seg(SegmentReg::Cs)
                            },
                        );
                        let address16 = default16 != address_override;
                        let count = if address16 { 0x1234_0002 } else { 2 };
                        cpu.set_reg(Reg32::Ecx, count);
                        cpu.eflags =
                            EFLAGS_CF | EFLAGS_OF | 2 | if opcode == 0xe1 { EFLAGS_ZF } else { 0 };
                        let flags = cpu.eflags;
                        step_gp(&mut cpu, &mut ram, 0);
                        assert_eq!(cpu.reg(Reg32::Ecx), count);
                        assert_eq!(cpu.eflags, flags);

                        // An exception handler fixes the segment and restarts
                        // the original instruction. Decrement only once.
                        cpu.set_seg_cache(
                            SegmentReg::Cs,
                            SegmentCache {
                                limit: 0xffff,
                                ..cpu.seg(SegmentReg::Cs)
                            },
                        );
                        cpu.eip = 0;
                        step_running(&mut cpu, &mut ram);
                        assert_eq!(cpu.reg(Reg32::Ecx), count - 1);
                        assert_eq!(cpu.eip, code.len() as u32 + 4);
                        assert_eq!(cpu.eflags, flags);
                    }
                }
            }
        }
    }

