    #[test]
    fn leave_page_fault_preserves_esp_for_restart() {
        let mut ram = Ram::new();
        ram.data[0] = 0xc9;
        ram.write_u32(0x2000, 0x3000 | 0x03);
        ram.write_u32(0x3000, 0x0000_0000 | 0x03);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.cr0 |= crate::x86::cpu::CR0_PG;
        cpu.cr3 = 0x2000;
        cpu.set_reg(Reg32::Ebp, 0x1000);
        cpu.set_reg(Reg32::Esp, 0x0200);

        let err = Interpreter::step(&mut cpu, &mut ram).unwrap_err();
        let Some(page) = err.page_fault() else {
            panic!("expected page fault");
        };

        assert_eq!(page.linear.0, 0x1000);
        assert_eq!(cpu.reg(Reg32::Esp), 0x0200);
    }

