    #[test]
    fn protected_int3_uses_interrupt_gate_and_pushes_32bit_frame() {
        let mut ram = Ram::new();
        ram.data[0] = 0xcc;
        ram.write_descriptor(1, 0x00cf_9a00);
        ram.write_idt_gate(0x300, 3, 0x08, 0x1234_5678, 0x8e);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x0f,
        };
        cpu.idtr = TableReg {
            base: 0x300,
            limit: 0x1ff,
        };
        cpu.set_seg_cache(
            SegmentReg::Ss,
            SegmentCache {
                base: 0x100,
                ..cpu.seg(SegmentReg::Ss)
            },
        );
        cpu.set_reg(Reg32::Esp, 0x20);
        cpu.eflags = EFLAGS_IF | EFLAGS_TF | EFLAGS_NT | EFLAGS_RF | EFLAGS_CF | 0x0000_0002;
        let old_flags = cpu.eflags;

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x1234_5678);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x08);
        assert_eq!(cpu.reg(Reg32::Esp), 0x14);
        assert_eq!(ram.read_u32(0x114), 1);
        assert_eq!(ram.read_u32(0x118), 0x10);
        assert_eq!(ram.read_u32(0x11c), old_flags);
        assert_eq!(
            cpu.eflags & (EFLAGS_IF | EFLAGS_TF | EFLAGS_NT | EFLAGS_RF),
            0
        );
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
    }

