    #[test]
    fn protected_int_to_inner_privilege_loads_tss_stack_and_pushes_old_stack() {
        let mut ram = Ram::new();
        ram.data[..2].copy_from_slice(&[0xcd, 0x80]);
        ram.write_descriptor(1, 0x00cf_9a00);
        ram.write_descriptor(2, 0x00cf_9200);
        ram.write_descriptor(3, 0x00cf_fa00);
        ram.write_descriptor(4, 0x00cf_f200);
        let (tss_low, tss_high) = descriptor_image(0x500, 0x0067, 0x89, 0x00);
        ram.write_descriptor_raw(5, tss_low, tss_high);
        ram.write_u32(0x504, 0x180);
        ram.write_u16(0x508, 0x10);
        ram.write_idt_gate(0x300, 0x80, 0x08, 0x2468, 0xee);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x2f,
        };
        cpu.idtr = TableReg {
            base: 0x300,
            limit: 0x7ff,
        };
        cpu.tr = 0x28;
        cpu.tr_cache = SegmentCache::new(0x28, 0x500, 0x67, 0x8b);
        cpu.set_seg_cache(
            SegmentReg::Cs,
            SegmentCache::flat(0x1b, SEGMENT_FLAG_DEFAULT_BIG),
        );
        cpu.set_seg_cache(
            SegmentReg::Ss,
            SegmentCache::flat(0x23, SEGMENT_FLAG_DEFAULT_BIG),
        );
        cpu.set_reg(Reg32::Esp, 0x100);
        cpu.eflags = EFLAGS_IF | EFLAGS_CF | 0x0000_0002;
        let old_flags = cpu.eflags;

        step_running(&mut cpu, &mut ram);

        assert_eq!(cpu.eip, 0x2468);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x08);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x10);
        assert_eq!(cpu.cpl(), 0);
        assert_ne!(ram.data[0x40 + 8 + 5] & 1, 0);
        assert_ne!(ram.data[0x40 + 16 + 5] & 1, 0);
        assert_eq!(cpu.reg(Reg32::Esp), 0x16c);
        assert_eq!(ram.read_u32(0x16c), 2);
        assert_eq!(ram.read_u32(0x170), 0x1b);
        assert_eq!(ram.read_u32(0x174), old_flags);
        assert_eq!(ram.read_u32(0x178), 0x100);
        assert_eq!(ram.read_u32(0x17c), 0x23);
        assert_eq!(cpu.eflags & EFLAGS_IF, 0);
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
    }

