    fn exception_entry_pc() -> (Cpu, Ram) {
        let mut ram = Ram::new();
        ram.write_descriptor(1, 0x00cf_9b00);
        ram.write_descriptor(2, 0x00cf_9300);
        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0x444, 0);
        cpu.set_seg_cache(SegmentReg::Cs, SegmentCache::flat(8, 0xc09b));
        cpu.set_seg_cache(SegmentReg::Ss, SegmentCache::flat(16, 0xc093));
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x17,
        };
        cpu.idtr = TableReg {
            base: 0x300,
            limit: 0x7ff,
        };
        cpu.set_reg(Reg32::Esp, 0x1000);
        (cpu, ram)
    }

    #[test]
    fn exception_entry_routes_nested_faults_and_preserves_event_identity() {
        // The first event encounters a non-present IDT gate. Observe which
        // handler actually receives control and its saved frame/error code.
        for (kind, first, target) in [
            (EventKind::Exception, 6, 11u8), // benign -> #NP
            (EventKind::Exception, 0, 8),    // #DE -> #NP => #DF
            (EventKind::Exception, 13, 8),   // #GP -> #NP => #DF
            (EventKind::Exception, 14, 8),   // #PF -> #NP => #DF
            (EventKind::External, 13, 11),   // IRQ vector 13 is not a #GP
            (EventKind::Software, 13, 11),   // nor is INT 13h
            (EventKind::Software, 8, 11),    // INT 8 is not a #DF
        ] {
            let (mut cpu, mut ram) = exception_entry_pc();
            ram.write_idt_gate(0x300, 8, 8, 0x800, 0x8e);
            ram.write_idt_gate(0x300, 11, 8, 0xb00, 0x8e);
            ram.write_idt_gate(0x300, first, 8, 0x900, 0x0e);
            deliver_interrupt_event(&mut cpu, &mut ram, first, 0x446, None, kind, 0x444).unwrap();
            assert_eq!(cpu.eip, u32::from(target) * 0x100);
            assert_eq!(cpu.reg(Reg32::Esp), 0xff0);
            let error = if target == 8 {
                0
            } else {
                u32::from(first) * 8 + 2 + u32::from(kind != EventKind::Software)
            };
            assert_eq!(ram.read_u32(0xff0), error);
            assert_eq!(ram.read_u32(0xff4), 0x444); // Original instruction, not INT's successor.
            assert_eq!(ram.read_u32(0xff8), 8);
            assert_ne!(ram.read_u32(0xffc) & EFLAGS_RF, 0);
        }
    }

    #[test]
    fn exception_entry_page_fault_order_keeps_cr2_and_page_walk_effects() {
        for (kind, first) in [
            (EventKind::Exception, 13),
            (EventKind::Exception, 14),
            (EventKind::Software, 13),
        ] {
            let (mut cpu, mut ram) = exception_entry_pc();
            ram.data.copy_within(0x40..0x58, 0x3040);
            cpu.gdtr.base = 0x3040;
            // Vector 13 is at 0xff8; vector 14 is at 0x1000. Put the initial
            // vector on an absent page and its eventual handler on a present
            // page. #GP -> #PF is serializable, but #PF -> #PF becomes #DF.
            cpu.idtr.base = 0xf90;
            cpu.cr0 |= CR0_PG;
            cpu.cr3 = 0x1000;
            cpu.set_reg(Reg32::Esp, 0x3800);
            ram.write_u32(0x1000, 0x2003);
            ram.write_u32(0x200c, 0x3003);
            let (target, code, cr2) = if first == 13 {
                ram.write_u32(0x2004, 3); // Linear page 1 -> physical page 0.
                ram.write_idt_gate(0, 0, 8, 0x3300, 0x8e);
                (0x3300, 0, 0xff8)
            } else {
                ram.write_u32(0x2000, 3);
                ram.write_idt_gate(0xf90, 8, 8, 0x3200, 0x8e);
                (0x3200, 0, 0x1000)
            };
            cpu.eip = 0x446; // INT decoding may already have advanced EIP.
            deliver_interrupt_event(&mut cpu, &mut ram, first, 0x446, Some(7), kind, 0x444)
                .unwrap();
            assert_eq!(cpu.eip, target);
            assert_eq!(cpu.cr2, cr2);
            assert_eq!(cpu.reg(Reg32::Esp), 0x37f0);
            assert_eq!(ram.read_u32(0x37f0), code);
            assert_eq!(ram.read_u32(0x37f4), 0x444);
            assert_ne!(ram.read_u32(0x1000) & TEST_PTE_ACCESSED, 0);
            assert_ne!(ram.read_u32(0x200c) & TEST_PTE_DIRTY, 0);
        }
    }

    #[test]
    fn exception_entry_distinguishes_cpu_shutdown_from_bus_implementation_errors() {
        let (mut cpu, mut ram) = exception_entry_pc();
        cpu.idtr.limit = 0;
        assert_eq!(
            deliver_exception(&mut cpu, &mut ram, 6, None, 0x444),
            Err(StepError::TripleFault {
                eip: 0x444,
                vector: 13,
                code: 0x43
            })
        );
        assert_eq!(cpu.reg(Reg32::Esp), 0x1000);
        assert_eq!(&ram.data[0xff0..0x1000], &[0; 16]);

        let (mut cpu, mut ram) = exception_entry_pc();
        cpu.idtr.base = 0x8000; // Outside this test bus, not a guest page fault.
        assert_eq!(
            deliver_exception(&mut cpu, &mut ram, 6, None, 0x444),
            Err(StepError::FaultOutOfRange {
                addr: PhysAddr(0x8030)
            })
        );
        assert_eq!(cpu.reg(Reg32::Esp), 0x1000);
    }

    #[test]
    fn exception_entry_uses_ltr_cache_but_reads_current_tss_stack() {
        for (access, ss_offset, frame_esp) in [(0x81, 4, 0x780), (0x89, 8, 0x900)] {
            let (mut cpu, mut ram) = exception_entry_pc();
            let (low, high) = descriptor_image(0x500, 0x67, access, 0);
            ram.write_descriptor_raw(5, low, high);
            cpu.gdtr.limit = 0x2f;
            cpu.set_reg(Reg32::Eax, 0x28);
            load_tr(&mut cpu, &mut ram, Rm32::Reg(Reg32::Eax), 0x444).unwrap();
            // Invalidate the GDT entry after LTR and only then fill SS0:ESP0.
            // Neither an uncached TR nor cached TSS contents can pass this.
            ram.write_descriptor_raw(5, 0, 0);
            ram.write_u16(0x500 + ss_offset, 16);
            if access == 0x89 {
                ram.write_u32(0x504, frame_esp);
            } else {
                ram.write_u16(0x502, frame_esp as u16);
            }
            ram.write_idt_gate(0x300, 0x20, 8, 0x800, 0x8e);
            cpu.set_seg_cache(SegmentReg::Cs, SegmentCache::flat(0x1b, 0xc0fb));
            cpu.set_seg_cache(SegmentReg::Ss, SegmentCache::flat(0x23, 0xc0f3));
            deliver_external_interrupt(&mut cpu, &mut ram, 0x20, 0x444).unwrap();
            assert_eq!(cpu.eip, 0x800);
            assert_eq!(cpu.seg(SegmentReg::Ss).selector, 16);
            assert_eq!(cpu.reg(Reg32::Esp), frame_esp - 20);
            assert_eq!(ram.read_u32((frame_esp - 4) as usize), 0x23);
            assert_eq!(ram.read_u32((frame_esp - 8) as usize), 0x1000);
            assert_eq!(ram.read_u32((frame_esp - 20) as usize), 0x444);
        }
    }

    #[test]
    fn interrupt_accessed_writes_follow_frame_accesses_and_precede_register_commit() {
        for (accessed, writable, bad_stack) in [
            (false, true, false),
            (false, false, false),
            (true, false, false),
            (false, false, true),
        ] {
            let (mut cpu, mut ram) = exception_entry_pc();
            ram.write_u32(0x1000, 0x2003);
            ram.write_u32(0x2000, 3);
            ram.write_u32(0x200c, 0x3001 | if writable { 2 } else { 0 });
            ram.write_u32(0x3008, 0xffff);
            ram.write_u32(0x300c, 0x00cf_9a00 | if accessed { 0x100 } else { 0 });
            ram.write_idt_gate(0x300, 0x20, 8, 0x900, 0x8e);
            cpu.gdtr.base = 0x3000;
            cpu.cr0 |= CR0_PG | crate::x86::cpu::CR0_WP;
            cpu.cr3 = 0x1000;
            if bad_stack {
                cpu.set_reg(Reg32::Esp, 0x3004);
            }
            let prior_esp = cpu.reg(Reg32::Esp);
            let result = enter_interrupt(&mut cpu, &mut ram, 0x20, 0x446, None, true, 0x444);
            if bad_stack || (!accessed && !writable) {
                let linear = LinearAddr(if bad_stack { 0x3000 } else { 0x300d });
                assert_eq!(
                    result,
                    Err(StepError::PageFault(mmu::PageFault { linear, code: 3 }))
                );
                assert_eq!(cpu.cr2, linear.0);
                assert_eq!(cpu.eip, 0x444);
                assert_eq!(cpu.reg(Reg32::Esp), prior_esp);
                assert_eq!(ram.data[0x300d] & 1, 0);
            } else {
                result.unwrap();
                assert_eq!(cpu.eip, 0x900);
                assert_eq!(cpu.reg(Reg32::Esp), 0xff4);
                assert_ne!(cpu.seg(SegmentReg::Cs).flags & 1, 0);
                assert_ne!(ram.data[0x300d] & 1, 0);
            }
            if !bad_stack {
                // Frame memory can already have changed on a later descriptor
                // write fault, while architectural ESP still restarts.
                assert_eq!(ram.read_u32(0xff4), 0x446);
                assert_eq!(ram.read_u32(0xff8), 8);
            }
            assert_eq!(
                ram.read_u32(0x200c) & 0x60,
                0x20 | if writable && !accessed { 0x40 } else { 0 }
            );
        }
    }

    #[test]
    fn exception_entry_stack_faults_precede_bad_target_and_keep_selector_ti() {
        for (ss, access, tss_limit, expected) in [
            (
                0,
                0x93,
                0x67,
                StepError::InvalidTss {
                    eip: 0x444,
                    code: 0,
                },
            ),
            (
                12,
                0x91,
                0x67,
                StepError::InvalidTss {
                    eip: 0x444,
                    code: 12,
                },
            ),
            (
                12,
                0x13,
                0x67,
                StepError::StackFault {
                    eip: 0x444,
                    code: 12,
                },
            ),
            (
                12,
                0x93,
                10,
                StepError::InvalidTss {
                    eip: 0x444,
                    code: 0x28,
                },
            ),
            (
                12,
                0x93,
                0x67,
                StepError::GeneralProtection {
                    eip: 0x444,
                    code: 0,
                },
            ),
        ] {
            let (mut cpu, mut ram) = exception_entry_pc();
            let (low, high) = descriptor_image(0, 0x10, 0x9b, 0x40);
            ram.write_descriptor_raw(1, low, high);
            let (low, high) = descriptor_image(0, 0xffff, access, 0x40);
            ram.write_u32(0xa08, low);
            ram.write_u32(0xa0c, high);
            cpu.ldtr = 0x30;
            cpu.ldtr_cache = SegmentCache::new(0x30, 0xa00, 15, 0x82);
            cpu.tr = 0x28;
            cpu.tr_cache = SegmentCache::new(0x28, 0x500, tss_limit, 0x8b);
            ram.write_u32(0x504, 0x900);
            ram.write_u16(0x508, ss);
            ram.write_idt_gate(0x300, 0x20, 8, 0x800, 0xee);
            cpu.set_seg_cache(SegmentReg::Cs, SegmentCache::flat(0x1b, 0xc0fb));
            cpu.set_seg_cache(SegmentReg::Ss, SegmentCache::flat(0x23, 0xc0f3));
            assert_eq!(
                enter_interrupt(&mut cpu, &mut ram, 0x20, 0x446, None, true, 0x444),
                Err(expected)
            );
            assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x23);
            assert_eq!(cpu.reg(Reg32::Esp), 0x1000);
            assert_eq!(&ram.data[0x8e0..0x900], &[0; 32]);
        }
    }

    #[test]
    fn vm86_exception_enters_ring0_with_extended_frame() {
        let mut ram = Ram::new();
        ram.write_descriptor(1, 0x00cf_9a00);
        ram.write_descriptor(2, 0x00cf_9200);
        let (tss_low, tss_high) = descriptor_image(0x500, 0x0067, 0x89, 0x00);
        ram.write_descriptor_raw(5, tss_low, tss_high);
        ram.write_u32(0x504, 0x180);
        ram.write_u16(0x508, 0x10);
        ram.write_idt_gate(0x300, 13, 0x08, 0x2468, 0x8e);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0x640, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x2f,
        };
        cpu.idtr = TableReg {
            base: 0x300,
            limit: 0x1ff,
        };
        cpu.tr = 0x28;
        cpu.tr_cache = SegmentCache::new(0x28, 0x500, 0x67, 0x8b);
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0x2000));
        cpu.set_seg_cache(SegmentReg::Ss, real_mode_segment(0x0030));
        cpu.set_seg_cache(SegmentReg::Es, real_mode_segment(0x1111));
        cpu.set_seg_cache(SegmentReg::Ds, real_mode_segment(0x2222));
        cpu.set_seg_cache(SegmentReg::Fs, real_mode_segment(0x3333));
        cpu.set_seg_cache(SegmentReg::Gs, real_mode_segment(0x4444));
        cpu.set_reg(Reg32::Esp, 0x1234);
        cpu.replace_eflags(
            EFLAGS_VM
                | EFLAGS_IOPL
                | EFLAGS_IF
                | EFLAGS_TF
                | EFLAGS_NT
                | EFLAGS_RF
                | EFLAGS_CF
                | 0x0000_0002,
        );
        let old_flags = cpu.eflags;

        deliver_exception(&mut cpu, &mut ram, 13, Some(0), 0x640).unwrap();

        assert_eq!(cpu.eip, 0x2468);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x08);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x10);
        assert_eq!(cpu.reg(Reg32::Esp), 0x158);
        assert_eq!(ram.read_u32(0x158), 0);
        assert_eq!(ram.read_u32(0x15c), 0x640);
        assert_eq!(ram.read_u32(0x160), 0x2000);
        assert_eq!(ram.read_u32(0x164), old_flags);
        assert_eq!(ram.read_u32(0x168), 0x1234);
        assert_eq!(ram.read_u32(0x16c), 0x0030);
        assert_eq!(ram.read_u32(0x170), 0x1111);
        assert_eq!(ram.read_u32(0x174), 0x2222);
        assert_eq!(ram.read_u32(0x178), 0x3333);
        assert_eq!(ram.read_u32(0x17c), 0x4444);
        assert_eq!(cpu.seg(SegmentReg::Es).selector, 0);
        assert_eq!(cpu.seg(SegmentReg::Ds).selector, 0);
        assert_eq!(cpu.seg(SegmentReg::Fs).selector, 0);
        assert_eq!(cpu.seg(SegmentReg::Gs).selector, 0);
        assert_eq!(
            cpu.eflags & (EFLAGS_VM | EFLAGS_IF | EFLAGS_TF | EFLAGS_NT | EFLAGS_RF),
            0
        );
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
    }

    #[test]
    fn vm86_software_int_uses_dpl3_gate_to_enter_ring0() {
        let mut ram = Ram::new();
        ram.write_descriptor(1, 0x00cf_9a00);
        ram.write_descriptor(2, 0x00cf_9200);
        let (tss_low, tss_high) = descriptor_image(0x500, 0x0067, 0x89, 0x00);
        ram.write_descriptor_raw(5, tss_low, tss_high);
        ram.write_u32(0x504, 0x180);
        ram.write_u16(0x508, 0x10);
        ram.write_idt_gate(0x300, 0x21, 0x08, 0x3456, 0xee);

        let mut cpu = Cpu::new();
        cpu.enter_protected_flat(0x640, 0);
        cpu.gdtr = TableReg {
            base: 0x40,
            limit: 0x2f,
        };
        cpu.idtr = TableReg {
            base: 0x300,
            limit: 0x1ff,
        };
        cpu.tr = 0x28;
        cpu.tr_cache = SegmentCache::new(0x28, 0x500, 0x67, 0x8b);
        cpu.set_seg_cache(SegmentReg::Cs, real_mode_segment(0x2000));
        cpu.set_seg_cache(SegmentReg::Ss, real_mode_segment(0x0030));
        cpu.set_reg(Reg32::Esp, 0x1234);
        cpu.replace_eflags(EFLAGS_VM | EFLAGS_IOPL | EFLAGS_IF | EFLAGS_CF | 0x0000_0002);
        let old_flags = cpu.eflags;

        deliver_software_interrupt_event(&mut cpu, &mut ram, 0x21, 0x642, 0x640).unwrap();

        assert_eq!(cpu.eip, 0x3456);
        assert_eq!(cpu.seg(SegmentReg::Cs).selector, 0x08);
        assert_eq!(cpu.seg(SegmentReg::Ss).selector, 0x10);
        assert_eq!(cpu.reg(Reg32::Esp), 0x15c);
        assert_eq!(ram.read_u32(0x15c), 0x642);
        assert_eq!(ram.read_u32(0x160), 0x2000);
        assert_eq!(ram.read_u32(0x164), old_flags);
        assert_eq!(ram.read_u32(0x168), 0x1234);
        assert_eq!(ram.read_u32(0x16c), 0x0030);
        assert_eq!(cpu.eflags & (EFLAGS_VM | EFLAGS_IF), 0);
        assert_ne!(cpu.eflags & EFLAGS_CF, 0);
    }

